(window.GIM_TS=window.GIM_TS||{})["Temurah.2"]={"from":48,"a":[["בהסבר מחלוקת ר' מאיר ור' יוסי במשנה \u0003אמר ר' יצחק בר' יוסי, אמר ר' יוחנן: הכל\u0004 (גם ר' מאיר וגם ר' יוסי) \u0003מודים ב\u0004מקרה שאדם \u0003אומר \"תחול זו\u0004 (תמורת עולה), \u0003ואחר כך תחול זו\u0004 (תמורת שלמים)\" — ל\u0003דברי הכל\u0004 אומרים אנו: \u0003תפוס\u0004 (אחוז כדבר המחייב) את ה\u0003לשון\u0004 ה\u0003ראשון\u0004 שאמר \"תמורת עולה\", וקדושת שלמים לא חלה אף לדעת ר' יוסי.","וכן הכל מודים כשאדם אומר \u0003\"לא תחול זו\u0004 (תמורת עולה) \u0003אלא אם כן חלתה\u0004 (חלה) \u0003זו\u0004 (תמורת שלמים)\" — שאומרים אנו כי \u0003תרווייהו קדשי\u0004 \u0005[שתיהן התקדשו,\u0006 שתי הקדושות, עולה ושלמים חלו\u0005],\u0006 אף לדעת ר' מאיר.","ו\u0003לא נחלקו\u0004 ר' מאיר ור' יוסי \u0003אלא\u0004 במקרה \u0003כגון\u0004 זה שב\u0003משנתינו,\u0004 ש\u0003אמר \"תמורת עולה תמורת שלמים\"\u0004 שבמקרה זה, \u0003ר' מאיר סבר: מדהוה ליה למימר\u0004 \u0005[מתוך שהיה לו לומר],\u0006 אם רצה להחיל את שתי הקדושות, \u0003\"תמורת עולה ושלמים\", ו\u0004אילו הוא \u0003אמר\u0004 במקום זה \u0003\"תמורת עולה תמורת שלמים\"\u0004 — \u0003הויא ליה\u0004 \u0005[הריהו]\u0006 נחשב \u0003כ\u0004אדם ה\u0003אומר \"תחול זו ואחר כך תחול זו\",\u0004 ומשום כך לא חלה אלא קדושת עולה, שאין קדושה חלה על קדושה.","\u0003ו\u0004אילו \u0003ר' יוסי סבר\u0004 שמתחילה נתכוון להחיל את שתי הקדושות, והסיבה שלא אמר \"תמורת עולה ושלמים\" — שכן \u0003אי אמר\u0004 \u0005[אם היה אומר]\u0006 \u0003\"תמורת עולה ושלמים\", הוה אמינא\u0004 \u0005[הייתי אומר,\u0006 מפרש\u0005]\u0006 את דבריו שרוצה שתהיה \u0003קדושה,\u0004 ואולם קדושתה תהא מתחלקת לשתיים, מחציתה כתמורת עולה ומחציתה כתמורת שלמים, \u0003ו\u0004משום כך \u0003אינה\u0004 יכולה להיות \u0003קריבה\u0004 על המזבח (שהרי אי אפשר להקריב חציה לקרבן זה וחציה לקרבן זה). לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו,\u0006 הוא אומר\u0005]\u0006 שבדבריו \"תמורת עולה תמורת שלמים\", התכוין לומר שתהא כולה עולה וכולה שלמים.","ודנים באופן אחר של תמורת שתי בהמות הקדש. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אדם \u0003האומר\u0004 על בהמת חולין שלו \u0003\"בהמה זו חציה תמורת עולה, וחציה תמורת שלמים\"\u0004 — התקדשה בהמה זו \u0003כולה\u0004 בקדושת עולה, ולכן \u0003תקרב עולה.\u0004 אלו \u0003דברי ר' מאיר. ו\u0004אילו \u0003חכמים אומרים: תרעה עד שתסתאב\u0004 (שיפול בה מום), \u0003ותימכר, ויביא בדמי חציה תמורת עולה, ובדמי חציה תמורת שלמים.\u0004","\u0003אמר ר' יוסי:\u0004 \u0003אם לכך נתכוון מתחלה, הואיל ואי אפשר\u0004 לאדם \u0003להוציא\u0004 מפיו \u0003שני שמות כאחת\u0004 (בבת אחת) — כל \u0003דבריו קיימין,\u0004 וחלה עליה אף קדושת שלמים. ושואלים: שיטת \u0003ר' יוסי היינו רבנן\u0004 \u0005[זוהי\u0006 שיטת \u0005חכמים],\u0006 ומה הוסיף בדבריו? ומשיבים: את הברייתא \u0003כולה ר' יוסי קתני לה\u0004 \u0005[הוא\u0006 ש\u0005שונה אותה],\u0006 ודברי חכמים שבה הם שיטת ר' יוסי.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 אדם האומר \u0003\"בהמה\u0004 זו תהא \u0003חציה עולה וחציה חטאת\"\u0004 — מאחר וכלל הוא ש\"תפוס לשון ראשון\" הרי חציה נעשה עולה. וכיון שמחצית בהמה הוא דבר שהנשמה תלויה בו, לפיכך \u0003כולה\u0004 קדושה בקדושת עולה, ולכן \u0003תיקרב עולה,\u0004 אלה \u0003דברי ר' מאיר.\u0004","\u0003ר' יוסי אומר:\u0004 חלה עליה אף קדושת חטאת, ולכן אינה קריבה כלל, אלא \u0003תמות,\u0004 שהרי אי אפשר להקריב בהמה אחת לשני קרבנות. \u0003ושוין\u0004 ר' מאיר ור' יוסי בדעתם \u0003באומר \"חציה חטאת וחציה עולה\"\u0004 — \u0003ש\u0004לדעת הכל \u0003תמות.\u0004","ומבררים: הלשון \u0003\"שוין\" מני\u0004 \u0005[\u0006ל\u0005מי היא\u0006 מתייחסת\u0005],\u0006 מי מהחכמים הוא המודה לחבירו באופן זה? — \u0003ר' מאיר\u0004 הוא, המודה לר' יוסי שבאופן זה דינה שתמות. ויש לשאול: והרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, ואין צורך להשמיענו כן. שהרי זו היא כשיטתו של ר' מאיר, שכיון שכבר חלה עליו קדושת אמירתו הראשונה, שוב לא חלה עליו קדושת אמירתו השניה. כך הוא במקרה שקדמה קדושת עולה לקדושת חטאת — שקרבה כעולה, וכך הוא במקרה שקדמה קדושת חטאת לקדושת עולה — שמתה!","ומשיבים: יש צורך להשמיענו זאת, שכן \u0003מהו דתימא\u0004 \u0005[\u0006היה מקום \u0005שתאמר]:\u0006 \u0003אי לאו דאשמעינן, הוה אמינא\u0004 \u0005[אם לא שהשמיענו,\u0006 שכך היא דעתו של ר' מאיר במקרה זה, \u0005הייתי אומר]\u0006 כי \u0003טעמא\u0004 \u0005[טעם]\u0006 שיטת \u0003ר' מאיר\u0004 הוא \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משום\u0004 שאומרים אנו \u0003\"תפוס לשון ראשון\",\u0004 שהאמירה הראשונה היא שמחילה את קדושתה, \u0003אלא היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של שיטת ר' מאיר — משום שהוא סבור כי \u0003חטאת מעורבת\u0004 בקדושה אחרת, דינה שהיא \u0003קריבה,\u0004 ומשום כך, באומר \"חציה עולה וחציה חטאת\" אמר ר' מאיר שקרבה (כעולה) אף שגם קדושת חטאת מעורבת בה.","\u0003ו\u0004מאותו טעם \u0003אפילו כי\u0004 \u0005[כאשר]\u0006 \u0003אמר \"חציה חטאת\" והדר\u0004 \u0005[וחזר]\u0006 ו\u0003אמר \"חציה עולה\"\u0004 — דינה שהיא \u0003קריבה.\u0004 לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 התנא בברייתא \u0005משמיע לנו]\u0006 ש\u0003לא\u0004 כך הוא הדין, ובאופן זה מודה ר' מאיר לר' יוסי שאין היא קריבה, אלא מתה.","ועוד בענין דומה, \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אמר \"בהמה זו חציה עולה וחציה שלמים\"\u0004 — הריהי \u0003קדושה, ו\u0004אולם \u0003אינה קריבה,\u0004 אלא הריהי רועה עד שיפול בה מום ותיפסל מהקרבה, ואזי תימכר, ויביא בדמי חציה עולה ובדמי חציה שלמים. ועוד מדיניה של בהמה זו: הריהי \u0003עושה תמורה\u0004 (כלומר, שאם המירו בה בהמת חולין — חלו עליה דיני התמורה), \u0003ו\u0004דינה של \u0003תמורתו כיוצא בו,\u0004 שאף תמורתה אינה קרבה אלא הריהי רועה עד שיפול בה מום, ותימכר, וחוצים את דמיה לעולה ושלמים.","ושואלים: והרי \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? — כשיטת \u0003ר' יוסי היא,\u0004 הסבור שחלה על הבהמה קדושת שתי אמירותיו, ולא כשיטת ר' מאיר, ואם כן הרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר לשיטת ר' יוסי ש\u0003קדושה ואינה קריבה,\u0004 ואין צורך להשמיענו זאת!","ומשיבים: דין \u0003תמורתה איצטריך ליה\u0004 \u0005[הוצרך לו]\u0006 להשמיענו, שאף היא אינה קריבה. שכן \u0003מהו דתימא\u0004 \u0005[\u0006היה מקום \u0005שתאמר]:\u0006 \u0003נהי\u0004 \u0005[אמנם]\u0006 \u0003היא\u0004 עצמה \u0003לא קרבה\u0004 — אבל \u0003תמורתה תקרב,\u0004 לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאף תמורתה אינה קריבה. וטעם הדבר: \u0003מאי שנא\u0004 \u0005[במה שונה,\u0006 מיוחדת\u0005]\u0006 \u0003היא\u0004 עצמה \u0003דלא\u0004 \u0005[שאינה]\u0006 \u0003קרבה\u0004 — משום \u0003דהויא לה\u0004 \u0005[שהריהי]\u0006 \u0003קדושה דחויה,\u0004 שהרי אינה כולה עולה או שלמים, ואם כן \u0003תמורתה נמי\u0004 \u0005[גם כן]\u0006 — \u0003מכח קדושה דחויה קאתיא\u0004 \u0005[היא באה],\u0006 ולכן אינה קריבה.","ועוד בדין הקדש שני חצאיה של בהמה. \u0003אמר ר' יוחנן:\u0004 היתה \u0003בהמה של שני שותפים,\u0004 ועמד אחד השותפים ו\u0003הקדיש\u0004 בתחילה את \u0003חציה שלו, ו\u0004לאחר מכן \u0003חזר ולקח\u0004 (קנה) משותפו את \u0003חציה\u0004 ה\u0003אחרת, והקדישה\u0004 — דינה שהיא \u0003קדושה ו\u0004אולם \u0003אינה קריבה,\u0004 שהרי כאשר הקדיש את חציה הראשון לא היתה ראויה להקרבה, וכיון שנדחתה מהקרבה שוב אינה חוזרת להכשרה להיות מוקרבת אף שעתה היא ראויה להקרבה, \u0003ו\u0004הריהי \u0003עושה תמורה, ותמורתה\u0004"],["\u0003כיוצא בה,\u0004 שאף היא קדושה ואינה קריבה. ו\u0003שמע מינה תלת\u0004 \u0005[למד ממנה,\u0006 מהלכה זו, \u0005שלושה\u0006 דברים\u0005]\u0006 לענין דין הדחיה בהקדש: \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי אף הקדוש ב\u0003קדושת דמים נדחה,\u0004 כלומר, אפילו בדבר שלא נתקדש בקדושת הגוף אלא בקדושת דמים (שדמיו יהיו עבור קרבן), שהרי כשהקדיש חצי בהמה — הקדישה רק לדמיה, שהרי אי אפשר לו להקריב חצי בהמה.","\u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 עוד כי \u0003בעלי (חיים.\u0004 ראה בגרסות\u0003)\u0004 הריהם \u0003נדחין,\u0004 שקרבנות שנדחו מפני טעם כלשהו מלהיקרב על גבי המזבח אף בהיותם חיים, שוב אינם יכולים להיקרב. ולא כדעת הסוברים שאין דחיה אלא בקרבנות שנשחטו בלבד. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 עוד כי גם דבר שהיה בו \u0003דיחוי מעיקרו\u0004 (מתחילתו, מראשית הקדשתו) \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003דיחוי,\u0004 ואין אומרים שאין דין דחיה אלא בדבר שהיה ראוי מתחילתו ואחר כך נדחה. שהרי בהמה זו היתה דחויה מתחילה, משעה שהקדיש את חציה.","ועוד בדינו של המקדיש שתי קדושות על בהמה אחת. \u0003אמר אביי: הכל מודים היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003אמר\u0004 \"בהמה זו \u0003\"חציה\u0004 תהא \u0003עולה וחציה\u0004 תהא \u0003מעשר\"\u0004 — של \u0003דברי הכל\u0004 חלה עליה קדושת \u0003עולה\u0004 בלבד, ולא קדושת מעשר, שהרי אין קדושת מעשר בהמה חלה אלא באופן זה של הוצאת הבהמות מהדיר ובהעברתן תחת השבט, ולא בהקדשה כשלעצמה. ולכן הריהי איפוא \u0003קריבה\u0004 כעולה לכל דבר.","ואולם \u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003אמר\u0004 על בהמת חולין העומדת לפניו \"בהמה זו \u0003חציה\u0004 תהא \u0003תמורה\",\u0004 אבל אין בהמת ההקדש עומדת לפניו — והרי זו איפוא תמורה שאינה כראוי. והוסיף \u0003ו\u0004אמר עוד \u0003\"חציה\u0004 תהא \u0003מעשר\",\u0004 ואף הקדשה זו אינה כראוי, שהרי לא נעשתה כדרך הקדשת מעשר בהמה, ומעתה יש לשאול \u0003מאי\u0004 \u0005[מה]\u0006 הדין, איזו משתי הקדושות הללו עדיפה?","וצדדי השאלה: האם כ\u0003תמורה\u0004 היא \u0003קריבה\u0004 — \u0003שכן נוהגת\u0004 התמורה \u0003בכל הקדשים, או דלמא\u0004 \u0005[שמא]\u0006 כ\u0003מעשר\u0004 היא \u0003קרובה\u0004 (קריבה), \u0003שכן\u0004 יש חומרה מיוחדת היא במעשר בהמה, שהריהו \u0003מקדיש\u0004 (מחיל קדושת מעשר) אף על זה ש\u0003לפניו ולאחריו,\u0004 שאם טעה מונה הבהמות ביציאתן מן הדיר וקרא לתשיעי \"עשירי\", או שקרא לאחד עשר \"עשירי\" — הרי אף הם קדושים. ומסכמים: לא נמצא לבעיה זו פתרון, ולפיכך \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","המשנה דנה בלשון המועילה בתמורה. היו לפניו שתי בהמות, האחת של חולין והשניה של הקדש, ואמר: \u0003\"הרי זו\u0004 (בהמת החולין) \u0003תחת זו\u0004 (בהמת ההקדש)\", וכן אם אמר \"הרי זו \u0003תמורת זו\",\u0004 או אם אמר \"הרי זו \u0003חליפת זו\"\u0004 — בכל האופנים הללו \u0003הרי זו תמורה,\u0004 שכל אלה לשונות תמורה הן. ואולם אם אמר \"הרי \u0003זו מחוללת על זו\"\u0004 — \u0003אין זו תמורה,\u0004 שאין זו לשון תמורה, אלא לשון חילול.","\u0003ואם היה\u0004 בהמת ה\u0003הקדש\u0004 שאמר עליה \"זו מחוללת על זו\" \u0003בעל מום,\u0004 ועומדת להתחלל — הריהו בכך \u0003יוצא לחולין\u0004 מן התורה \u0003ו\u0004אולם מדברי סופרים \u0003צריך לעשות דמים\u0004 (הערכה כספית), כמה היא שווה. שאם היתה בהמת ההקדש יקרה יותר משוויה של בהמת החולין — על הבעלים להוסיף להקדש את ההפרש, שלא יימצא ההקדש נפסד.","שנינו במשנה כי האומר \"זו תחת זו\" הריהי מכלל לשונות התמורה. ושואלים על כך: \u0003למימרא\u0004 \u0005[האם לומר,\u0006 נלמד מכאן\u0005]\u0006 שהלשון \u0003\"תחת\" לישנא דאתפוסי\u0004 \u0005[לשון של התפסה,\u0006 האצלת קדושה מדבר לדבר\u0005]\u0006 \u0003הוא, ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על כך ממה ששנינו בברייתא: היתה בהמת חולין שלו עומדת לפני בהמת \u0003קדשי בדק הבית,\u0004 ו\u0003אמר\u0004 \"הרי בהמה זו \u0003חליפת\u0004 בהמה \u0003זו\"\u0004 או שאמר \"הרי בהמה זו \u0003תמורת זו\"\u0004 — \u0003לא אמר כלום.\u0004 שכן אלו לשונות של תמורה, ואין ממירים בקדשי בדק הבית.","ואולם אם אמר \"הרי זו \u0003תחת זו\"\u0004 או שאמר \"הרי זו \u0003מחוללת על זו\"\u0004 — \u0003דבריו קיימין.\u0004 שהתחללו בכך קדשי בדק הבית על בהמת החולין.","\u0003ו\u0004מעתה יש לשאול: \u0003אי סלקא דעתך לישנא דאיתפוסי\u0004 \u0005[אם עולה על דעתך\u0006 לומר כי \"תחת\" \u0005לשון של התפסה]\u0006 \u0003היא,\u0004 ומשום כך מועילה היא בדין התמורה כאמור במשנה, אם כן \u0003מאי שנא רישא\u0004 \u0005[במה שונה\u0006 הלשונות הנזכרים ב\u0005תחילת\u0006 הברייתא\u0005],\u0006 \"חליפי\", \"תמורת\", שאין הם מועילים לחילול קדשי בדק הבית כיון שלשון התפסה הם, \u0003ומאי שנא סיפא\u0004 \u0005[ובמה שונה\u0006 הלשון שב\u0005סוף\u0006 הברייתא, \"תחת\"\u0005]\u0006 שאף שהיא לשון התפסה הריהי מועילה לחילול קדשי בדק הבית?","\u0003אמר אביי:\u0004 הלשון \u0003\"תחת\"\u0004 — פעמים \u0003משכחת לה לישנא דאיתפוסי\u0004 \u0005[מוצא אתה אותה\u0006 משמשת כ\u0005לשון התפסה],\u0006 \u0003ו\u0004פעמים הריהי משמשת כ\u0003לישנא דאחולי\u0004 \u0005[לשון חילול].\u0006 ומפרט: \u0003לישנא דאתפוסי\u0004 \u0005[לשון התפסה]\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006"],["\u0003\"ואם תחתיה תעמד הבהרת\"\u0004 (ויקרא יג, כג), הרי שלשון \"תחת\" משמש במובן של הישארות דבר במקומו. וכן הוא עיקרה של התפסת התמורה שאף שבהמת החולין מתקדשת בה, קדושת בהמת ההקדש עומדת במקומה.","ולשון \u0003דאחולי\u0004 \u0005[של חילול,\u0006 החלפת הדבר\u0005]\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"תחת הנחשת אביא זהב\u0004 ותחת הברזל אביא כסף ותחת העצים נחושת ותחת האבנים ברזל\" (ישעיה ס, יז), הרי שמשמשת הלשון \"תחת\" במובן של החלפת הדבר בדבר אחר. \u0003והלכך\u0004 \u0005[ומשום כך]\u0006 נקבע מובנה על פי הנסיבות שבהן היא נאמרה. ולכן, \u0003גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 \u0003קדשי מזבח, דעבדין\u0004 \u0005[שעושים]\u0006 \u0003תמורה\u0004 — \u0003לישנא דאתפוסי\u0004 \u0005[לשון התפסה]\u0006 \u0003הוא.\u0004 ואילו \u0003גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 \u0003קדשי בדק הבית, דלא עבדין\u0004 \u0005[שאין\u0006 הם \u0005עושים]\u0006 \u0003תמורה\u0004 — \u0003לישנא דאחולי\u0004 \u0005[לשון חילול]\u0006 \u0003הוא.\u0004","\u0003אמר רבא: אפילו בקדשי מזבח,\u0004 שדינם שהם עושים תמורה, פעמים \u0003משכחת לה לישנא דאחולי\u0004 \u0005[מוצא אתה\u0006 כי לשון \"תחת\" \u0005לשון\u0006 של \u0005חילול]\u0006 \u0003הוא.\u0004 ומסביר את דבריו: \u0003כגון שהיה\u0004 קרבן ה\u0003הקדש בעל מום,\u0004 שאין הוא עומד להקרבה אלא לפדיון, והמיר עליו בהמת חולין בלשון \"הרי זו תחת זו\" — אף שחל דין התמורה, שהרי אף שהיא בעלת מום מכל מקום קדושה היא בקדושת מזבח וראויה לעשות תמורה, ואף על פי כן הריהי מתחללת בלשון זו.","\u0003אמר רב אשי: אפילו ב\u0004אופן זה שהביא רבא, שהיה קרבן ההקדש \u0003בעל מום\u0004 \u0003נמי משכחת לה לישנא דאחולי, ומשכחת לישנא דאתפוסי\u0004 \u0005[גם כן,\u0006 יש ו\u0005מוצא אתה\u0006 שהיא משמשת ב\u0005לשון חילול,\u0006 ויש ו\u0005מוצא אתה\u0006 שהיא משמשת ב\u0005לשון התפסה].\u0006 ומפרט את דבריו: אם אמר \"זו תחת זו\" כאשר \u0003ידו\u0004 היתה מונחת \u0003אקודש\u0004 \u0005[על\u0006 בהמת \u0005הקודש]\u0006 — לשון \u0003חול הוי\u0004 \u0005[הריהו],\u0006 שהרי ניכרים הדברים שכוונתו שבהמת ההקדש תתחלל על בהמת החולין. ואם אמר \"זו תחת זו\" כאשר \u0003ידו\u0004 היתה מונחת \u0003אחול\u0004 \u0005[על\u0006 בהמת \u0005החול]\u0006 — לשון \u0003קודש הוה\u0004 \u0005[הריהו],\u0006 שהרי ניכר הדבר שכוונתו שבהמת החול תתקדש בקדושת בהמת ההקדש.","ועוד באותו ענין \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי: היו\u0004 עומדות \u0003לפניו שתי בהמות של קדש\u0004 שהן \u0003בעלות מום, ושתי בהמות של חולין תמימות,\u0004 \u0003ואמר \"הרי אלו תחת אלו\",\u0004 בלא שהניח ידיו על אלו או על אלו, \u0003מהו\u0004 הדין?","וצדדי השאלה: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר\u0004 (התכוון) בכך \u0003לאתפוסי\u0004 \u0005[להתפיס]\u0006 את קדושת שתי בהמות ההקדש על שתי בהמות החולין, כדין התמורה — \u0003ולקי\u0004 \u0005[ולוקה]\u0006 הוא פעמיים מלקות על כך, כשאר הממירים שלוקים. \u0003או דלמא\u0004 \u0005[שמא]:\u0006 כיון שיתכן שלחלל את בהמת ההקדש בעלת המום על בהמת החולין הוא מתכוין, שכן כלל הוא כי \u0003כל היכא דאיכא היתרא\u0004 \u0005[היכן שיש\u0006 אפשרות שייעשה הדבר ב\u0005היתר]\u0006 ואפשרות שייעשה הדבר באיסור — \u0003לא שביק איניש היתרא ועביד איסורא\u0004 \u0005[אין אדם עוזב\u0006 את ה\u0005היתר ועושה איסור],\u0006 ואף כאן לא היתה כוונתו אלא לחלל את שתי בהמות ההקדש, ואין הוא לוקה על כך?","\u0003ו\u0004הוסיף אביי ושאל: \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003כל היכא דאיכא היתרא, לא שביק איניש ועביד איסורא\u0004 \u0005[היכן שיש היתר, אין אדם עוזב היתר ועושה איסור],\u0006 ונסכם איפוא בבעיה הקודמת שאין הוא לוקה, שכן כוונתו היתה לחילול, עדיין יש לדון במקרה ש\u0003היו\u0004 עומדות \u0003לפניו שתי בהמות של קודש, ו\u0004רק \u0003אחת מהן בעלת מום,\u0004 והשניה תמימה. \u0003ו\u0004כן עמדו לפניו \u0003שתי בהמות של חולין, ו\u0004רק \u0003אחת מהן בעלת מום,\u0004 והשניה היא תמימה. \u0003ואמר \"הרי אלו תחת אלו\", מהו\u0004 הדין?","והרי אף שברור שבבהמת ההקדש התמימה חלה לשון \"תחת\" במובן של התפסה בתמורה, ואולם אין זה ברור באיזו מבהמות החולין החיל את התמורה הזו, ואלו צדדי השאלה: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר\u0004 (התכוון בדבריו) שבהמת החולין ה\u0003תמימה\u0004 תהיה \u0003תחת\u0004 בהמת ההקדש ה\u0003תמימה\u0004 — ונמצא כי \u0003לאתפוסי\u0004 \u0005[להתפסה]\u0006 אותה בתמורה התכוון (ולוקה על כך), ואילו \u0003בעלת מום\u0004 של החולין תהיה \u0003תחת בעלת מום\u0004 של הקדש — ואין זו לשון התפסת תמורה, אלא \u0003לאחולי\u0004 \u0005[לחילול]\u0006 התכוון (ואין הוא לוקה על כך).","\u0003או דלמא\u0004 \u0005[שמא]\u0006 כוונתו היתה שהבהמה ה\u0003תמימה\u0004 של \u0003חולין\u0004 תהיה \u0003תחת בעלת מום\u0004 של \u0003הקדש,\u0004 והרי זו התפסת תמורה, שכך הוא מדין התמורה שהממיר בעלת מום בתמימה — הריהי תמורה (ולוקה על כך), ושתהיה \u0003בעלת מום\u0004 של \u0003חולין\u0004 — \u0003תחת תמימה\u0004 של \u0003הקדש,\u0004 ואף זו לשון התפסה, שהרי אף בכך חל דין התמורה שהממיר תמימה בבעלת מום — הריהי תמורה (ולוקה על כך), \u0003ו\u0004נמצא שעל \u0003תרוייהו לקי\u0004 \u0005[שתיהן לוקה]? ו\u0006","הוסיף ושאל אביי: אף \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003כל היכא דאיכא היתירא\u0004 \u0005[היכן שיש היתר]\u0006 — \u0003לא עביד איסורא\u0004 \u0005[אין\u0006 אדם \u0005עושה איסור],\u0006 \u0003ולאחולי\u0004 \u0005[ולחילול]\u0006 \u0003הוא\u0004 מתכוין, \u0003ולא לקי\u0004 \u0005[ואינו לוקה]\u0006 על כך פעמיים מלקות, אלא אחת, עדיין יש לדון במקרה ש\u0003היו\u0004 עומדות \u0003לפניו שלש בהמות של קדש ואחת מהן\u0004 \u0003בעלת מום,\u0004 והשתיים האחרות תמימות. \u0003ו\u0004כן \u0003שלשה בהמות של חולין\u0004 שכולן \u0003תמימות, ואמר \"הרי אלו תחת אלו\",\u0004 מה הדין?","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003מ\u0004תוך שבוודאי כוונתו לומר ששתי ה\u0003תמימות\u0004 של החולין תהיינה \u0003תחת\u0004 שתי ה\u0003תמימות\u0004 של הקדש, ו\u0003ל\u0004משמעות \u0003אתפוסי\u0004 \u0005[התפסה]\u0006 בדין התמורה, כדינה הרגיל של לשון \"תחת\" התכוון — ודאי התכוין שהבהמה השלישית משלש ה\u0003תמימות\u0004 של החולין \u0003נמי\u0004 \u0005[גם כן]\u0006 תהיה \u0003תחת בעלת מום\u0004 של ההקדש — ו\u0003ל\u0004משמעות \u0003אתפוסי\u0004 \u0005[להתפסה]\u0006 בתמורה התכוין, והריהו איפוא לוקה על שלש תמורות. \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אומרים אנו את הכלל ש\u0003כל היכא דאיכא היתירא, לא עביד איסורא\u0004 \u0005[כל היכן שיש היתר, אין\u0006 אדם \u0005עושה איסור],\u0006 \u0003ו\u0004לכן יש לומר שכוונתו ב\u0003ההיא בתרייתא\u0004 \u0005[באותה\u0006 בהמה \u0005אחרונה]\u0006 שמבין שלוש התמימות של חולין — \u0003לאחולי הוי\u0004 \u0005[לחילול\u0006 בהמת ההקדש \u0005הריהי],\u0006 ולא להמרה, ואין הוא לוקה על כך.","ו\u0003אם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003הכא נמי\u0004 \u0005[כאן,\u0006 באופן של הבעיה הקודמת \u0005גם כן]\u0006 אין הוא לוקה על השלישית, וטעם הדבר: שכן \u0003כיון דאכתי גברא\u0004 \u0005[שעדיין אדם]\u0006 זה \u0003לא איתחזק באיסורי\u0004 \u0005[הוחזק באיסורים,\u0006 כמי שרגיל לעבור על איסורים\u0005]\u0006 שהרי טרם עבר על איסור שלוש פעמים, שיש בהן כדי חזקה, ומשום כך אומרים אנו בו את הכלל כי \u0003לא שביק התירא ועביד איסורא\u0004 \u0005[אין\u0006 אדם \u0005מניח היתר ועושה איסור].\u0006 ומעתה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: היו\u0004 עומדות \u0003לפניו ארבע בהמות של קדש\u0004 שלוש מהן תמימות, \u0003ואחת מהן\u0004 היא \u0003בעלת מום, ו\u0004כן עמדו לפניו \u0003ארבע בהמות\u0004 תמימות \u0003של חולין, ואמר \"הרי אלו תחת אלו\" מהו\u0004 הדין?","וצדדי השאלה: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי כיון דאיתחזק גברא באיסורי\u0004 \u0005[שהוחזק האדם באיסורים],\u0006 שהרי ודאי בשלוש התמימות של ההקדש המיר — והרי איפוא יש לומר שאף בבהמת ההקדש הרביעית, בעלת המום, גם כן המיר, והריהו \u0003(בכולן) לקי\u0004 \u0005[לוקה]\u0006 \u0003בארבע\u0004 סדרות של \u0003מלקיות.\u0004","\u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003אף על גב דאיתחזק באיסורא\u0004 \u0005[אף על פי שהוחזק\u0006 אדם זה \u0005באיסור],\u0006 וממעשיו נראה שאין הוא נרתע מלעבור עבירה, ואולם עדיין כלל הוא אף לגבי אדם שכזה ש\u0003לא שביק איניש היתירא ועביד איסורא\u0004 \u0005[אין אדם מניח היתר ועושה איסור],\u0006 \u0003והוי בתרייתא לאחולי הוי\u0004 \u0005[והרי\u0006 כוונתו לגבי הבהמה \u0005האחרונה,\u0006 הרביעית של ההקדש \u0005לחילול הריהי]?\u0006 ומסכמים: לא נמצא פתרון לכל הבעיות הללו, ולכך \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","שנינו במשנה שהאומר \"הרי זו (בהמת חולין) מחוללת על זו (בהמת הקדש)\", \u0003אם היתה\u0004 בהמת ה\u0003הקדש בעל מום\u0004 — \u0003יצא לחולין,\u0004 ואולם צריך להעריך את שוויה של בהמת ההקדש, ואם הוא עולה על שווי בהמת החולין — צריך להשלים להקדש את ההפרש שביניהן (\"לעשות דמים\"). ובהסברן של שתי הלכות אלה נחלקו חכמים.","\u0003אמר ר' יוחנן:\u0004 דין זה ש\u0003יצא\u0004 ההקדש \u0003לחולין\u0004 — הריהו \u0003דבר תורה,\u0004 שכן מן התורה אפילו הקדש השווה מאה מנה שחולל על שווה פרוטה — הריהו מחולל בכך. \u0003ו\u0004אילו דין זה ש\u0003צריך לעשות דמים\u0004 — הריהו \u0003מדבריהם\u0004 של חכמים, שתקנו כן על מנת שלא יפסיד ההקדש. \u0003ו\u0004אילו \u0003ריש לקיש אמר: אף\u0004 דין זה ש\u0003צריך לעשות דמים\u0004 — הריהו \u0003דבר תורה.\u0004","ודנים במחלוקתם: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה אופן, \u0005אנו עוסקים\u0006 כאן\u0005]\u0006 במחלוקת זו? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שעוסקים אנו במקרה שההבדל בין הערך הממשי של בהמת ההקדש, ובין ערך הבהמה שניתנה כפדיון, היה עד כדי ששית (שתות) ולא יותר, שהוא הפרש המחיל דין \u0003אונאה\u0004 (שהמקח נקנה ואולם צריך המאנה להשיב את הפרש הדמים) — האם \u0003בהא נימא\u0004 \u0005[בזה יאמר]\u0006 \u0003ריש לקיש\u0004 ש\u0003אף\u0004 דין זה שבמשנתנו ש\u0003צריך לעשות דמים\u0004 הוא \u0003דבר תורה?\u0004","\u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת בבא מציעא\u0005]:\u0006 \u0003אלו דברים שאין להם\u0004 דין \u0003אונאה: העבדים, והשטרות, והקרקעות, וההקדשות,\u0004 הרי איפוא שאין ההקדש בכלל דיני האונאה, ולמה נדרש הוא להחזיר להקדש את הפרש הדמים?","\u0003אלא\u0004 אם נאמר שמחלוקת זו בין ר' יוחנן לריש לקיש הריהי במקרה שהיה הפרש הדמים יותר משישית שבכגון זה יש כבר \u0003בטול מקח,\u0004 שבכך מתבטלת בכך המכירה, ואולם באופן זה יש לשאול, לכיוון ההפוך: וכי \u0003בהא נימא\u0004 \u0005[בזה יאמר]\u0006 \u0003ר' יוחנן\u0004 שדין זה ש\u0003צריך לעשות דמים\u0004 הוא \u0003מדבריהם\u0004 של חכמים?"],["\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' ירמיה\u0004 על המשנה המונה את הדברים שאין בהם דין אונאה כי מבין כל אלה מיוחד הוא דין ה\u0003קרקעות\u0004 של \u0003חולין, ור' יונה אמר\u0004 זאת על דין ה\u0003הקדשות.\u0004 ו\u0003תרווייהו משמיה\u0004 \u0005[שניהם בשמו]\u0006 של \u0003ר' יוחנן אמרי\u0004 \u0005[אמרו]\u0006 זאת, שמיוחד אותו הדבר (הקרקעות או ההקדשות) בכך שאמנם דין \u0003אונאה\u0004 אם היתה עד כדי שתות — \u0003אין להן,\u0004 אבל דין \u0003ביטול מקח\u0004 אם היתה יותר משתות — \u0003יש להם.\u0004 נמצא שלדעת ר' יונה שיטת ר' יוחנן היא שיש ביטול מקח בהקדשות מן התורה, ומדוע נאמר משמו כי השבת הדמים היא רק מדברי חכמים?","ומשיבים: \u0003לעולם\u0004 תפרש כי מחלוקת זו של ר' יוחנן וריש לקיש היא בהפרש שיש בו כדי \u0003ביטול מקח\u0004 (שתות), \u0003ו\u0004אולם \u0003איפוך\u0004 \u0005[הפוך]\u0006 את שמות האומרים את השיטות, שהדעה שיוחסה לר' יוחנן הריהי של ריש לקיש, וזו שיוחסה לריש לקיש הריהי של ר' יוחנן. ונמצא איפוא שדעת ר' יוחנן במחלוקת זו שדין השבת הדמים הוא מן התורה.","ושואלים על כך: \u0003ומי מצית אמרת איפוך\u0004 \u0005[והאם יכול אתה לומר\u0006 שיש \u0005להפוך]\u0006 את שמות בעלי השיטות? \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח למי שאומר,\u0006 ר' יונה\u0005]\u0006 את דברי ר' יוחנן (אונאה אין להם, ביטול מקח יש להם) בענין ה\u0003הקדשות, ו\u0004אם כן, \u0003כל שכן\u0004 שכך הוא הדין אף בענין \u0003קרקעות.\u0004","\u0003אלא למאן דאמר\u0004 \u0005[למי שאומר,\u0006 ר' ירמיה\u0005]\u0006 כי דווקא בענין ה\u0003קרקעות\u0004 הוא שאמר ר' יוחנן שיש להם ביטול מקח, \u0003אבל\u0004 בענין ה\u0003הקדשות אין להן ביטול מקח, היכי איפוך להא\u0004 \u0005[איך אהפוך את זה]\u0006 שאמר ר' יוחנן על משנתנו בדין השבת הדמים ותאמר שהנוסח הוא \"דבר תורה\"? ומסבירים: כך \u0003אמר ר' ירמיה:\u0004 לשיטתי אכן \u0003לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 את דברי ר' יוחנן וריש לקיש שעל משנתנו, ונשארו דברי ר' יוחנן שאין דין השבת דמים מדין תורה. שכן להקדשות אין דין ביטול מקח. ור' יונה הוא שהופך שיטותיהם לטעמו ועל פי זה מתיישבת שיטתו.","","ומציעים בהסבר מחלוקת זו שנחלקו ר' ירמיה ור' יונה, שלדעת ר' ירמיה אין דין ביטול מקח בהקדש ולדעת ר' יונה יש דין ביטול מקח בהקדש: \u0003לימא\u0004 \u0005[אמור]\u0006 כי \u0003ב\u0004שיטתו של \u0003שמואל קא מיפלגי\u0004 \u0005[הם חולקים].\u0006 ש\u0003אמר שמואל: הקדש\u0004 ש\u0003שוה מנה שחיללו על שוה פרוטה,\u0004 והרי זה הפרש דמים גדול עד מאוד — הריהו \u0003מחולל.\u0004 ובכך נחלקו, ש\u0003ר' יונה\u0004 — \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את שיטתו זו של \u0003שמואל,\u0004 שסבור הוא שיש ביטול מקח להקדש. \u0003ו\u0004אילו \u0003ר' ירמיה\u0004 — \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את שיטת \u0003שמואל,\u0004 שסבור הוא שאין דין ביטול מקח בהקדש.","ודוחים: \u0003לא,\u0004 אין צורך להעמיד כך את מחלוקתם, אלא \u0003בין דמר\u0004 \u0005[לחכם זה]\u0006 \u0003ובין דמר\u0004 \u0005[לחכם זה]\u0006 — \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את שיטת \u0003שמואל,\u0004 ואולם בזאת נחלקו, ש\u0003ר' יונה סבר: כי\u0004 \u0005[כאשר]\u0006 \u0003אמר שמואל\u0004 את שיטתו זו — הרי זה דווקא ב\u0003דיעבד\u0004 (משכבר נעשה מעשה), שאם נתאנה ההקדש ביותר משתות אין המקח בטל, \u0003אבל לכתחלה\u0004 — \u0003לא אמר\u0004 שיהא מותר לאנות את ההקדש ביותר משתות. \u0003ו\u0004אילו \u0003ר' ירמיה סבר: אפילו לכתחלה\u0004 אמר שמואל שמותר לאנות את ההקדש ביותר משתות.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003לעולם לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 את דברי ר' יוחנן וריש לקיש בדין השבת דמים שבמשנתנו, \u0003ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך\u0004 על שיטת ריש לקיש (הסבור כי דין זה שצריך \"לעשות דמים\" הוא מן התורה) מ\u0003מתניתין\u0004 \u0005[המשנה]\u0006 האומרת \u0003\"אלו דברים\u0004 שאין להם אונאה... וה\u0003הקדשות\",\u0004 הרי שאין דין השבת דמים בהקדש מן התורה — הרי זה \u0003כ\u0004הסברו של \u0003רב חסדא,\u0004 שכן \u0003אמר רב חסדא:\u0004 מה שנאמר במשנה ש\u0003אין להן אונאה\u0004 — הכוונה היא: ש\u0003אינן בתורת\u0004 דין \u0003אונאה\u0004 הרגיל. שבעוד שכרגיל אין השבת דמים באונאה בפחות מששית (\"כדי אונאה\"), הרי דינם של הקדשות ש\u0003אפילו\u0004 ב\u0003פחות מכדי אונאה\u0004 — \u0003חוזר,\u0004 כלומר, מחזיר את ההפרש.","","ובענין השבת דמים להקדש, כאשר נמצא שהתחלל בפחות משוויו, \u0003אמר עולא: לא אמרו\u0004 שיש להשיב להקדש את ההפרש, \u0003אלא\u0004 \u0003בשמוי\u0004 (ששמו, העריכו את שוויו) \u0003בתרי\u0004 \u0005[בשנים],\u0006 שרק שני אנשים הם שהעריכו, ואחר כך באו שלושה אחרים (כדין) ושמוהו ביותר, \u0003אבל ב\u0004הקדש ה\u0003שמוי בתלתא\u0004 \u0005[בשלושה],\u0006 וכסכום הזה שולם להקדש — \u0003ו\u0004מעתה \u0003אף על גב דאתי\u0004 \u0005[אף על פי שבאו]\u0006 לאחר מכן עוד ששמו אותו, ונישום \u0003במאה\u0004 אנשים שהעריכו את שווי ההקדש ביותר — \u0003לא הדר\u0004 \u0005[אין מחזיר]\u0006 להקדש את ההפרש.","ושואלים: \u0003איני\u0004 \u0005[האמנם כן]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב ספרא: היכא אמר\u0004 \u0005[היכן נאמר]\u0006 כלל זה ש\u0003מאה\u0004 אנשים הריהם נחשבים \u0003כתרי\u0004 \u0005[כשנים]\u0006 \u0003ותרי\u0004 \u0005[ושנים]\u0006 \u0003כמאה?\u0004 — הרי זה דווקא \u0003לענין עדות,\u0004 שכן דין עדות היא בשניים, \u0003אבל לענין\u0004 שב\u0003אומדנא\u0004 (הערכה) — \u0003בתר\u0004 \u0005[אחר]\u0006 מספר ה\u0003דעות\u0004 (האנשים) \u0003אזלינן\u0004 \u0005[הולכים אנו],\u0006 ולענייננו, צריך לקבל את דעתם של המאה, וצריך להחזיר להקדש את הפרש הדמים.","\u0003ותו\u0004 \u0005[ועוד],\u0006 אף במקרה שהיו בתחילה \u0003תלתא\u0004 \u0005[שלושה]\u0006 שהעריכו את שווי ההקדש, \u0003ו\u0004לאחר מכן \u0003תלתא\u0004 \u0005[שלושה]\u0006 אחרים העריכו בסכום את שוויו, גבוה משל קודמיהם, האם \u0003לא אזלינן בתר בתרא\u0004 \u0005[אין אנו הולכים\u0006 אז אחר דברי הקבוצה \u0005האחרונה]?\u0006 שכן כלל הוא ש\u0003יד הקדש על העליונה!\u0004","ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003עולא\u0004 כי דין זה ש\u0003צריך לעשות דמים\u0004 — אין הוא מן התורה, אלא \u0003מדבריהם\u0004 של חכמים, \u0003וכל\u0004 הלכה \u0003דרבנן\u0004 \u0005[של חכמים]\u0006 — \u0003אקילו\u0004 \u0005[הקלו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים],\u0006 ולכן אף שהמאה ששמו אחר השלושה העריכו ביותר — אין מחמירים לנהוג כהערכתם.","הרוצה לעשות תמורה, ואומר \u0003\"הרי\u0004 בהמת חולין \u0003זו תחת עולה\",\u0004 או שאמר \"הרי בהמת חולין זו \u0003תחת חטאת\",\u0004 שלא אמר שתהא תחת עולה או חטאת מסויימת, אלא בסתם — \u0003לא אמר כלום.\u0004 שאין התמורה חלה אלא בממיר על בהמת הקדש מסויימת. עמדו לפניו בהמת חולין ובהמת חטאת ואמר \"הרי בהמת חולין זו \u0003תחת חטאת זו\",\u0004 \u0003ו\u0004כן אם עמדו לפניו בהמת חולין ובהמת עולה ואמר \"הרי בהמת חולין זו \u0003תחת עולה זו\"\u0004 — הרי זו תמורה. ואם אמר \"הרי בהמת חולין זו \u0003תחת\u0004 בהמת \u0003חטאת\u0004 שיש לי בבית\", \u0003ו\u0004כן אם אמר \"הרי בהמת חולין זו \u0003תחת עולה שיש לי בבית\",\u0004 אם אכן \u0003היה לו\u0004 בבית באותה שעה קרבן עולה או חטאת — \u0003דבריו קיימים.\u0004","אם \u0003אמר על הבהמה טמאה ו\u0004כן אם אמר \u0003על\u0004 בהמה שהיא \u0003בעלת מום \"הרי אלו עולה\"\u0004 — \u0003לא אמר כלום.\u0004 שהרי אין אלה ראויות ליקרב על המזבח. ואולם אם אמר עליהן \u0003\"הרי אלו לעולה\"\u0004 — \u0003ימכרו, ויביא בדמיהם עולה,\u0004 שהרי יש במשמעות הלשון \"לעולה\" — לצורך עולה, שנמכרים ומביא בדמיהם קרבן עולה.","שנינו במשנה שאם אמר על בהמת חולין \"הרי זו תחת עולה\" — לא אמר כלום. ובענין זה \u0003אמר רב יהודה, אמר רב: מתניתין\u0004 \u0005[משנתנו]\u0006 זו הריהי ש\u0003לא כ\u0004שיטת \u0003ר' מאיר, דאי\u0004 \u0005[ש\u0006כן \u0005אם]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 לשיטתו \u0003אין אדם מוציא דבריו לבטלה.\u0004 וזה שאמר \"הרי זו תחת עולה\", לא הוציא דבריו לבטלה, וכוונתו היתה לעולה שיש לו בבית.","עוד שנינו במשנתנו שאם אמר על הבהמה הטמאה ועל הבהמה בעלת המום \u0003\"הרי אלו לעולה\" ימכרו, ויביא בדמיו עולה.\u0004 ומדייקים בדברים: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 משום שהרי אלו \u0003בהמה טמאה ובעלת מום, דלא חזיין\u0004 \u0005[שאינן ראויות]\u0006 להקרבה — משום כך \u0003לא בעיין מומא\u0004 \u0005[אינן צריכות\u0006 שיפול בהן \u0005מום]\u0006 על מנת שימכרו לדמיהן. \u0003אבל\u0004 ה\u0003מפריש נקבה לאשם או לעולה,\u0004 שאינה ראויה לקרבנות אלה, אבל ראויה היא לקרבנות אחרים — \u0003בעיין מומא\u0004 \u0005[צריכות\u0006 שיפול בהן \u0005מום]\u0006 על מנת שימכרו לדמיהן. ומכאן, \u0003אמר רב יהודה, אמר רב: מתניתין\u0004 \u0005[משנתנו]\u0006 הריהי ש\u0003לא כר' שמעון. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכתנו\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 המפריש נקבה לאשמו, \u0003תימכר שלא במום,\u0004","",""],["\u0003כל\u0004 הבהמות \u0003האסורין\u0004 בהקרבה \u0003לגבי\u0004 (על) ה\u0003מזבח,\u0004 שהתערבו בבהמות הכשרות להקרבה — הריהם \u0003אוסרין\u0004 את כל התערובת שהם בתוכה, \u0003בכל שהן,\u0004 בכל יחס מספרי בינם לבין הבהמות המותרות, ואלו הם הבהמות האסורות: זכר \u0003הרובע\u0004 את האשה, \u0003והנרבע\u0004 על ידי אדם, \u0003והמוקצה\u0004 (זה שיחדוהו) לעבודה זרה, \u0003והנעבד\u0004 כעבודה זרה, \u0003והאתנן\u0004 (בהמה שניתנה כתשלום לזונה), \u0003ו\u0004זה ששימש כ\u0003מחיר\u0004 (כתמורה) לכלב, \u0003וה\u0004בהמה שהיא \u0003כלאים\u0004 (שנולדה משתי מיני בהמות, כגון תיש ורחל), \u0003וה\u0004בהמה \u0003טרפה\u0004 (שעומדת למות עקב מחלה או פגיעה), \u0003ו\u0004כן בהמה שהיא \u0003יוצא דופן\u0004 (שנולדה שלא כרגיל, אלא שנחתכה דופן בטנה של אמה והוצאה משם).","ולפירוט הדברים: \u0003איזהו\u0004 הפסול משום \u0003מוקצה?\u0004 — זה \u0003המוקצה לעבודה זרה,\u0004 ודינו: דווקא \u0003הוא\u0004 עצמו \u0003אסור\u0004 להקרבה על המזבח, \u0003ו\u0004אולם \u0003מה שעליו\u0004 (תכשיטיו, כליו) \u0003מותר\u0004 להקרבה (באופן שימכרו אלו, ובדמיהם יביאו קרבנות), שכן עדיין לא נעבד זה לעבודה זרה. \u0003ואיזהו ה\u0004פסול משום \u0003נעבד?\u0004 — \u0003כל שעובדין אותו\u0004 בפועל כעבודה זרה, ודינו: \u0003הוא ומה שעליו אסור\u0004 להקרבה על המזבח. \u0003וזה וזה\u0004 (הן זה שהקצוהו לעבודה זרה והן זה שנעבד בפועל לעבודה זרה) \u0003מותר באכילה\u0004 להדיוט, שכן כל איסורם אינו אלא למזבח, ולא לאכילת אדם.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 שנינו במשנתנו שכל אותן הבהמות האסורות להקרבה על המזבח, שהתערבו בבהמות אחרות, הריהן \u0003אוסרין בכל שהן.\u0004 והרי זה איפוא בא להשמיענו ש\u0003לא בטלי ברובא\u0004 \u0005[שאין\u0006 הן \u0005בטלות ברוב].\u0006 ואולם על כך יש לשאול, שהרי כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנה במסכת זבחים כי \u0003כל הקדשים\u0004 (הקרבנות) \u0003שנתערבו\u0004 \u0003בחטאות\u0004 ה\u0003מתות,\u0004 (חטאות שנפסלו ודינן שהן מתות) \u0003או בשור הנסקל\u0004 (שנידון לסקילה על שהרג אדם), \u0003אפילו\u0004 \u0003אחד\u0004 שהתערב \u0003ברבוא\u0004 — \u0003ימותו\u0004 כולם.","\u0003וקשיא לן\u0004 \u0005[והיה קשה לנו]\u0006 בפירוש משנה זו: \u0003מאי קאמר\u0004 \u0005[מה אמר,\u0006 מה בדיוק הכוונה\u0005]\u0006 במה שאמר \"אפילו אחד ברבוא\" שמשמע שנתערב אחד כשר ברבוא אסורים? שהרי אם מיעוט אסורים התערב ברוב כשרים כולם אסורים, כל שכן כאשר הרוב הם האסורים!","והשבנו כי \u0003הכי קתני\u0004 \u0005[כך\u0006 היא \u0005שנויה,\u0006 כך פירושה\u0005]:\u0006 כל הקרבנות הכשרים ש\u0003נתערבו בהן\u0004 אחת \u0003מ\u0004חמש \u0003חטאות\u0004 ה\u0003מתות או שור הנסקל, אפילו\u0004 התערב מהפסולים \u0003ברבוא\u0004 כשרים — \u0003ימותו\u0004 כולם. ומעתה יש להקשות: למה להשמיענו שוב הלכה זו במשנתנו?","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר שוב במשנתנו, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי דווקא \u0003התם\u0004 \u0005[שם,\u0006 במשנה בזבחים\u0005]\u0006 כך \u0003הוא\u0004 הדין, שכל התערובת נאסרה — משום שהקרבנות האסורים המוזכרים שם (חמש חטאות המתות ושור הנסקל) שהתערבו בבהמות מותרות \u0003איסורי הנאה\u0004 הם, \u0003אבל הכא\u0004 \u0005[כאן,\u0006 במשנתנו\u0005],\u0006 \u0003דלאו\u0004 \u0005[שאין]\u0006 הפסולים בכלל \u0003איסורי הנאה,\u0004 אלא רק פסולי הקרבה — \u0003אימא\u0004 \u0005[אומר]:\u0006 \u0003ליבטל ברובא\u0004 \u0005[שיבטל\u0006 הפסול \u0005ברוב],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאף פסולי הקרבה אוסרים את כל התערובת בכל שהוא.","ומקשים על הסבר זה: \u0003ו\u0004הרי \u0003רובע ונרבע\u0004 ושאר הקרבנות הפסולים השנויים במשנתנו זו \u0003נמי תנינא\u0004 \u0005[גם כן שנינו]\u0006 באותה משנה בזבחים, שכן שנינו שם: נתערבו רובע ונרבע, מוקצה, נעבד (ושאר המנויים במשנתנו) — נאסרו בכך כל הבהמות שבתערובת, ודינן ש\u0003ירעו עד שיסתאבו\u0004 (שיפול בהם מום, וייפסלו להקרבה), \u0003ו\u0004לאחר מכן \u0003ימכרו, ויביא\u0004 הבעלים \u0003בדמי\u0004 הבהמה היותר \u0003יפה\u0004 (משובחת) \u0003שבהן מאותו המין\u0004 של הקרבן שצריך להקריב. הרי שאף אם נתערב פסול הקרבה המותר בהנאה, גם כן אוסר הוא את כל התערובת בכל שהוא, ומדוע יש לשנות זאת שוב במשנתנו?","\u0003אמר רב כהנא, אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה,\u0006 השאלה הזו \u0005לפני]\u0006 \u0003רב שימי בר אשי,\u0004 ו\u0003אמר לי\u0004 בתשובה לכך: יש צורך למשנתנו לחזור ולהשמיע דין זה, שכן \u0003חדא\u0004 \u0005[\u0006משנה \u0005אחת,\u0006 משנתנו\u0005]\u0006 עוסקת \u0003ב\u0004שנתערבו אותן בהמות בעודן \u0003חולין,\u0004 ולאחר מכן עמד בעליהן והקדישן. \u0003ו\u0004אילו \u0003חדא\u0004 \u0005[\u0006משנה \u0005אחת,\u0006 בזבחים\u0005]\u0006 עוסקת \u0003ב\u0004מקרה שהתערבו כשהם \u0003קדשים\u0004 כבר (וכמו שמורה לשון במשנה \"כל הזבחים שנתערבו\" — שהם זבחים).","\u0003ו\u0004לכן \u0003צריכי\u0004 \u0005[נצרכו]\u0006 שתיהן להיאמר, \u0003דאי אשמועינן גבי\u0004 \u0005[שאם היה משמיענו\u0006 רק את המשנה \u0005אצל]\u0006 \u0003קדשים\u0004 — הייתי אומר בטעם הדבר \u0003משום דמאיסי\u0004 \u0005[שמאוסים]\u0006 בשעה שהתערבו בכשרים, שהרי נפסלו אחר שנתקדשו, \u0003אבל גבי\u0004 \u0005[אצל]\u0006 בהמות שהתערבו כשהן עדיין \u0003חולין\u0004 (ואין בפסולים אלו כדי להחשיב את החולין כמאוס), ורק לאחר מכן הקדישן — \u0003אימא ליבטלי\u0004 \u0005[אומר שיבטלו]\u0006 בתערובת זו, ויותרו הכל להקרבה. ולכן השמיענו שגם כשהתערבו בעודן חולין פוסלים הם את כל התערובת.","ושואלים על הסבר זה: \u0003ו\u0004הרי \u0003בחולין נמי תנינא\u0004 \u0005[גם כן שנינו]\u0006 במסכת עבודה זרה, שאין בטלים האסורים והכל נאסר, שכך שנינו שם: \u0003ואלו\u0004 הדברים שהם \u0003אסורין\u0004 כשלעצמם \u0003ואוסרין\u0004 אחרים אם נתערבו בדברים המותרים כדוגמתם \u0003בכל שהן: יין נסך,\u0004 \u0003ועבודה זרה, וציפרי מצורע\u0004 המשמשים לטהרתו, \u0003ועורות לבובין,\u0004 שניקבו מול לב הבהמה והוציאו דרך שם את לבה בעודה חיה כתקרובת לעבודה זרה,","\u0003ושיער נזיר\u0004 שמגלח לטהרתו בתום ימי הנזירות, \u0003ופטר חמור, ובשר בחלב, ושור הנסקל, ועגלה ערופה,\u0004 \u0003וחולין שנשחטו בעזרה, ושעיר המשתלח\u0004 של יום הכיפורים — \u0003הרי\u0004 כל \u0003אלו אסורין ואוסרין\u0004 את אלה שהתערבו בהם \u0003בכל שהן!\u0004","ומשיבים: \u0003צריכי\u0004 \u0005[צריכות]\u0006 שתי המשניות הללו להיאמר, \u0003דאי אשמעינן התם\u0004 \u0005[שאם היה משמיענו\u0006 רק \u0005שם]\u0006 במסכת עבודה זרה — הייתי אומר כי משום שהדברים האסורים המנויים במשנה זו הריהם \u0003איסורי הנאה,\u0004 לכן הוא \u0003דלא בטלי\u0004 \u0005[שאינם בטלים],\u0006 \u0003אבל\u0004 הפסולים המנויים במשנתנו \u0003הכא\u0004 \u0005[כאן],\u0006 שאינם אסורים בהנאה, שהרי הם מותרים באכילה להדיוט — \u0003ליבטלי\u0004 \u0005[שיבטלו]\u0006 בתערובתם.","\u0003ו\u0004מן הצד האחר, \u0003אי אשמועינן הכא\u0004 \u0005[אם היה משמיענו\u0006 רק את משנתנו \u0005כאן]\u0006 — הייתי אומר שהטעם שאין האיסורים הללו בטלים בתערובתם, משום שהמדובר בהקרבה \u0003לגבוה דמאיס\u0004 \u0005[שמאוס]\u0006 הדבר, \u0003אבל ל\u0004ענין הנאתם בידי \u0003הדיוט\u0004 — \u0003אימא\u0004 \u0005[אומר]\u0006 ש\u0003איסורי הנאה ליבטלו ברובא\u0004 \u0005[שיבטלו ברוב],\u0006 לכן בעבודה זרה \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאף בזה אין הם בטלים, וכל התערובת אסורה.","בין הפסולים המנויים במשנתנו מוזכרים ה\u0003רובע ונרבע.\u0004 ומבררים: \u0003מנלן דאסירי\u0004 \u0005[מנין לנו שאסורים]\u0006 \u0003לגבוה\u0004 (להקרבה במקדש)? — \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על הכתוב \"מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם\" (ויקרא א, ב), הביטוי \u0003\"מן הבהמה\"\u0004 — בא \u0003להוציא\u0004 מכלל המובאים לקרבן את ה\u0003רובע ו\u0004את ה\u0003נרבע.\u0004","ויש לדון בדבר, למה לי דרשת כתובים להוראת הלכה זו שהרובע והנרבע פסולים לקרבן, \u0003והלא דין\u0004 (קל וחומר) הוא, ובאופן זה: \u0003ומה בעל מום,\u0004 הקל, \u0003ש\u0004כן \u0003לא נתעבדה בה עבירה\u0004 — בכל זאת הריהו \u0003פסול לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח. רובע ונרבע,\u0004 החמורים, \u0003ש\u0004כן \u0003נעבדה בהן עבירה\u0004 — \u0003אינו דין ש\u0004הריהם \u0003אסורין לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח?\u0004","ופורכים: שור שנעברה בו עבירה של ה\u0003חורש בשור וחמור\u0004 יחדיו \u0003יוכיח\u0004 לענין זה, שאף \u0003שנתעבדה בו עבירה\u0004 — \u0003ו\u0004בכל זאת הריהו \u0003מותר לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח.\u0004","ודוחים: אין להביא ראיה משור זה, שכן \u0003מה ל\u0004איסור \u0003חורש בשור וחמור\u0004 — הקל, \u0003ש\u0004הרי \u0003אין חייבין\u0004 עליו \u0003מיתה,\u0004 ומשום כך אף אינו נאסר להקרבה, \u0003תאמר ב\u0004איסור \u0003רובע ו\u0004באיסור \u0003נרבע\u0004 — החמורים, \u0003ש\u0004הרי \u0003חייבין\u0004 עליהם \u0003מיתה,\u0004 ומשום כך אסורים הם להקרבה.","ומסכמים: אכן דחיה נכונה היא זו, ו\u0003טול לך\u0004 (חזור בך) מ\u0003מה שהבאתה,\u0004 מהפירכה על הקל וחומר. ואמנם מקל וחומר מבעל מום יכול להילמד דינם של הרובע והנרבע שפסולים הם להקרבה, ואולם \u0003הרי\u0004 זה נכון רק ברובע או נרבע \u0003שנתעבדה בהן עבירה בשני עדים,\u0004 ודינם למיתה, ואולם הרובע או הנרבע ש","\u0003נעבדה בהן עבירה על פי עד אחד, או על פי\u0004 הודאת \u0003הבעלים,\u0004 שאין דינם למיתה, \u0003מנין\u0004 לנו שאף הם פסולים להקרבה?","לכך באה דרשת הכתוב \"מן הבהמה\", ש\u0003אמר ר' שמעון: אני דן\u0004 (למד בקל וחומר זה מבעל מום) אף את דינו של הרובע או הנרבע שאין דינו למיתה, ובאופן זה: \u0003ומה בעל מום\u0004 — הקל, \u0003ש\u0004הרי \u0003אין התראת שני עדים פוסלתו מאכילה\u0004 להדיוט, ובכל זאת \u0003הודאת\u0004 (קביעת) \u0003עד אחד\u0004 (החכם האחד הפוסק שהרי זה מום הפוסל אותו מקרבן) — \u0003פוסלתו מהקרבה. ברובע ונרבע שהודאת שני עדים פוסלתו מאכילה\u0004 — \u0003אינו דין שהודאת עד אחד פוסלתו מהקרבה!\u0004","לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \u0003\"מן הבהמה\"\u0004 — \u0003להוציא\u0004 מכלל הכשרים להקרבה את ה\u0003רובע ונרבע.\u0004 ותוהים על סוף הדברים: מדוע אמר שלכך מלמדנו הכתוב בדרשה זו, \u0003והא אתיא מדינא\u0004 \u0005[והרי\u0006 הדבר \u0005בא,\u0006 נלמד הדבר \u0005מן הדין,\u0006 מקל וחומר זה שאמרו ר' שמעון\u0005]\u0006 ומשיבים: חכמים החולקים על ר' שמעון סוברים כי אף הרובע או הנרבע על פי עד אחד או על פי הודאת הבעלים \u0003לא אתיא\u0004 \u0005[אינו בא,\u0006 נלמד\u0005]\u0006"],["שכן \u0003אמר רב אשי:\u0004 אין ללמוד דינם של הרובע והנרבע בקל וחומר מבעל מום, \u0003משום דאיכא למימר\u0004 \u0005[שיש לומר]\u0006 על קל וחומר זה כי \u0003מעיקרא דדינא פירכא\u0004 \u0005[מתחילת,\u0006 מיסוד \u0005הדין,\u0006 הקל וחומר, יש עליו \u0005פירכה],\u0006 שכן אפשר לומר: \u0003מה לבעל מום\u0004 — \u0003שכן מומו ניכר,\u0004 ומשום כך הריהו פסול להקרבה,","\u0003תאמר ברובע ונרבע\u0004 — \u0003שאין מומו ניכר,\u0004 והיה מקום לומר ש\u0003הואיל ואין מומו ניכר\u0004 — \u0003יהא כשר לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח,\u0004 אף שנעשתה בו עבירה — לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \u0003\"מן הבהמה\"\u0004 (ויקרא א, ב) — \u0003להוציא רובע ונרבע\u0004 מכלל הכשרים להקרבה.","עוד נדרש בברייתא זו הכתוב \"מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם\": \u0003\"מן הבקר\"\u0004 — בא \u0003להוציא\u0004 (למעט) \u0003את הנעבד\u0004 מכלל הכשרים להקרבה. ויש לדון בדבר: למה לי דרשת כתוב זה, \u0003והלא דין\u0004 (קל וחומר) \u0003הוא\u0004 המלמדנו כן, ובאופן זה: \u0003ומה אתנן\u0004 זונה \u0003ומחיר\u0004 כלב, הקלים בדינם \u0003ש\u0004הרי \u0003ציפויין\u0004 (תוספת ציפוי לקישוט שעליהם) \u0003מותרין\u0004 למקדש, כגון לעשות מהם ריקועים למזבח, מכל מקום \u0003הן\u0004 עצמם \u0003אסורין\u0004 להקדש. ומעתה, \u0003נעבד,\u0004 החמור בדינו, \u0003ש\u0004הרי \u0003ציפויו אסור\u0004 — \u0003אינו דין שהוא\u0004 עצמו יהיה \u0003אסור\u0004 להקדש. ואין צורך איפוא בלימוד מן הכתוב להשמיענו הלכה זו.","\u0003או\u0004 שמא נלמד \u0003חילוף\u0004 (באופן הפוך): \u0003ומה אתנן ומחיר\u0004 החמורים, \u0003ש\u0004הרי \u0003הן אסורין\u0004 להקרבה — בכל זאת \u0003ציפוייהן מותרין. נעבד\u0004 הקל בדינו, \u0003ש\u0004הרי הוא \u0003מותר\u0004 להקרבה (שלא נאמר בתורה שהוא אסור) — \u0003יהא ציפויו מותר\u0004 להקדש.","ואולם אין לומר קל וחומר זה משום ש\u0003אם כן ביטלת\u0004 את האמור בתורה: \"פסילי אלהיהם תשרפון באש \u0003לא תחמד כסף וזהב עליהם ולקחת לך\"\u0004 (דברים ז, כה), שבכלל זה לא רק הפסילים עצמם, אלא אף קישוטיהם (\"כסף וזהב עליהם\").","ודוחים: \u0003אני אקיימנו\u0004 את האמור \u0003\"לא תחמד כסף וזהב\u0004 עליהם\" — שאיסור זה הוא דווקא \u0003ב\u0004ציפוי של \u0003דבר שאין בו רוח חיים,\u0004 \u0003אבל ב\u0004ציפוי של \u0003דבר שיש בו רוח חיים, הואיל והן\u0004 עצמם \u0003מותר\u0004 להקרבה — \u0003יכול יהא\u0004 אף ה\u0003ציפוי\u0004 שעליו \u0003מותר\u0004 להקדש. לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \u0003\"מן הבקר\"\u0004 — \u0003להוציא את הנעבד\u0004 ואת הציפוי שעליו. ומעתה, כיון שדבר שיש בו רוח חיים הריהו אסור, וגם ציפויו אסור.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חנניא: טעמא\u0004 \u0005[הטעם]\u0006 שציפוי הנעבד הריהו אסור, הוא רק משום \u0003דמעטיה קרא\u0004 \u0005[שמיעטתו התורה]\u0006 את הנעבד מן הכתוב \"מן הבקר\". ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 שאם \u0003לא מעטיה קרא\u0004 \u0005[מיעטתו התורה]\u0006 — היה ה\u0003ציפוי מותר? והכתיב\u0004 \u0005[והרי נאמר]\u0006 בעבודה זרה שיש לאבדה מכל וכל, ככתוב: \"ונתצתם את מזבחותם ושברתם את מצבותם ואשריהם תשרפון באש ופסילי אלהיהם תגדעון \u0003ואבדתם את שמם\"\u0004 (דברים יב, ג) — ולמדנו מכאן שיש לאבד לא רק את העבודה זרה עצמה אלא אף את \u0003כל העשוי לשמם\u0004 (\"ואבדתם את שמם\"), ואף ציפוייהם בכלל זה!","ומשיבים: הכתוב \u0003ההוא\u0004 \"ואבדתם את שמם\" לא לכך הוא בא, אלא ללמדנו שיש \u0003לכנות להם\u0004 לעבודה זרה \u0003שם\u0004 של גנאי ולא לקרוא להם בשמם המקורי \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 וכגון: \u0003ל\u0004מקום עבודה זרה ששמו \u0003\"בית גליא\"\u0004 \u0005[בית רם]\u0006 — \u0003קרינן\u0004 \u0005[קוראים אנו]\u0006 \u0003אותו \"בית כריא\"\u0004 \u0005[בית כליון],\u0006 מקום הנקרא \u0003\"פני המולך\"\u0004 — אנו קוראים \u0003\"פני כלב\",\u0004 ואת העבודה זרה הנקראת \u0003\"עין כל\"\u0004 — אנו קוראים \u0003\"עין קוץ\".\u0004","ושואלים על דרשות הברייתא: למדנו מן הכתוב \"מן הבהמה\" למעט את הרובע והנרבע, ומן הכתוב \"מן הבקר\" למעט את הנעבד, \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 את דרשות הכתובים, ובאופן זה: \u0003\"מן הבהמה\"\u0004 — \u0003להוציא את הנעבד, \"מן הבקר\"\u0004 — \u0003להוציא רובע ונרבע!\u0004","ומסבירים: \u0003התם\u0004 \u0005[שם]\u0006 בכתוב \"מן הבהמה\" דורשים אנו \u0003מעניינא דקרא\u0004 \u0005[מעניינו של הכתוב]\u0006 העוסק בבהמה, שכן דין הרובע והנרבע \u0003כתיב גבי\u0004 \u0005[נאמר אצל]\u0006 \u0003בהמה\u0004 — \u0003\"ואיש כי יתן שכבתו בבהמה מות יומת\u0004 ואת הבהמה תהרוגו. ואשה אשר תקרב אל כל בהמה לרבעה אותה והרגת את האשה ואת הבהמה מות יומתו דמיהם בם\" (ויקרא כ, טו—טז). ואילו איסור נעבד לעבודה זרה \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בקר כתיב\u0004 \u0005[נאמר]\u0006 — \"יעשו עגל בחורב וישתחוו למסכה. \u0003וימירו את כבודם בתבנית שור אכל עשב\"\u0004 (תהלים קו, יט—כ).","עוד נדרש בברייתא על הכתוב \"מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם\": הביטוי \u0003\"מן הצאן\"\u0004 בא \u0003להוציא את המוקצה\u0004 (המיועד) לעבודה זרה מכלל הכשרים להקרבה, ותוספת וא\"ו \u0003\"ומן הצאן\"\u0004 באה \u0003להוציא את\u0004 השור \u0003הנוגח\u0004 שהרג אדם. אמר ר' שמעון: \u0003אם נאמר\u0004 מיעוט בתורה לענין ה\u0003רובע\u0004 — \u0003למה נאמר\u0004 עוד מיעוט לענין ה\u0003נוגח? ואם נאמר\u0004 מיעוט לענין ה\u0003נוגח\u0004 — \u0003למה נאמר\u0004 מיעוט נוסף לענין \u0003רובע?\u0004 הלא שניהם שווים בכך שעשו מעשים שבגללם הורגים אותם!","ומסבירים: \u0003לפי שישנו ברובע\u0004 צד חומרה \u0003מה שאין כן בנוגח,\u0004 ולהיפך. ומפרטים: \u0003יש\u0004 צד חומרה \u0003ברובע, שהרובע עושה\u0004 בו הכתוב דין \u0003אונס כ\u0004דין \u0003רצון\u0004 (בין אם הבהמה עשתה דבר זה מרצונה בין אם אנסוה לכך), \u0003מה שאין כן בנוגח,\u0004 ששור שנגח לאונסו פטור.","ומן הצד האחר, \u0003יש בנוגח\u0004 צד חומרה שאין ברובע ונרבע — \u0003ש\u0004כן בעליו של \u0003הנוגח משלם את הכופר, מה שאין כן ברובע\u0004 ובתוך כך הרג את הנרבע, שאין בעליו משלם כופר. לכך \u0003הוצרך\u0004 הכתוב \u0003לומר\u0004 (ללמדנו) את דין ה\u0003רובע והוצרך לומר\u0004 את דין ה\u0003נוגח.\u0004","למדנו בברייתא כי איסור הקרבת רובע ונרבע נלמד מדרשת הכתוב \"מן הבהמה\". ומעירים: \u0003ו\u0004אילו \u0003האי תנא מייתי לה מהכא\u0004 \u0005[תנא זה,\u0006 שדבריו יובאו להלן, \u0005מביא,\u0006 למד \u0005אותה הלכה מכאן,\u0006 ממקרא אחר\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הרובע והנרבע (וכולם)\u0004 שהוקדשו — הרי \u0003הם כקדשים שקדם מום עובר להקדשן,\u0004 וכיון שיש בהם עתה מום, אין הם ראויים להקרבה, ואין די בכך כדי להתיר את פדיונם,","\u0003ו\u0004כמו בכל מום עובר אחר אין די במומם, אלא \u0003צריכין\u0004 שיהיה בהם \u0003מום קבוע\u0004 כדי \u0003לפדות עליהן.\u0004 וטעם הדבר: \u0003ש\u0004כן \u0003נאמר\u0004 בסופה של פרשת בעלי המומים הפסולים להקרבה: \"לא תקריבו את לחם אלהיכם מכל אלה \u0003כי משחתם בהם מום בם\u0004 לא ירצו לכם\" (ויקרא כב, כה).","ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה,\u0006 כיצד הוא \u0005הלימוד],\u0006 כיצד מלמד הפסוק הזה לענין הרובע והנרבע? והרי אין הכתוב מדבר אלא בענין בעלי מומים! ומשיבים: \u0003חסורי מיחסרא, והכי קתני\u0004 \u0005[חסר\u0006 בלשון הברייתא, \u0005וכך היא שנויה\u0006 במלואה\u0005]:\u0006 \u0003מנין שהן,\u0004 הרובע והנרבע, \u0003אסורין\u0004 לקרבן? — לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \u0003\"כי משחתם בהם מום בם\", ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005של בית\u0006 מדרשו\u0005] של\u0006 \u0003ר' ישמעאל\u0004 כלל זה בלשון הכתובים: \u0003כל מקום\u0004 בתורה \u0003שנאמר\u0004 בו לשון \u0003'השחתה'\u0004 — \u0003אינו אלא דבר ערוה ועבודה זרה.\u0004","ומפרט: \u0003דבר ערוה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדור המבול שהיו פרוצים בעריות: \u0003\"כי השחית כל בשר\u0004 את דרכו על הארץ\" (בראשית ו, יב). ו\u0003עבודה זרה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 באזהרת עשיית עבודה זרה: \u0003\"פן תשחתון ועשיתם לכם פסל תמונת כל סמל\"\u0004 (דברים ד, טז). וכן בבעלי מום נאמרה לשון 'השחתה', \"כי משחתם בהם מום בם\", ונמצאנו למדים: \u0003כל שהמום פוסל בהן\u0004 בבעלי החיים מלקרב על המזבח — אף \u0003דבר ערוה\u0004 (הרובע או הנרבע) \u0003ועבודה זרה פוסלין בהן.\u0004","ושואלים: \u0003ותנא דבי\u0004 \u0005[של בית\u0006 מדרשו\u0005] של\u0006 \u0003ר' ישמעאל,\u0004 שלמד את פסול הרובע והנרבע, הנעבד והמוקצה מהאמור בפרשת בעלי המומים, דברי הכתוב \u0003\"מן הבהמה מן הבקר ומן הצאן\"\u0004 שמהם למדנו בברייתא הקודמת את פסול הרובע והנרבע ונעבד ומוקצה, \u0003מאי דריש בהו\u0004 \u0005[מה\u0006 הוא \u0005דורש בהם]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 פסוק זה ללמדנו שלושה מיעוטים (הנלמדים מהאמור בפסוק \"מן הבהמה\", \"מן הבקר\", \"ומן הצאן\"): \u0003פרט לחולה, זקן, ומזוהם\u0004 (מעלה זיעה ומסריח) שאין הם קרבים.","וחוזרים ושואלים לצד האחר: \u0003ותנא קמא\u0004 \u0005[והתנא\u0006 בברייתא \u0005הראשונה,\u0006 הקודמת\u0005],\u0006 \u0003דאפקינהו להני קראי\u0004 \u0005[שהוציא,\u0006 שדרש \u0005אותם פסוקים]\u0006 \u0003לרובע ונרבע,\u0004 אם כן ה\u0003חולה,\u0004 ה\u0003זקן, ו\u0004ה\u0003מזוהם מנא ליה\u0004 \u0005[מנין לו]\u0006 שהם פסולים להקרבה? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 דבר זה מהפסוק \"ואם \u0003מן הצאן\u0004 קרבנו \u0003מן הכבשים ומן העזים\"\u0004 (ראה דברים א, י). ומעירים: \u0003ו\u0004אילו \u0003לתנא דבי\u0004 \u0005[של בית\u0006 מדרשו\u0005] של\u0006 \u0005ר' ישמעאל הדורש זאת מהפסוק \"מן הבהמה מן הבקר ומן הצאן\", מה דורש הוא מהכתוב \"מן הצאן קרבנו מן הכשבים\" וגו' — הוא סבור שאין לדרוש כן מהכתוב הזה, כי\u0006 \u0003אורחיה דקרא לאישתעויי הכי\u0004 \u0005[דרך הכתוב לדבר כך].\u0006","שנינו במשנה: \u0003איזהו\u0004 הנקרא \u0003מוקצה?\u0004 — זה המוקצה \u0003לעבודה זרה.\u0004 ובענין זה \u0003אמר ריש לקיש: אין אסור\u0004 להקרבה משום \"מוקצה\" \u0003אלא\u0004 זה ה\u0003מוקצה לשבע\u0004","\u0003שנים.\u0004 שהקצוהו על מנת שבסוף תקופת שבע השנים ישמש כעבודה זרה. ומקורו של דבר: \u0003ש\u0004כן \u0003נאמר\u0004 בגדעון \u0003\"ויהי בלילה ההוא ויאמר קח את פר השור אשר לאביך ופר השני שבע שנים\u0004 והרסת את מזבח הבעל אשר לאביך ואת האשרה אשר עליו תכרת. ובנית מזבח לה' אלהיך... ולקחת את הפר השני והעלית עולה בעצי האשרה אשר תכרות\" (שופטים ו, כה—כו), הרי שכך היה מנהג עבודה זרה להעמיד פר לשבע שנים.","ושואלים: \u0003ו\u0004כי \u0003התם\u0004 \u0005[שם]\u0006 אותו הפר \u0003מוקצה בלחוד הוה\u0004 \u0005[בלבד היה]?\u0006 והרי \u0003נעבד נמי הוה\u0004 \u0005[גם כן היה],\u0006 שהרי עבדוהו בפועל! \u0003אמר רב אחא בר יעקב:\u0004 פר זה \u0003מוקצה\u0004 היה \u0003לעבוד\u0004 בו עבודה זרה, \u0003ו\u0004אולם בפועל \u0003לא עבדוהו. רבא אמר: לעולם עבדוהו,\u0004 והיה איפוא מקום לאוסרו משום עבודה זרה, \u0003ו\u0004אולם \u0003חידוש הוא, כ\u0004דברי \u0003ר' אבא בר כהנא:\u0004 שכן \u0003אמר ר' אבא בר כהנא, שמנה דברים\u0004 אסורים, \u0003התירו\u0004 לגדעון לעשות \u0003באותו לילה\u0004 (ראה שופטים פרק ו'): איסור שחיטת קדשים ב\u0003חוץ\u0004 (מחוץ למשכן), \u0003ו\u0004האיסור להקריב קרבנות ב\u0003לילה,\u0004 שהרי הקריב בלילה, \u0003ו\u0004איסור עבודה ב\u0003זרות\u0004 (במי שאינם כהנים), שהרי גדעון לא היה כהן,"],["\u0003ו\u0004איסור הקרבה שלא ב\u0003כלי שרת, ו\u0004איסור הקרבה ב\u0003כלי אשירה,\u0004 שהקריב בכלים ששימשו קודם לכן לאשירה, \u0003ו\u0004האיסור להשתמש ב\u0003עצי אשירה,\u0004 שכך נאמר לגדעון להקריב את העולה על עצי האשירה שיכרות, \u0003ו\u0004איסור הקרבה של ה\u0003מוקצה\u0004 לעבודה זרה, \u0003ו\u0004של ה\u0003נעבד\u0004 לעבודה זרה.","ועוד בעניינו של המוקצה לעבודה זרה, \u0003אמר רב טובי בר מתנה, אמר ר' יאשיה: מנין ל\u0004דין ה\u0003מוקצה מן התורה?\u0004 — \u0003שנאמר\u0004 בדיני הקרבנות בפרשת פינחס: \"את קרבני לחמי לאשי ריח ניחוחי \u0003תשמרו להקריב לי במועדו\"\u0004 (במדבר כח, ב), ומשמעות המלה \"תשמרו\" — \u0003כל שעושין לו שימור.\u0004 סברו מתחילה שכוונת דברי ר' יאשיה היתה: שכל קרבן המוקרב לשמים, צריך שתקדם לו שמירה, שיקצהו ולא יקריבנו מייד לאחר שהקדישו.","ועל כך \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003אביי: אלא מעתה,\u0004 אם אדם \u0003אייתית אימרא דצומא\u0004 \u0005[הביא\u0006 להקרבה \u0005כבש מסוגף,\u0006 כחוש ורעב\u0005],\u0006 \u0003ו\u0004הרי ברור ש\u0003לא עביד ליה\u0004 \u0005[עשה לו]\u0006 בעליו \u0003שימור,\u0004 האם \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר בו שהוא \u0003לא חזו\u0004 \u0005[ראוי]\u0006 \u0003להקרבה?\u0004 והרי לא שמענו שיהיה הקרבן פסול משום שלא טופל כראוי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יאשיה: \u0003אנא\u0004 \u0005[אני],\u0006 כך את הפסוק \u0003\"תשמרו להקריב לי במועדו\", קאמינא\u0004 \u0005[אמרתי,\u0006 דרשתי\u0005]:\u0006 \"תשמרו \u0003לי\"\u0004 — דווקא לשמים אתם מקצים לקרבן, \u0003ולא לאדון אחר, ואיזהו\u0004 (ומיהו) \u0003אחר\u0004 זה \u0003שמקריבין לו?\u0004 — \u0003הוי אומר: זו עבודה זרה.\u0004","ועוד בהגדרת המוקצה לעבודה זרה. \u0003אמר רבא בר רב אדא, אמר רב יצחק: אין\u0004 ה\u0003מוקצה\u0004 לעבודה זרה \u0003אסור\u0004 להקרבה \u0003אלא עד שיעבדו\u0004 בו לצורך כמרי עבודה זרה, ואולם לאחר שעבדו בו כבר לצורך הכמרים — אינו אסור, ששוב אינם מקריבים אותו לעבודה זרה. \u0003עולא אמר\u0004 בשם \u0003ר' יוחנן:\u0004 אין המוקצה אסור להקרבה אלא \u0003עד שימסרוהו לכומרי עבודה זרה\u0004 כדי שיאכילוהו לצורך פיטומו, ואפילו לא נעבדה בו כל עבודה, ואולם לאחר שמסרוהו, אינו אסור, ששוב אינם מקריבים אותו.","החכם \u0003בהא אמר\u0004 בשם \u0003ר' יוחנן:\u0004 אין המוקצה אסור אלא \u0003עד שיאכילוהו\u0004 בעליו לאחר הקצאתו לצורך כמרי עבודה זרה ב\u0003כרשיני\u0004 (מין ירק) \u0003עבודה זרה,\u0004 שלאחר שהאכילוהו שוב אין מקריבים אותו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לבהא:\u0004 האם \u0003מפלגיתו אתון\u0004 \u0005[חולקים אתם]\u0006 על \u0003עולא\u0004 מהי שיטת ר' יוחנן. שכן עולא אמר בשם ר' יוחנן הגדרה אחרת למוקצה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בהא: \u0003לא,\u0004 אינני חולק על עולא לשיטת ר' יוחנן, אלא ש\u0003עולא נמי כי קאמר\u0004 \u0005[גם כן כאשר אמר]\u0006 \u0003הוא\u0004 את הגדרתו זו, הרי זה בתנאי: ובלבד \u0003דשפי ליה\u0004 \u0005[ש\u0006גם \u0005האכילו אותו]\u0006 \u0003כרשיני עבודה זרה.\u0004","\u0003אמר ר' אבא: ידע\u0004 \u0005[יודע]\u0006 \u0003בהא לשנויי שמעתא\u0004 \u0005[לתרץ הלכה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא דסליק התם\u0004 \u0005[שעלה\u0006 מבבל \u0005לשם,\u0006 לארץ ישראל\u0005]\u0006 — \u0003לא הוה ידע\u0004 \u0005[היה יודע]\u0006 לתרץ כך, שכן \u0003ארץ ישראל\u0004 היא ש\u0003גרמה ליה\u0004 \u0005[לו]\u0006 להחכים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יצחק\u0004 לר' אבא: לא כך הוא, שהרי \u0003בהא מיכן ומיכן\u0004 (מכאן ומכאן, מבבל ומארץ ישראל) \u0003הוה\u0004 \u0005[היה],\u0006 ומכאן ומכאן החכים.","ועוד בהגדרת המוקצה, זה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב חנניא טריטאה קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן\u0004 ברייתא זו: \u0003אין מוקצה\u0004 לעבודה זרה \u0003אסור אלא עד שיעשו בו מעשה. הוא\u0004 רב חנניא טריטאה \u0003תני לה\u0004 \u0005[שנה אותה],\u0006 \u0003ו\u0004הוא זה ש\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 (פירש) \u0003לה\u0004 \u0005[אותה]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מעשה\"?\u0004 — \u0003עד שיגזז ויעבדו בו\u0004 לצורך הקצאתו כעבודה זרה.","שנינו במשנתנו: ו\u0003איזהו\u0004 ה\u0003נעבד?\u0004 — כל שעובדין אותו... וזה וזה (המוקצה והנעבד) מותרים באכילה להדיוט. ודנים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006","\u0003אמר רב פפא:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין הקרבנות \"ושה אחת מן הצאן מן המאתים ממשקה ישראל למנחה ולעולה ולשלמים לכפר עליהם\" (יחזקאל מה, טו), ודרשו בו חכמים: \u0003\"ממשקה ישראל\"\u0004 — \u0003מן המותר\u0004 באכילה \u0003לישראל\u0004 מביאים קרבנות, ואין מביאים ממה שאינו מותר באכילה לישראל. \u0003ו\u0004מעתה, \u0003אי סלקא דעתך אסירי\u0004 \u0005[אם עולה על דעתך\u0006 לומר ש\u0005אסורים]\u0006 המוקצה והנעבד באכילה \u0003להדיוט, למה לי קרא ממעטינהו\u0004 \u0005[פסוק למעט אותם]\u0006 \u0003מ\u0004הקרבה ל\u0003גבוה,\u0004 שהרי אם אסורים הם באכילה להדיוט ממילא אסורים הם להקרבה לגבוה. אלא ודאי מותרים הם להדיוט.","ודוחים את הראיה: \u0003ו\u0004כי \u0003כל היכא דאסירי\u0004 \u0005[היכן,\u0006 מקום \u0005שאסורים]\u0006 דברים \u0003להדיוט\u0004 — \u0003לא בעי קרא\u0004 \u0005[אין צריך פסוק]\u0006 ללמדנו שאסורים הם להקרבה? \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003טרפה\u0004 (בעל החיים פגוע, העומד למיתה), \u0003דאסירא\u0004 \u0005[שאסורה]\u0006 היא באכילה \u0003להדיוט,\u0004 \u0003ו\u0004בכל זאת \u0003מעטיה קרא\u0004 \u0005[מיעטה הפסוק]\u0006 \u0003מ\u0004הקרבתה ל\u0003גבוה,\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 מן הכתוב בתחילת ספר ויקרא \"מן הבהמה מן הבקר ומן הצאן\" (ויקרא א, ב) למדנו פסול הקרבתם של קרבנות שונים, וכמבואר למעלה (כח,א). ומעתה, \u0003כשהוא אומר\u0004 \"אם עולה קרבנו \u0003מן הבקר\" למטה\u0004 (בהמשך, בפסוק שלאחריו) \u0003שאין תלמוד לומר\u0004 (שלא למדנו ממנו דבר עד כה), מה הוא מלמדנו? \u0003אלא להוציא\u0004 מכלל הקרבנות \u0003את הטרפה!\u0004","ומשיבים: בכלל, דבר שאסור באכילה לישראל, אין צורך בלימוד מיוחד לאוסרו להקרבה, ואולם בטריפה \u0003איצטריך\u0004 \u0005[נצרך]\u0006 הדבר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאין הטריפה קרבה, אמורים דווקא כשתחילה \u0003נטרפה ואחר כך נתקדשה, אבל\u0004 אם \u0003נתקדשה ו\u0004רק \u0003אחר כך נטרפה\u0004 — \u0003אימא דתישרי\u0004 \u0005[אומר שתותר]\u0006 \u0003לגבוה,\u0004 אף שאינה מותרת לישראל. לכך נצרכה הדרשה מהכתוב למעט אותה.","ושואלים: והאם דין זה שהטריפה פסולה להקרבה אף שהתקדשה ואחר כך נטרפה נלמד מכתוב זה? \u0003והא\u0004 \u0003מהכא נפקא\u0004 \u0005[והרי מכאן יוצא,\u0006 נלמד\u0005],\u0006 מפסוק אחר, שכן נאמר בדין מעשר בהמה \"וכל מעשר בקר וצאן \u0003כל אשר יעבר תחת השבט\u0004 העשירי יהיה קודש לה'\" (ויקרא כז, לב), ומהלשון \"יעבור\" למדו חכמים שאין דין זה נוהג אלא בבהמה העוברת, \u0003פרט לטרפה,\u0004 וכגון זו שנחתכו רגליה למעלה מן הברך, \u0003ש\u0004כן בשל כך \u0003אינה עוברת\u0004 תחת השבט (וממנה נלמד לכל שאר הטרפות)!","ומשיבים: הלימוד \u0003ההוא\u0004 ממעשר בהמה \u0003נמי איצטריך\u0004 \u0005[גם כן נצרך],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שהטריפה פסולה להקרבה אמורים דווקא \u0003היכא\u0004 \u0005[היכן,\u0006 בזמן\u0005]\u0006 ש\u0003לא היתה לה\u0004 מעולם \u0003שעת הכושר\u0004 (זמן שבו היתה ראויה להקרבה), וכגון שכבר \u0003נולדה טרפה ממעי אמה, אבל היכא\u0004 \u0005[היכן,\u0006 בזמן\u0005]\u0006 ש\u0003היתה לה שעת הכושר, ויצאת לאויר העולם,\u0004 והיתה ראויה להקרבה, \u0003ו\u0004רק ל\u0003אחר כך נטרפה\u0004 — \u0003אימא תשתרי\u0004 \u0005[אומר\u0006 ש\u0005תותר]\u0006 \u0003לגבוה,\u0004 לכן \u0003קא משמע לן\u0004 \u0005[הוא\u0006 הלימוד מ\"כל אשר יעבור תחת השבט\" \u0005משמיע לנו]\u0006 שאף זו אסורה לגבוה.","\u0003ואיזהו\u0004 הנקרא \u0003אתנן\u0004 שפסול להקרבה על המזבח? — אדם \u0003האומר ל\u0004אשה \u0003זונה \"הוליך\u0004 (הרי לך) \u0003טלה זה בשכרך\", אפילו הן מאה\u0004 טלאים שנתן לה — \u0003כולן\u0004 נחשבים אתנן זונה, ו\u0003אסורין\u0004 להקרבה. \u0003וכן\u0004 אדם \u0003האומר לחבירו \"הוליך\u0004 (הרי לך) \u0003טלה זה ו\u0004בתמורה לכך \u0003תלין\u0004 (תשכב משכב ביאה) \u0003שפחתך אצל עבדי\", ר' מאיר אומר: אינו אתנן, וחכמים אומרים: אתנן.\u0004","שנינו במשנה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שהאומר לזונה שיהיה טלה זה בשכרה, \u0003ואפילו הן מאה\u0004 טלאים שנתן לה — \u0003כולן\u0004 נחשבים אתנן, ו\u0003אסורין.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[באיזה אופן מדובר]?\u0006 \u0003אילימא דשקלה אגרא\u0004 \u0005[אם תאמר\u0006 בזונה \u0005הלוקחת שכר]\u0006 \u0003מאה בהמות\u0004 — \u0003פשיטא דכולהו אסירי\u0004 \u0005[פשוט\u0006 הדבר \u0005שכולן,\u0006 כל מאה הטלאים שנתן לה, \u0005אסורים],\u0006 שהרי \u0003מה לי חד\u0004 \u0005[\u0006טלה \u0005אחד],\u0006 \u0003מה לי מאה\u0004 טלאים, ומה חידשה המשנה בכך?!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר אלא באופן \u0003דשקלה אגרא חדא\u0004 \u0005[שלוקחת\u0006 זונה זו ב\u0005שכרה\u0006 טלה \u0005אחד],\u0006 \u0003ויהיב\u0004 \u0005[ונתן]\u0006 \u0003לה מאה\u0004 טלאים, ובאה המשנה להשמיענו, שאף שפסק איתה לתת לה טלה אחד באתננה, ונתן לה מאה טלאים, אין אנו אומרים שרק טלה אחד הוא אתנן, והשאר מתנה ואין דין אתנן עליהם, אלא \u0003דכולהו\u0004 \u0005[שכולם]\u0006 \u0003מכח אתנן קאתי\u0004 \u0005[הם באים],\u0006 ודין אתנן אף עליהם.","ועוד בדין האתנן. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נתן לה\u0004 לזונה בהמה, \u0003ולא בא עליה.\u0004 וכן אם \u0003בא עליה ולא נתן לה\u0004 — \u0003אתננה מותר.\u0004 ותוהים על הדברים: אם \u0003נתן לה ולא בא עליה, \"אתננה\" קרית ליה\u0004 \u0005[אתה קורא לו]?\u0006 והרי אין אתנן אלא זה הניתן על ביאת זונה, ולא היתה כאן ביאה! \u0003ותו\u0004 \u0005[ועוד],\u0006 במקרה השני, כאשר \u0003בא עליה ולא נתן לה, מאי יהיב\u0004 \u0005[מה\u0006 הוא \u0005נתן]\u0006 \u0003לה\u0004 שנאמר בו שהוא מותר?","\u0003אלא הכי קתני\u0004 \u0005[כך הוא אומר,\u0006 כך יש לשנות בדברי חכמים אלה\u0005]:\u0006 \u0003נתן לה ו\u0004לא בא עליה מיד, אלא \u0003אחר כך בא עליה,\u0004 וכן אם \u0003בא עליה\u0004 ולא נתן לה מיד, \u0003ואחר כך נתן לה\u0004 — בשני אופנים אלה דין \u0003אתננה\u0004 זה שהוא \u0003מותר\u0004 להקרבה. ושואלים: במקרה שנתן לה טלה ורק אחר כך בא עליה, מדוע מותר? \u0003וליחול עליה\u0004 \u0005[ויחול עליו]\u0006 שם \u0003אתנן למפרע! אמר ר' אלעזר:\u0004"],["מדובר צבאופן \u0003שקדמה\u0004 (שהזדרזה) הזונה \u0003והקריבתו\u0004 את הטלה לקרבן, קודם שבא עליה נותן הטלה. וללמדנו שאין הוא נחשב אתנן. ושואלים על הסבר זה: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק המדובר]?\u0006 \u0003אי נימא דאקניה ניהליה לאלתר\u0004 \u0005[אם נאמר שהקנה לה מייד]\u0006 את הטלה, ורק אחר כך בא עליה — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שטלה זה \u0003מותר\u0004 להקרבה, שהרי הוא שלה, ו\u0003עד כאן\u0004 (עדיין) נותן הטלה \u0003לא בא עליה,\u0004 ואין הטלה, אתנן כלל!","\u0003ואלא\u0004 נאמר שהמדובר באופן שנתן לה ולאחר מכן בא עליה, ואולם כשנתן \u0003אמר לה \"לא ניקני ליך\u0004 \u0005[ייקנה לך]\u0006 אלא \u0003עד שעת ביאה\",\u0004 והיא הזדרזה והקריבתו קודם. ואולם במקרה זה יש לשאול: \u0003מי מציא מקרבה ליה\u0004 \u0005[האם\u0006 היא בכלל \u0005יכולה להקריב אותו]?\u0006 והרי \u0003\"איש כי יקדיש את ביתו קדש לה'\"\u0004(ויקרא כו, יד), \u0003אמר רחמנא\u0004 \u0005[הכתוב],\u0006 וללמדנו: \u0003מה ביתו\u0004 — הריהו \u0003ברשותו, אף כל\u0004 דבר אותו הוא מקדיש — הרי זה רק אם הוא \u0003ברשותו.\u0004 ואילו טלה זה, כל זמן שלא בא עליה, עדיין אינו שלה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 להשמיענו אלא באופן שנתן לה טלה ו\u0003אמר לה \"לא מקניה\u0004 \u0005[ייקנה]\u0006 \u0003לך\u0004 הטלה הזה אלא \u0003עד שעת ביאה, ו\u0004אולם \u0003אי מצטריך\u0004 \u0005[אם\u0006 הוא \u0005נצרך] לך\u0006 — \u0003ניקני\u0004 \u0005[ייקנה]\u0006 \u0003לך מעכשיו\".\u0004","בעי \u0005[שאל]\u0006 רב אושעיא: קדמה הזונה \u0003והקדישתו\u0004 את האתנן קודם שבא עליה הנותן, ולא הקריבתו, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? ומציעים: \u0003תפשוט ליה\u0004 \u0005[תיפתר לו]\u0006 לרב אושעיא בעייתו זו \u0003מ\u0004דברי \u0003ר' אלעזר\u0004 בהסבר דברי הברייתא, שכן \u0003אמר ר' אלעזר\u0004 שמדובר כש\u0003קדמה והקריבתו,\u0004 ונדייק: דווקא כאשר קדמה ו\u0003הקריבתו היא\u0004 לקרבן — אין זה אתנן, \u0003דהא ליתיה\u0004 \u0005[שהרי אינו]\u0006 קיים הטלה \u0003בשעת\u0004 ה\u0003ביאה, אבל\u0004 אם רק קדמה ו\u0003הקדישתו\u0004 ועדיין לא הקריבתו — הרי טלה זה \u0003אסור\u0004 משום אתנן!","ומסבירים: \u0003היא גופה\u0004 \u0005[עצמה],\u0006 דיוק הלכה זו של ר' אלעזר \u0003קמיבעיא ליה\u0004 \u0005[היא\u0006 ש\u0005נשאלה לו,\u0006 לרב אושעיא\u0005],\u0006 ובאופן זה: האם אכן יש לדייק בדברי ר' אלעזר ולומר כי דווקא כאשר קדמה ו\u0003הקריבתו,\u0004 \u0003והא ליתיה\u0004 \u0005[והרי\u0006 איפוא \u0005הוא אינו]\u0006 קיים עתה \u0003בשעת ביאה,\u0004 ולכן \u0003מותר,\u0004 שאין זה אתנן. \u0003אבל\u0004 במקרה שרק \u0003הקדישה\u0004 אותו, ועדיין לא הקריבתו \u0003בשעת ביאה —\u0004 \u0003אסור\u0004 הטלה להקרבה משום אתנן.","\u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003כיון דתנן\u0004 \u0005[ששנינו]\u0006 \u0003אמירתו לגבוה כמסירתו להדיוט,\u0004 שכל דבר שמקדישים בדיבור בלבד לשם שמים, הרי דינו לענין קניינים כמו מסירה שמוסרים חפץ להדיוט, ולכן כאשר \u0003הקדישתו\u0004 בדיבור ועדיין לא בא עליה הנותן — הטלה \u0003מותר\u0004 להקרבה ואין בו משום אתנן, שהרי בשעת הביאה אינו שלה, \u0003וכל שכן\u0004 אם \u0003הקריבתו?\u0004 ומסכמים: לא נפתרה הבעיה ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ושבים לדון עוד בברייתא שהובאה בעמוד הקודם. שנינו בה שאם \u0003בא עליה ואחר כך נתן לה\u0004 את הטלה — \u0003אתננה מותר.\u0004 ושואלים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא אחרת\u0005]:\u0006 \u0003בא עליה ו\u0004אחר כך \u0003נתן לה\u0004 טלה כאתנן לאותה ביאה, \u0003ואפילו\u0004 היתה נתינה זו \u0003עד שנים עשר חדש\u0004 (שנה) — \u0003אתננה\u0004 זה \u0003אסור\u0004 להקרבה!","\u0003אמר רב חנן בר רב חסדא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003הא\u0004 \u0005[זה],\u0006 ששנינו בברייתא האחרת — מדובר באופן שייחד לה טלה מסויים בשעת הביאה ו\u0003אמר לה\u0004 מראש \u0003\"הבעלי לי בטלה זה\",\u0004 ואז נחשב טלה זה מיד כשלה, אפילו אם נמסר לה בפועל רק לאחר זמן, ולכן הריהו אסור כאתנן. ואילו \u0003הא\u0004 \u0005[זה],\u0006 בברייתא שהובאה בעמוד הקודם — מדובר כש\u0003אמר לה \"הבעלי לי בטלה\" סתם,\u0004 שלא ייחד לה טלה מסויים בשעת הביאה. ולכן כשנתן לה לאחר ביאה — שוב אין זה נחשב אתנן, ומותר בהקרבה.","ותוהים: אף כאשר אמר לה \"הבעלי לי ב\u0003טלה זה\",\u0004 מה בכך, ומדוע נאסר הטלה כאתנן, \u0003והא\u0004 \u0005[והרי]\u0006 הוא \u0003מחוסר משיכה,\u0004 שהרי טרם נמסר לה, ולא קנתה אותו! ומשיבים: מדובר בברייתא זו \u0003בזונה גויה, דלא קניא\u0004 \u0005[שאין\u0006 היא \u0005קונה]\u0006 \u0003במשיכה,\u0004 שאין משיכה קונה בגוים. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 לעולם מדובר בברייתא זו \u0003אפילו בזונה ישראלית,\u0004 ומדובר \u0003כגון דקאי\u0004 \u0005[שהיה\u0006 הטלה \u0005עומד]\u0006 \u0003בחצרה,\u0004 וקנתה אותו מדין קנין חצר, שקונה לבעליו מה שבתוכה.","ושואלים: אם מדובר באופן שהטלה עומד בחצרה — אין זה תואם לאמור בברייתא שבא עליה ונתן לה לאחר שנים עשר חודש, ש\u0003הא יהבית\u0004 \u0005[הרי נתן]\u0006 \u0003לה מעיקרא\u0004 \u0005[מתחילה],\u0006 עוד קודם שבא עליה, וכבר קנתה אותו בחצרה. ומשיבים: מדובר במקרה \u0003דשוויה\u0004 \u0005[שעשאו]\u0006 את הטלה \u0003לה אפותיקי\u0004 \u0005[משכון],\u0006 \u0003ו\u0004כך \u0003אמר לה \"אם עד יום פלוני יהיבנא\u0004 \u0005[אתן]\u0006 \u0003לך זוזי\u0004 \u0005[זוזים,\u0006 כסף\u0005]\u0006 באתננך — \u0003מוטב,\u0004 ותחזירי לי את הטלה. \u0003ואם לאו\u0004 \u0005[לא]\u0006 אביא כסף — יהא ה\u0003טלה\u0004 עצמו \u0003באתננך\".\u0004","ודנים עוד בהגדרת אתנן זונה האסור להקרבה. \u0003אמר רב:\u0004 כל הניתן עבור ביאת זנות, \u0003אחד\u0004 (הן) \u0003אתנן\u0004 הניתן עבור ביאת \u0003זכר\u0004 על זכר, \u0003ואחד\u0004 (והן) \u0003אתנן\u0004 הניתן על ביאת \u0003כל\u0004 אחת מן ה\u0003עריות\u0004 — הרי זה בכלל \"אתנן\" ה\u0003אסור\u0004 להקרבה במקדש. \u0003חוץ מאתנן\u0004 שנותן הבעל ל\u0003אשתו\u0004 על ביאתה כשהיא \u0003נדה,\u0004 על אף האיסור שבביאה זו.","ומסביר את דעתו: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין זה נחשב אתנן? שכן באתנן לשון \u0003\"זונה\" כתיב\u0004 \u0005[נאמר]\u0006 (\"לא תביא אתנן זונה... בית ה' אלהיך\", דברים כג, יט), \u0003ו\u0004אילו \u0003הא\u0004 \u0005[זו,\u0006 אשתו הנדה\u0005]\u0006 — \u0003לאו\u0004 \u0005[לא] זונה היא. \u0006","\u0003ולוי אמר: אפילו\u0004 השכר הניתן על ביאת \u0003אשתו נדה\u0004 הריהו בכלל אתנן האסור בהקרבה במקדש. ומסביר את דעתו: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — לשון \u0003\"תועבה\" כתיב\u0004 \u0005[נאמר]\u0006 בדין אתנן הזונה ומחיר הכלב (\"כי תועבת ה' אלהיך גם שניהם\" דברים כג, יט), \u0003ו\u0004הרי \u0003הא\u0004 \u0005[זו,\u0006 ביאת אשתו הנדה\u0005]\u0006 אף היא בכלל \u0003תועבה היא,\u0004 שכן לשון \"תועבה\" נאמרה ביחס לכל העריות ובכלל זה גם אשתו נדה (\"כי כל אשר יעשה מכל התועבות האלה\". ויקרא יח, כט).","ושואלים: \u0003ו\u0004לשיטת \u0003לוי נמי\u0004 \u0005[גם כן],\u0006 \u0003והכתיב\u0004 \u0005[והרי]\u0006 נאמר \u0003\"זונה\"\u0004 בדין האתנן, ואין אשתו הנדה בכלל זונה? ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר,\u0006 להשיב\u0005]\u0006 \u0003לך\u0004 לוי על כך באופן זה: \u0003ההיא\u0004 \u0005[אותה]\u0006 \"זונה\" הכתובה בדין האתנן הריהי באה ללמד דין אחר, שאין דין אתנן נוהג אלא באשה ה\u0003זונה\u0004 המקבלת שכר מאיש על ביאתו, \u0003ולא\u0004 באיש ה\u0003זונה\u0004 המקבל שכר מאשה על ביאתו. ושואלים: \u0003ו\u0004לשיטת \u0003רב,\u0004 שלמד מהכתוב \"זונה\" שאין אתנן נוהג בבא על אשתו הנדה, \u0003ההיא\u0004 \u0005[אותה]\u0006 הלכה שאין האתנן אלא בנתינת האיש ל\u0003זונה ולא\u0004 בנתינת האשה לאיש ה\u0003זונה מנא ליה\u0004 \u0005[מנין לו]?\u0006","ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 \u0003מ\u0004מה שאמר \u0003רבי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: אין\u0004 בכלל ה\u0003אתנן\u0004 ה\u0003אסור\u0004 בהקרבה דווקא אתנן הזונה, \u0003אלא כל אתנן\u0004 שניתן על ביאתן של אלו \u0003הבאות לו בעבירה,\u0004 שאין לו בהן צד היתר. \u0003אבל אתנן\u0004 שנתן הבעל ל\u0003אשתו נדה\u0004 על ביאתו, \u0003ו\u0004כן השכר \u0003שנתן לה\u0004 לזונה, ואולם לא על ביאתו עליה, אלא כ\u0003שכר להפקעתה\u0004 (בטלה מעבודה אחרת בה היתה מקבלת שכר), \u0003ו\u0004כן שכר \u0003שנתנה לו\u0004 הזונה \u0003באתננו\u0004 — כל אלה אינם אתנן, ו\u0003מותרין\u0004 הם להקרבה.","ו\u0003אף על פי שאין ראיה\u0004 מפורשת מן הכתוב \u0003לדבר\u0004 זה, שהשכר שניתן על ידי האשה לאיש הזונה אתה אינו בכלל אתנן, מכל מקום יש \u0003זכר לדבר\u0004 זה, שכן נאמר בנבואת יחזקאל: \"לכל זונות יתנו נדה (=מוהר) ואת נתת את נדניך לכל מאהביך ותשחדי אותם לבוא אליך מסביב בתזנותיך. ויהי בך הפך מן הנשים בתזנותיך ואחריך לא זונה \u0003ובתתך אתנן ואתנן לא נתן לה ותהי להפך\"\u0004 (יחזקאל טז, לג—לד). הרי שאין זו דרך זנות, שתתן האשה שכר לבא עליה (\"ובתתך אתנן... ותהי להפך\").","ושואלים: \u0003ורב, האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"תועבה\"\u0004 שממנו למד לוי את שיטתו שאף השכר שנותן הבעל על ביאת אשתו הנדה הריהו אתנן, \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו,\u0006 לומד ממנו\u0005]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 פסוק זה להשמיענו \u0003כ\u0004דבריו של \u0003אביי,\u0004 שכן \u0003אמר אביי:\u0004 אף השכר הניתן על ביאת \u0003זונה גויה\u0004 — \u0003אתננה\u0004 זה \u0003אסור\u0004 בהקרבה.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003כתיב הכא\u0004 \u0005[נאמר כאן,\u0006 בדין איסור אתנן ומחיר כלב\u0005]\u0006 \u0003\"תועבה\"\u0004 (\"כי תועבת ה' אלהיך גם שניהם\"), \u0003וכתיב התם\u0004 \u0005[ונאמר שם,\u0006 בסיכום פרשת העריות\u0005]\u0006 \u0003\"כי כל אשר יעשה מכל התועבות האל\"\u0004 (ויקרא יח, כט), \u0003מה להלן\u0004 \u0005[הלאה,\u0006 בפרשת העריות\u0005]\u0006 מדובר דווקא ב\u0003עריות שאין קדושין תופסין בה\u0004 (שאף אם עבר אדם וקדש אחת מאלה — אין הקדושין חלים), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 בדין האתנן — אין המדובר אלא בשכר הניתן על ביאת אשה זו ש\u0003אין קדושין תופסין בה,\u0004 ובכלל זה הגויה.","\u0003ו\u0004עוד אמר אביי בדין הזונה הגויה: \u0003כהן שבא עליה\u0004 — \u0003אין לוקה עליה משום\u0004 \"אשה \u0003זונה\u0004 וחללה לא יקחו\" (ויקרא כא, ז), \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ו \u0003לא יחלל זרעו\u0004 בעמיו\" (ויקרא כא, טו) — והרי זה בא להורות שאין איסור זה אלא ב\u0003מי\u0004 שבא על אשה \u0003שזרעו\u0004 (הנולד ממנה) הריהו \u0003מיוחס אחריו\u0004 (שכן בישראל, נקבע יחוסו של הבן על פי האב), \u0003יצא\u0004 מכלל זה הבא על ה\u0003גויה\u0004 — ש\u0003אין זרעו מיוחס אחריו\u0004 אלא אחריה, והרי הילד הוא גוי.","ועוד אמר אביי בענין זה: הבא על \u0003זונה ישראלית\u0004 שאינה אשת איש — \u0003אתננה מותר\u0004 בהקרבה, \u0003מה טעם?\u0004 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003קדושין תופסין בה,\u0004 ואין אתנן אסור אלא בעריות שאין קדושין תופסים בהן, וכהן שבא עליה — \u0003לוקה משום זונה, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003זרעו\u0004 הנולד מביאה זו \u0003מיוחס אחריו. ו\u0004אילו","\u0003רבא אמר: אחד זה ואחד זה,\u0004 בין זונה גויה ובין זונה ישראלית — בשתיהן \u0003אתננה אסור,\u0004 \u0003ו\u0004בשתיהן \u0003כהן הבא עליה\u0004 — \u0003לוקה משום זונה\u0004 (ושלא כאביי הסבור שכהן הבא על הגויה אינו לוקה). \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003ילפי מהדדי\u0004 \u0005[למדות\u0006 הזונה הגויה והזונה הישראלית \u0005זו מזו],\u0006 ובאופן זה: \u0003מה\u0004 כהן הבא על \u0003זונה ישראלית\u0004 הריהו \u0003ב\u0004כלל ה\u0003לאו\u0004 (איסור כהנים בזונה) — \u0003אף\u0004 הכהן הבא על \u0003זונה גויה\u0004 הריהו \u0003בלאו. ו\u0004מן הצד האחר, \u0003מה אתנן זונה גויה אסור\u0004 — \u0003אף אתנן זונה ישראלית\u0004 הריהו \u0003אסור.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת אביי המבחין בין אתנן זונה גויה (שאסור) לאתנן זונה פנויה ישראלית (שמותר) ממה ששנינו: \u0003אחד זונה גויה, ואחד זונה ישראלית\u0004 — \u0003אתננה אסור,\u0004 הרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003אביי!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר,\u0006 להשיב\u0005]\u0006 \u0003לך אביי\u0004 כך: \u0003הא מני\u0004 \u0005[זו\u0006 הברייתא כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' עקיבא היא\u0004 ש\u0003אמר: אין קדושין תופסין בחייבי לאוין,\u0004","\u0003והא קמשמע לן\u0004 \u0005[וזה משמיע לנו]\u0006 לשיטת ר' עקיבא כי \u0003כל זונה לא תפסי\u0004 \u0005[אין תופסים]\u0006 \u0003בה קדושין, דומיא\u0004 \u0005[בדומה]\u0006 לדעתו באיסור \u0003אלמנה\u0004 לכהן גדול, שאף בזו \u0003לא תפסי\u0004 \u0005[אין תופסים]\u0006 \u0003בה קידושין,\u0004 ואולם אביי עצמו אינו סבור כן.","ושואלים: \u0003ול\u0004שיטת \u0003רבא, מאי שנא דקתני\u0004 \u0005[מה שונה,\u0006 מה המיוחד בכך \u0005שהוא שונה]\u0006 בסופה של אותה ברייתא \u0003\"כגון אלמנה לכהן גדול\u0004 וגרושה וחלוצה לכהן הדיוט\", והרי לשיטת רבא אף השכר הניתן על ביאת הפנויה הישראלית הריהו אתנן? ומשיבים: שנה זאת, כדי ללמדנו שאף הבא על הפנויה הריהו \u0003דומיא\u0004 \u0005[בדומה]\u0006 לדין \u0003אלמנה\u0004 לכהן גדול; \u0003מה אלמנה\u0004 לכהן גדול — \u0003לא לקי\u0004 \u0005[אין לוקים]\u0006 על כך \u0003עד דמתרי\u0004 \u0005[שמתרים]\u0006 \u0003בה\u0004 עדים שהדבר אסור ונענשים על כך, \u0003אף\u0004 הבא על ה\u0003זונה\u0004 — אין זה אתנן, \u0003עד\u0004 ש\u0003אמר \"הא לך\u0004 טלה זה בשכרך\", ומודיע לה בכך שהוא לזנות.","\u0003לאפוקי\u0004 \u0005[להוציא] מ\u0006דברי \u0003ר' אלעזר,\u0004 שכן \u0003אמר ר' אלעזר:\u0004 כל \u0003פנוי הבא על פנויה שלא לשם אישות\u0004 — \u0003עשאה\u0004 בכך \u0003זונה.\u0004 אכן סבור רבא שאין הדברים אמורים אלא בבא על פנויה פעם ראשונה, שאין היא נעשית בכך זונה, \u0003אבל היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 שאשה זו הריהי \u0003זונה מעיקרא\u0004 \u0005[מתחילתה]\u0006 העומדת מופקרת לביאות — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אף רבא סבור שאתננה \u0003אסור,\u0004 ורק בזה אמר שאתנן הפנויה הישראלית אסור.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 בתשובת אביי שאין להקשות מהברייתא ששנינו בה \"אחד זונה גויה ואחד זונה ישראלית — אתננה אסור\": שכן \u0003כי קתני הא\u0004 \u0005[כאשר נשנתה\u0006 הלכה \u0005זו]\u0006 — הרי זה דווקא \u0003בעריות שאין קדושין תופסין בה,\u0004 שאף הזונה הישראלית האמורה בה היתה מכלל העריות שאין תופסים בהן קדושין, ואילו אביי מדבר באופן שקידושין תופסים בה (פנויה).","ושואלים על כך: \u0003והא קתני סיפא\u0004 \u0005[והרי שנויה בסוף]\u0006 אותה ברייתא: \"כגון \u0003אלמנה לכהן גדול, גרושה וחלוצה לכהן הדיוט\u0004 — \u0003אתננה אסור\", והא הני\u0004 \u0005[והרי אלו]\u0006 — \u0003קדושין תופסין בהן!\u0004 ומשיבים: \u0003הא מני\u0004 \u0005[זו\u0006 הברייתא כשיטת \u0005מי היא]?\u0006 —"],["כשיטת \u0003ר' אלעזר היא,\u0004 ש\u0003אמר: פנוי הבא על הפנויה שלא לשום\u0004 (לשם) \u0003אישות\u0004 — \u0003עשאה זונה,\u0004 ומשום כך אתננה אסור. ואני אמרתי כדברי חכמים החולקים עליו. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' אלעזר\u0004 היא, \u0003מאי איריא\u0004 \u0005[מה מכוון,\u0006 מדוע הוזכר דווקא\u0005]\u0006 איסור \u0003אלמנה\u0004 לכהן גדול? \u0003ניתני\u0004 \u0005[שישנה]\u0006 שאתנן אסור אף בפנוי הבא על ה\u0003פנויה!\u0004","ומשיבים: \u0003אלמנה איצטריך\u0004 \u0005[נצרך]\u0006 לומר, שכן אם היה שונה בפנוי הבא על הפנויה, \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 שכך הוא הדין דווקא באתנן של פנוי הבא על הפנויה, שכן אין איסור תורה בדבר, ו\u0003הואיל ובנין אב הוא\u0004 הייתי מסיק מכאן כי אתנן הניתן לאשה האסורה עליו \u0003לא ניתסרו\u0004 \u0005[ייאסרו],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 \"כגון אלמנה לכהן גדול, גרושה וחלוצה לכהן הדיוט\" שאף שמכלל האסורים הם, הרי אלו אתנן.","שנינו במשנתנו: \u0003האומר לחבירו \"הא לך טלה זה\u0004 ותלין שפחתך אצל עבדי\". רבי אומר: אינו אתנן, וחכמים אומרים: אתנן. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003שפחה לעבד\u0004 כנעני \u0003מישרא שריא\u0004 \u0005[מותרת],\u0006 ואין זה איפוא מעשה זנות, ומדוע יהיה השכר אתנן? \u0003אמר רב הונא:\u0004 שתשכב \u0003אצלו\u0004 עצמו, אצל האדון, ולא אצל עבדו, \u0003קאמר\u0004 \u0005[הוא\u0006 התכוון \u0005לומר],\u0006 \u0003והא דקתני\u0004 \u0005[וזה ששנה,\u0006 שאמר\u0005]\u0006 שתלין אצל ה\u0003עבד\u0004 — \u0003לישנא מעליא קאמר\u0004 \u0005[\u0006ב\u0005לשון מעולה,\u0006 צנועה, \u0005הוא אמר].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי\u0004 הסבור שאין זה אתנן? \u0003אמר שמואל בר רב יצחק: לעולם\u0004 דבריו ואף כוונתו של האדון היו שתלין שפחתך אצל \u0003עבדי, ו\u0004באשר לשאלה שהרי מותרת שפחה לעבד, \u0003כי קתני\u0004 \u0005[כאשר שנינו\u0006 במשנתנו\u0005]\u0006 דין זה שאין בכך אתנן (לשיטת רבי), הרי זה \u0003בעבד עברי.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמדובר בעבד עברי, \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]\u0006 הסבורים שהרי זה אתנן, והרי \u0003שפחה\u0004 גם \u0003לעבד עברי מישרא שריא\u0004 \u0005[מותרת]?\u0006 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דלית ליה\u0004 \u0005[שאין לו,\u0006 לעבד העברי\u0005]\u0006 \u0003אשה ובנים,\u0004 ובמקרה זה, אין השפחה מותרת לעבד עברי. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם \u0003אין לו\u0004 לעבד העברי \u0003אשה ובנים\u0004 בשעה שנכנס לעבדות — \u0003אין רבו מוסר לו שפחה כנענית,\u0004 אם כבר \u0003יש לו אשה ובנים\u0004 — \u0003רבו מוסר לו שפחה כנענית.\u0004 ואילו רבי הסבור שאין זה אתנן, לדעתו אף עבד עברי שאין לו אשה ובנים רבו מוסר לו שפחה כנענית, ואין בכך משום זנות.","\u0003ואיזהו\u0004 הנקרא \u0003\"מחיר כלב\"\u0004, שאסור בהקרבה? כגון \u0003האומר לחבירו \"הוליך\u0004 \u0005(הרי לך)\u0006 \u0003טלה זה\u0004 שלי \u0003תחת כלב\u0004 זה שלך\".","\u0003וכן\u0004 הוא הדין ב\u0003שני שותפין ש\u0004ביקשו להיפרד זה מזה, ועמדו ו\u0003חלקו\u0004 ביניהם את נכסיהם. \u0003אחד נטל\u0004 בחלקו \u0003עשרה\u0004 טלאים, \u0003ואחד\u0004 נטל בחלקו \u0003תשעה\u0004 טלאים \u0003וכלב,\u0004 שבכגון זה כל הטלאים \u0003שכנגד הכלב\u0004 (שבחלקו של זה שלא לקח את הכלב) — \u0003אסור\u0004 להקרבה משום \"מחיר כלב\", \u0003ו\u0004אילו תשעת הטלאים \u0003שעם הכלב\u0004 — \u0003מותר\u0004 להקרבה.","\u0003אתנן הכלב\u0004 (אדם הנותן טלה לחבירו כתשלום על רביעת כלבתו), \u0003ו\u0004כן \u0003מחיר זונה\u0004 (אדם הנותן לחבירו טלה תחת זונה שתינתן לו לשפחה) — \u0003הרי אלו מותרין\u0004 להקרבה, \u0003ש\u0004כן \u0003נאמר\u0004 באיסור אתנן זונה ומחיר כלב \"כי תועבת ה' אלהיך גם שניהם\" (דברים כג, יט). והרי הלשון המדגישה \"שניהם\", מלמדת כי \u0003\"שנים\"\u0004 דווקא הם האסורים (אתנן זונה ומחיר כלב) — \u0003ולא ארבעה\u0004 (אף אתנן כלב ומחיר זונה). וכן ללמדנו שדווקא אתנן זונה ומחיר כלב הם עצמם אסורים, אבל \u0003ולדותיהן מותרין,\u0004 שכן נדרש הכתוב \u0003\"הן\"\u0004 שרק הם אסורים \u0003ולא ולדותיהן.\u0004","ועוד בהגדרת \"מחיר כלב\", \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"מחיר כלב\"\u0004 — \u0003זהו\u0004 הדבר הניתן כ\u0003חליפי כלב.\u0004 שכך הוא מובנה של המלה \"מחיר\" — הדבר הניתן תמורת דבר אחר, ולא דמים. \u0003וכן הוא,\u0004 הכתוב, \u0003אומר: \"תמכר עמך בלא הון ולא רבית במחיריהם\"\u0004 (תהלים מד, יג), הרי ש\"מחיר\" (\"במחיריהם\") הוא הדבר הניתן בתמורה, שאינו כסף (\"בלא הון\").","ושואלים: \u0003אימא\u0004 \u0005[אמור]\u0006 בפירוש הכתוב \"מחיר כלב\" שכוונתו לאיסור \u0003אתנן\u0004 הניתן ל\u0003זונה,\u0004 ואתנן הניתן לרביעת כלב, ואיסור מחיר כלב. ודוחים: אינך יכול לומר כן, שהרי \u0003אם כן\u0004 מספר אלו ש\u0003לא קרב\u0004 \u0005[אינם קרבים]\u0006 \u0003הוו תלתא\u0004 \u0005[הריהם שלושה],\u0006 ואילו בכתוב נאמר \u0003\"גם שניהם\"\u0004 — שנים הם האסורים, \u0003ולא שלשה!\u0004","ומסבירים את כוונת השאלה: \u0003מי קאמרינן אנן\u0004 \u0005[האם אומרים אנו]\u0006 בשאלתנו שיהיו האסורים \u0003אתנן\u0004 לבעילת זונה ואתנן לרביעת כלב, \u0003ומחיר\u0004 כלב? והלא השאלה היתה שאפשר שכוונת הכתוב \"מחיר כלב\" היא במשמעות \u0003אתנן\u0004 כלב, \u0003ולא\u0004 במשמעות \u0003מחיר\u0004 (חליפי) כלב, \u0003קאמרינן\u0004 \u0005[אומרים אנו],\u0006 ואין האסורים אלא שניים: אתנן הניתן לבעילת זונה ואתנן הניתן לרביעת כלב!","ודוחים: \u0003אם כן\u0004 כדבריך, \u0003נימא קרא\u0004 \u0005[יאמר הכתוב]\u0006 \u0003\"לא תביא אתנן זונה וכלב\",\u0004 ובאופן זה מוסבת המלה \"אתנן\" על שני אלה. ואולם \u0003מדכתיב\u0004 \u0005[מתוך שנאמר]\u0006 \u0003\"אתנן זונה ומחיר כלב\"\u0004 — \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שהכוונה לדברים נפרדים, לאתנן הניתן לזונה, ולחליפי כלב.","שנינו במשנה בדינם של שני \u0003השותפין שחלקו, אחד נטל\u0004 עשרה טלאים ואחד נטל תשעה טלאים וכלב אחד, שזה שנטל עשרה טלאים — כולם אסורים משום \"מחיר כלב\". ושואלים: מדוע נאסרו כל העשרה, \u0003ניפוק חדא דלהדי כלבא, והנך כולהו לישתרו\u0004 \u0005[נוציא אחד\u0006 הטלאים \u0003אצל,\u0004 כנגד \u0005הכלב, ואלו\u0006 השאר \u0005כולם שיותרו]?\u0006 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דטפי\u0004 \u0005[שעולה],\u0006 ששווי \u0003דמי\u0004 ה\u0003כלב\u0004 יותר \u0003מ\u0004כל \u0003חד מינייהו\u0004 \u0005[אחד מהם,\u0006 מעשרת הטלאים שכנגדו\u0005],\u0006 ואם כן אי אפשר להוציא טלה אחד ולהעמידו כנגד הכלב, והשאר יהיו מותרים, \u0003ו\u0004מאחר וכך הוא, \u0003האי טיפונא\u0004 \u0005[תוספת זו]\u0006 של דמי \u0003כלב שדי בכולהו\u0004 \u0005[הטל,\u0006 מתחלקת \u0005בכולם],\u0006 ולכן כל עשרת הטלאים נאסרים משום חלק \"מחיר כלב\" הנמצא בתוך כל אחד מהם.","עוד שנינו במשנה כי \u0003אתנן\u0004 הניתן עבור רביעת \u0003כלב ו\u0004כן הניתן כ\u0003מחיר\u0004 (כחליפין) לקבלת \u0003זונה\u0004 הרי זה \u0003מותר\u0004 להקרבה. ובענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מפרזקיא לרב אשי:\u0004"],["\u0003מנא הא מילתא דאמור רבנן\u0004 \u0005[מנין דבר זה שאמרו חכמים]\u0006 \u0003אין זנות לבהמות,\u0004 כלומר, שהאשה הנבעלת לבהמה אינה נחשבת כזונה, שהרי נאמר במשנה שאתנן כלב מותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי בתשובה: אילו היה דין \"זונה\" באשה הנבעלת לבהמה, \u0003לא נישמוט קרא לכתוב\u0004 \u0005[לא היה נשמט,\u0006 נמנע \u0005הכתוב מלומר]\u0006 זאת באופן זה \"לא תביא \u0003אתנן זונה וכלב\u0004 בית ה' אלהיך\". וכיון שלא נאמר כך, אלא \"לא תביא אתנן זונה ומחיר כלב\" הרי זה ללמדנו שאין זנות לבהמה.","ומביאים ראיה לדבר, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מנין לאתנן כלב\u0004 (אדם הנותן טלה לחבירו כתשלום על רביעת כלבתו), \u0003ו\u0004כן \u0003מחיר זונה\u0004 (אדם הנותן לחבירו טלה תחת זונה שתינתן לו לשפחה), \u0003שמותרין\u0004 להקרבה? \u0003ש\u0004כן \u0003נאמר\u0004 באיסור אתנן זונה ומחיר כלב \"כי תועבת ה' אלהיך גם שניהם\". \u0003\"שנים\"\u0004 דווקא הם האסורים (אתנן זונה ומחיר כלב) — \u0003ולא ארבעה\u0004 (אף אתנן כלב ומחיר זונה). וכן ללמדנו שדווקא אתנן זונה ומחיר כלב עצמם אסורים, אבל \u0003ולדותיהן מותרין, ש\u0004כן \u0003נאמר\u0004 בכתוב \u0003\"הן\"\u0004 — ללמדנו: הם אסורים, \u0003ולא ולדותיהן.\u0004","ועוד בענין ולדות הפסולים להקרבה, \u0003אמר רבא: ולד\u0004 הבהמה \u0003הנרבעת\u0004 על ידי אדם כשהיתה מעוברת, \u0003אסורה\u0004 להקרבה כמו האם. וטעם הדבר: שבכגון זה נחשב הדבר כאילו \u0003היא ו\u0004גם \u0003ולדה נרבעו.\u0004 וכן ולד הפרה המעוברת ה\u0003נוגחת\u0004 אדם מישראל והרגה אותו — אף ולדה \u0003אסורה\u0004 להקרבה כאמו, וטעם הדבר: שנחשב הדבר כאילו \u0003היא ו\u0004גם \u0003ולדה נגחו.\u0004","ואולם \u0003ולד\u0004 ה\u0003מוקצה\u0004 לעבודה זרה (שהוא עצמו אסור להקרבה) \u0003ו\u0004כן ולד בעל החיים ה\u0003נעבד\u0004 לעבודה זרה — \u0003מותר\u0004 להקרבה. \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — שכן המקצה בהמה מעוברת לעבודה זרה — רק \u0003לאימיה אקציה\u0004 \u0005[את אמו הקצה אותה],\u0006 ולא את ולדה. וכן העובד בהמה מעוברת כעבודה זרה — רק \u0003לאימיה פלחי לה\u0004 \u0005[את אמו עבדו אותה],\u0006 ולא את ולדה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כך את דברי רבא: אף \u0003ולד\u0004 הבהמה ה\u0003מוקצה ו\u0004ולד בעל החיים ה\u0003נעבד\u0004 — \u0003אסור. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003דניחא ליה\u0004 \u0005[ש\u0006כן \u0005נוח לו],\u0006 לאדם המקצה בהמה לעבודה זרה או לעובד אותה ב\u0003ניפחיה\u0004 \u0005[בנפחה],\u0006 שהיא מעוברת, שהריהי גדולה ונחשבת יותר. ונמצא איפוא שאף הולד הוא בכלל ההקצאה והעבודה, ונאסר בכך.","\u0003אמר רב אחדבוי בר אמי, אמר רב: המקדש\u0004 את האשה \u0003בפרש\u0004 (בהפרשות היוצאות מגופו) של \u0003שור הנסקל,\u0004 ואותו פרש שווה פרוטה — הרי זו \u0003מקודשת.\u0004 כי אף ששור הנסקל עצמו אסור בהנאה, הפרש אינו אסור בהנאה. אבל המקדש את האשה \u0003בפרש עגלי עבודה זרה\u0004 — הרי זו \u0003אינה מקודשת,\u0004 משום שפרש זה אף הוא אסור בהנאה. \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 להבחנה זו שבין פרש שור הנסקל לפרש עגלי עבודה זרה? \u0003אי בעית אימא קרא, ואי בעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 שהמקור לכך \u0005מקרא, אם תרצה אמור\u0006 שהוא מן ה\u0005סברה].\u0006","ומפרטים: \u0003אי בעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 שהוא מן \u0005סברה],\u0006 שכן \u0003ניחא ליה גבי\u0004 \u0005[נוח לו,\u0006 לבעלי עגלי עבודה זרה \u0005אצל]\u0006 ה\u0003עבודה זרה בניפחיה\u0004 \u0005[בנפחו\u0006 היתר של העגל\u0005],\u0006 שעל ידי הפרש שבתוכו הריהו נראה שמן יותר, ולכן גם הפרש מצטרף לאיסור. ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שור הנסקל\u0004 — \u0003לא ניחא ליה בניפחיה\u0004 \u0005[לא נוח לו,\u0006 לבעלי השור \u0005בנפחו\u0006 היתר], ולכן אינו נאסר בהנאה כשור עצמו.","\u0003אי בעית אימא קרא\u0004 \u0005[אם תרצה אמור מקרא]:\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 מצוות איבוד \u0003עבודה זרה כתיב\u0004 \u0005[נאמר]:\u0006 \"ולא תביא תועבה אל ביתך \u0003והיית חרם כמהו\"\u0004 (דברים ז, כו), ולשון זו \"והיית\" כוללת \u0003כל\u0004 דבר בעבודה זרה \u0003שאתה מהיה\u0004 (מתהווה, שנוצר) ממנו ש\u0003הרי הוא\u0004 \"חרם \u0003כמוהו\",\u0004 שאף הוא בכלל עבודה זרה האסורה בהנאה, ופסולה להקרבה. ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שור הנסקל כתיב\u0004 \u0005[נאמר]\u0006 \"סקול יסקל השור ו\u0003לא יאכל את בשרו\"\u0004 (שמות כא, כח), ונלמד מכאן: דווקא \u0003בשרו\u0004 הוא ש\u0003אסור,\u0004 אבל \u0003פרשו\u0004 — \u0003מותר.\u0004","ועוד בדין אתנן זונה. הבא על הזונה ו\u0003נתן לה\u0004 בשכרה \u0003מעות,\u0004 מאחר והם עצמם אינם עולים למזבח — \u0003הרי אלו מותרין\u0004 ויכול להשתמש בהן לקניית קרבנות. ואם נתן לזונה בשכרה \u0003יינות\u0004 \u0003ושמנים וסלתות, ו\u0004כן \u0003כל דבר שכיוצא בו קרב על גבי המזבח\u0004 — הרי זה \u0003אסור\u0004 בהקרבה, שהרי אלה בכלל \"אתנן זונה\" שאסור בהקרבה. ואם \u0003נתן לה\u0004 מן הדברים שהם כבר \u0003מוקדשין\u0004 להקרבתם — \u0003הרי אלו מותרין\u0004 בהקרבה. שמאחר וכבר הוקדשו הרי אינם שלו ואין אדם אוסר את שאינו שלו.","ואם נתן לה בשכרה \u0003עופות\u0004 של חולין — \u0003הרי אלו אסורין\u0004 להקרבה. ומסבירים: מה הטעם לציין הלכה זו בעופות לעצמה? — \u0003ש\u0004כן \u0003היה\u0004 מקום לומר \u0003ב\u0004עופות \u0003דין\u0004 (קל וחומר): \u0003מה אם המוקדשין\u0004 כבר, החמורים בדינם, \u0003ש\u0004כן \u0003המום פוסל בהן\u0004 — \u0003אין\u0004 דין \u0003אתנן\u0004 זונה \u0003ומחיר\u0004 כלב \u0003חל עליהן. עוף\u0004 הקל בדינו, \u0003ש\u0004כן \u0003אין המום\u0004 (שאינו חסרון אבר) \u0003פוסל בו\u0004 — \u0003אינו דין שלא יהא\u0004 דין \u0003אתנן ומחיר חל עליו?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \"לא תביא אתנן זונה ומחיר כלב בית ה' אלהיך \u0003לכל נדר\"\u0004 (דברים כג, יט) — \u0003להביא\u0004 (לרבות) אף \u0003את העוף\u0004 לאיסור, שכן אף הוא בא בנדר.","ומוסיפה המשנה לגבי ולדות הפסולים: \u0003כל\u0004 אלה (שנמנו במשנה בתחילת הפרק) \u0003האסורין לגבי\u0004 \u0005[אצל]\u0006 \u0003מזבח\u0004 — \u0003ולדותיהן מותרין\u0004 להקרבה. \u0003ר' אליעזר אמר: ולד\u0004 ה\u0003טרפה לא יקרב על גבי המזבח. ר' חנינא בן אנטיגנוס אומר:\u0004 בהמה \u0003כשירה שינקה\u0004 חלב \u0003מן\u0004 הבהמה \u0003הטרפה\u0004 — הרי זו \u0003פסולה מ\u0004ליקרב \u0003על גבי המזבח.\u0004 \u0003כל\u0004 הבהמות \u0003הקדשים שנעשו טרפה,\u0004 והריהן עתה פסולות להקרבה, ואסורות אף למאכל — \u0003אין פודין אותן\u0004 בדמים, כדי להוציאן לחולין ולהשתמש בדמיהן לקניית קרבנות במקומם. וטעם הדבר: מפני \u0003שאין פודין את הקדשים\u0004 על מנת \u0003להאכילן לכלבים\u0004 (שכן אין הטריפות ראויות אלא למאכל כלבים) שיש בדבר זה משום ביזוי הקדשים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נתן לה\u0004 לזונה בשכרה \u0003חיטין ו\u0004היא \u0003עשאתן סולת,\u0004 או \u0003זיתים ו\u0004היא \u0003עשאתן שמן,\u0004 או \u0003ענבים ו\u0004היא \u0003עשאתן יין.\u0004 נחלקו בדינם של אלה שתי ברייתות. \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 כל אלה \u0003אסורים\u0004 להקרבה, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מותרין\u0004 להקרבה. ובענין זה \u0003אמר רב יוסף\u0004 שכך \u0003תני\u0004 \u0005[שנה]\u0006 החכם \u0003גוריון\u0004 ש\u0003מן\u0004 הישוב \u0003אספורק: בית שמאי אוסרין\u0004 את כל אלה להקרבה, \u0003ו\u0004אילו \u0003בית הלל מתירין.\u0004","ובהסבר שיטותיהם: \u0003בית הלל סברי\u0004 \u0005[סבורים]:\u0006 נאמר באיסור אתנן זונה ומחיר כלב \"כי תועבת ה' אלהיך גם שניהם\" (דברים כג, יט), והרי הלשון המדגישה \"שניהם\" מורכבת היא משתי מלים: \"שנים\" \"הם\", וללמדנו: מן הכתוב \u0003\"הם\"\u0004 — דווקא הם עצמם אסורים, \u0003ולא ולדותיהן,\u0004 וכן \u0003\"הם\"\u0004 — דווקא \u0003ולא שינוייהן\u0004 (כגון קבלה בשכרה חיטים ועשתה מהן סולת).","ואילו \u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 מן האמור \u0003\"הם\"\u0004 — יש ללמוד: \u0003ולא ולדותיהן,\u0004 ומן האמור בכתוב \u0003\"גם\"\u0004 — יש ללמוד: \u0003לרבות שינוייהן,\u0004 שאף הם בכלל איסור ה\"אתנן\". ושואלים: \u0003ול\u0004שיטת \u0003בית הלל, הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"גם\"!\u0004 ואומרים: \u0003\"גם\"\u0004 זה שנאמר \u0003לבית הלל\u0004 אכן \u0003קשה.\u0004","ועוד בדין האתנן, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר באיסור הקרבת האתנן \"לא תביא אתנן זונה ומחיר כלב \u0003בית ה' אלהיך\"\u0004 הרי זה בא למעט, שאין איסור זה חל אלא בקרבנות הבאים לבית המקדש, פרט לפרה אדומה, שאין היא בכלל דין אתנן ומחיר, \u0003ש\u0004הרי \u0003אין\u0004 היא \u0003באה לבית\u0004 (המקדש), שכן שחיטתה ומעשיה הריהם שלא בבית המקדש, אלו \u0003דברי ר' אלעזר. וחכמים אומרים:\u0004 כתוב זה \"לא תביא... בית ה' אלהיך\" בא \u0003לרבות\u0004 אף \u0003את הריקועין\u0004 (ציפוי) במקדש, שאין מביאים אותם מאתנן זונה וממחיר כלב.","ומבררים: \u0003מאן\u0004 \u0005[מיהם]\u0006 \u0003חכמים\u0004 אלה? \u0003אמר רב חסדא:\u0004 כשיטת ר' יוסי בר' יהודה היא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003נתן לה\u0004 לזונה בשכרה \u0003זהב, ר' יוסי בר יהודה אומר: אין עושין\u0004 ממנו \u0003ריקועין\u0004 במקדש, \u0003אפילו\u0004 למקום הנמצא \u0003אחורי בית הכפרת,\u0004 כלומר, השטח (אחת עשרה אמה) המשתרע מכתלו המערבי של ההיכל עד לחומת העזרה, שקדושתו קלה יותר.","שנינו במשנתנו שאם \u0003נתן לה\u0004 לזונה \u0003מוקדשין\u0004 בשכרה \u0003הרי אלו מותרין,\u0004 ואם נתן לה עופות — הרי אלו אסורים משום אתנן. ובטעם דין זה בעופות, אמרה המשנה שנצרך הדבר להיאמר, שכן אף שיש קל וחומר המלמד ממוקדשים החמורים לדינם של עופות הקלים, והיה אם כן צריך למעט אף אותם מדין אתנן ומחיר, מכל מקום כתוב מיוחד (\"לכל נדר\") מלמדנו שאף העופות בכלל דין האתנן והמחיר.","ושואלים עתה לכיוון ההפוך: \u0003ויהיו\u0004 ה\u0003מוקדשין\u0004 כעופות ש\u0003אתנן ומחיר חל עליהן,\u0004 ונלמד דבר זה \u0003מקל וחומר: ומה עופות\u0004 הקלים, \u0003ש\u0004הרי \u0003אין המום פוסל בהן\u0004 — דינם ש\u0003אתנן ומחיר חל עליהן, מוקדשים\u0004 החמורים, \u0003ש\u0004הרי \u0003המום פוסל בהן\u0004 — \u0003אינו דין שאתנן ומחיר חל עליהן?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \u0003\"לכל נדר\"\u0004 — \u0003להוציא\u0004 מכלל דין האתנן והמחיר \u0003את\u0004 זה \u0003הנדור\u0004 כבר, כמוקדשים הללו שכבר נדרום למקדש.","ושואלים על כך: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאין דין אתנן ומחיר נוהג במוקדשים, הרי זה רק משום \u0003דמעטינהו קרא\u0004 \u0005[שמיעטם הכתוב]\u0006 \"לכל נדר\", ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 שאם \u0003לא מעטינהו קרא\u0004 \u0005[מיעטם הכתוב],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כי יהיב\u0004 \u0005[כאשר נתן]\u0006 \u0003לה\u0004 לזונה בשכרה \u0003מוקדשין\u0004 — \u0003חל עליהן אתנן ומחיר, והא לאו ממונא\u0004 \u0005[הרי לא ממון]\u0006 של אדם זה \u0003הוא\u0004 הקרבן שנתן לה, ואין אדם יכול לאסור דבר שאינו שלו!","\u0003אמר רב הושעיא:\u0004 מדובר כאן \u0003ב\u0004אדם שכשכר לזונה הריהו \u0003ממנה\u0004 (מצרף אותה לחבורת אוכלי קרבן הפסח) \u0003על\u0004 קרבן \u0003פסחו, ו\u0004כשיטת \u0003רבי היא\u0004 הסבור שמכלל זכויותיו של בעל קרבן הפסח להמנות עליו אחרים כתמורה לכסף שחייב להם. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הפסוק האמור בקרבן פסח \u0003\"ואם ימעט הבית מהיות משה\u0004 ולקח הוא ושכנו הקרוב אל ביתו במכסת נפשות איש לפי אכלו תכוסו על השה\" (שמות יב, ד).","ונדרש הכתוב שאם \"ימעט הבית\" ואין לו לבעל השה די מעות כדי צורכו לצרכי הפסח — הרי \"מהיות משה\" כלומר, \u0003החייהו\u0004 לבעל הבית \u0003משה\u0004 זה, שיטול מעות משכנו וימנה אותו על הפסח, ובאותן מעות יקנה צרכיו. וזהו דווקא כשחסר לו \u0003מכדי אכילה ולא\u0004 כשחסר לו \u0003מכדי מקח,\u0004 שהוא נזקק למעות לצרכים אחרים.","\u0003רבי אומר: אף מכדי מקח, שאם אין לו\u0004 מעות לצרכי עצמו שאינם לאכילה — הריהו \u0003ממנה אחרים עמו על פסחו ועל חגיגתו, ומעותיו\u0004 שקיבל עבור כך, הריהן \u0003חולין.\u0004 וטעם הדבר: \u0003שעל מנת כן הקדישו\u0004 מלכתחילה \u0003ישראל\u0004 את \u0003פסחיהן,\u0004 שאפשר יהיה להמנות עליו אחרים בתמורה למעות שיתקבלו מהם.","שנינו במשנה ש\u0003כל\u0004 אלה \u0003האסורים לגבי מזבח\u0004 ולדותיהם מותרים להקרבה. ובענין זה \u0003אמר רב:\u0004 זה ששנינו ש\u0003כל האסורים לגבי מזבח ולדותיהן מותרים,\u0004 אין זה אלא כדברי חכמים, ואין אלה דברי הכל. \u0003ו\u0004כן \u0003תני עלה\u0004 \u0005[שנינו\u0006 בברייתא תוספת \u0005עליה,\u0006 על דין זה של משנתנו\u0005]:\u0006 \u0003ור' אליעזר אוסר\u0004 את הולדות מהקרבה.","ובביאור מחלוקתם של חכמים ור' אליעזר בדין הולדות, \u0003אמר רב הונא בר חיננא, אמר רב נחמן: מחלוקת\u0004 זו עוסקת בזמן \u0003ש\u0004כבר \u0003עיברו\u0004 (היו מעוברות) בהמות הקודש \u0003ולבסוף\u0004 (ולאחר מכן), לפני שילדו את עובריהן, נפסלו להקרבה, כגון ש\u0003נרבעו\u0004 (או שהוקצו לעבודה זרה, וכן שאר הפסולים המנויים במשנה שבתחילת פרקנו). שבמקרה זה \u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 שאף העובר נפסל מהקרבה, משום ש\u0003עובר\u0004 כ\u0003ירך\u0004 (כאחד האיברים, חלק מגוף) \u0003אמו הוא\u0004 נחשב. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 שאין הולדות נפסלים להקרבה בכך, משום שעובר \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ירך אמו הוא\u0004 נחשב. \u0003אבל\u0004 במקרה שבתחילה \u0003נרבעו\u0004 (או שאר פסולים) \u0003ולבסוף\u0004 (ולאחר מכן) \u0003עיברו,\u0004 שלא היה עובר במעיה של בהמה זו בשעה שנפסלה — \u0003דברי הכל מותרין.\u0004","ואילו \u0003רבא אמר: מחלוקת\u0004 זו של חכמים ור' אליעזר הריהי דווקא \u0003כשנרבעו ולבסוף עיברו.\u0004 וטעמם של החולקים — ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 כלל הוא בהלכה כי \u0003זה וזה גורם\u0004 (כאשר ישנם שני גורמים להיווצרותו של מצב מסויים, האחד אסור והשני מותר) — הדבר שנוצר על ידם הריהו \u0003אסור.\u0004 ואף כאן, אף שהזכר שרבע את הבהמה (אבי הולד) הריהו כשר, כיון שהבהמה האם פסולה, אף הולד פסול. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כלל זה בהלכה: ש\u0003זה וזה גורם\u0004 — \u0003מותר,\u0004 ומשום כך, אף הולד הנולד במקרה זה שקודם נרבעה ורק אחר כך נתעברה הריהו כשר.","\u0003אבל\u0004 במקרה שבתחילה \u0003עיברו\u0004 (היו כבר מעוברות) \u0003ולבסוף נרבעו\u0004 — \u0003דברי הכל אסורין.\u0004 ומעירים: \u0003ורבא\u0004 הולך בזה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אמר רבא:\u0004 ה\u0003ולד\u0004 הנולד לבהמה שאסורה משום \u0003נרבעת\u0004 אף הוא \u0003אסורה,\u0004 וטעם הדבר: \u0003היא וולדה נרבעו,\u0004 וכן \u0003ולד\u0004 ה\u0003נוגחת אסור,\u0004 וטעם הדבר: \u0003היא וולדה נגחו.\u0004","\u0003לישנא אחרינא אמרי לה\u0004 \u0005[לשון אחרת אומרים אותה].\u0006 \u0003אמר רב הונא בר חיננא, אמר רב נחמן: מחלוקת\u0004 חכמים ור' אליעזר היא דווקא במקרה \u0003שנרבעו כשהן\u0004 כבר \u0003מוקדשין,\u0004 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 שאף הולדות הנולדים פסולים להקרבה, שכן אם נקריבם — ביזוי הקודש הוא, ו\u0003ביזוי\u0004 הקודש \u0003מילתא\u0004 \u0005[דבר]\u0006 הוא. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 שאפשר להקריב את הולדות, שכן לדעתם \u0003לא\u0004 נחשב הדבר כביזוי הקודש. \u0003אבל\u0004 במקרה ש\u0003נרבעו כשהן חולין\u0004 ורק לאחר מכן הוקדשו, \u0003הואיל ואשתנו\u0004 \u0005[והשתנו]\u0006 בכך, שהרי הוקדשו — \u0003דברי הכל מותרין.\u0004","ואילו \u0003רבא אמר\u0004 בשמו של \u0003רב נחמן\u0004 הסבר אחר למחלוקתם: \u0003מחלוקת\u0004 זו היא דווקא \u0003כשנרבעו כשהן חולין,\u0004 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 הרי זה ביזוי הקודש ו\u0003ביזוי מילתא\u0004 \u0005[דבר]\u0006 הוא. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003הואיל ואשתנו\u0004 \u0005[והשתנו]\u0006 — \u0003מותרין, אבל נרבעו כשהן מוקדשין\u0004 — ל\u0003דברי הכל אסורין.\u0004"],["שנינו במשנתנו שחלקו חכמים בדינו של \u0003ולד\u0004 ה\u0003טרפה,\u0004 ר' אליעזר אוסר להקריבו על המזבח, וחכמים מתירים. ומסבירים: נחלקו חכמים במסכת חולין האם בהמה טריפה יכולה ללדת, ומעתה נאמר כי \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003טרפה (אינה) ילדה\u0004 \u0005[\u0006הריהי \u0005יולדת] משכחת לה\u0006 \u0005[מוצא אתה]\u0006 את מחלוקת ר' אליעזר וחכמים זו — \u0003כגון ש\u0004בתחילה הבהמה \u0003נטרפה ולבסוף\u0004 (ולאחר מכן) \u0003עיברה\u0004 (נתעברה).","\u0003ובהא פליגי\u0004 \u0005[ובזה נחלקו]:\u0006 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003זה וזה גורם\u0004 (כאשר שני דברים, אחד של איסור ואחד של היתר גורמים היווצרותו של דבר) — הרי אותו דבר \u0003אסור,\u0004 וכן כאן, אף אם הזכר המוליד את הולד הזה כשר, כיון שאם הולד אסורה (כטריפה) — הולד אסור בהקרבה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003זה וזה גורם\u0004 — \u0003מותר,\u0004 ולכן הולד כשר להקרבה. ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003טריפה אינה חיה\u0004 (=אינה יולדת) — \u0003משכחת לה\u0004 \u0005[מוצא אתה]\u0006 את מחלוקת ר' אליעזר וחכמים \u0003כגון ש\u0004בתחילה \u0003עיברה ולבסוף נטרפה. ובהא פליגי\u0004 \u0005[ובזה נחלקו]:\u0006 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 כי ה\u0003עובר\u0004 כ\u0003ירך\u0004 (איבר, חלק מגוף) \u0003אמו הוא\u0004 נחשב, וכשם שהאם אסורה להקרבה שהרי היא טריפה, אף עוברה אסור. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 ש\u0003עובר לאו\u0004 \u0005[לא]\u0006 כ\u0003ירך אמו הוא\u0004 נחשב ולכן אין לאוסרו למזבח. ועוד בענין מחלוקת ר' אליעזר וחכמים, \u0003אמר רב הונא: מודים חכמים לר' אליעזר באפרוח\u0004 הבוקע מ\u0003ביצת\u0004 יונה \u0003טרפה\u0004 — \u0003שאסור\u0004 להקרבה. ומסביר: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 להבחנה זו בשיטת חכמים — \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי עליה\u0004 \u0005[נחלקו\u0006 חכמים \u0005עליו]\u0006 על \u0003ר' אליעזר\u0004 ואמרו שולד הטריפה מותר, \u0003אלא בולד בהמה\u0004 — \u0003דמאוירא קא רביא\u0004 \u0005[שמן האויר הוא גדל],\u0006 שאף כשהוא ברחם אמו הריהו מתפתח כגוף עצמאי, ואינו כחלק מן האם, \u0003אבל ביצת\u0004 התרנגולת ה\u0003טרפה,\u0004 ש\u0003מגופה דתרנגולתא קא רביא\u0004 \u0005[של התרנגולת היא גדלה,\u0006 מתפתחת\u0005]\u0006 — \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שאסורה, והאפרוח הבוקע ממנה פסול. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב הונא:\u0004 יש \u0003תניא דמסייע\u0004 \u0005[ברייתא שמסייעת]\u0006 \u0003לך\u0004 בשיטתך זו, שכן שנינו: \u0003מלא תרוד\u0004 (כף גדולה, שהוא שיעור עפר רקבון של מת), של \u0003רימה\u0004 (תולעי רקב) \u0003הבאה מאדם חי,\u0004 מה דינו לענין שיטמא? \u0003ר' אליעזר מטמא, וחכמים מטהרין.\u0004 ונדייק מכאן: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[נחלקו\u0006 חכמים \u0005עליו]\u0006 על ר' אליעזר \u0003אלא ברימה, דפירשא בעלמא\u0004 \u0005[שסתם פרש]\u0006 \u0003הוא\u0004 היוצא מגוף האדם, שאין הוא חלק ממנו. \u0003אבל ביצה\u0004 ש\u0003מגופה דתרנגולת\u0004 \u0005[של התרנגולת]\u0006 \u0003הוא\u0004 — \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שחלק מהתרנגולת היא, ולכן האפרוח הבוקע מביצת הטריפה הריהו אסור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: אין להביא ראיה מכאן לשיטת רב הונא, שהרי \u0003אדרבה\u0004 (להיפך), \u0003איפכא מסתברא\u0004 \u0005[ההיפך מסתבר]:\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003פליג\u0004 \u0005[חלק]\u0006 \u0003ר' אליעזר עלייהו דרבנן\u0004 \u0005[עליהם, על חכמים]\u0006 \u0003אלא ברימה\u0004 — שסבור הוא שזהו חלק מן האדם אף שיצא כשהוא חי, \u0003דאיקרי\u0004 \u0005[ש\u0006הרי \u0005נקרא]\u0006 \u0003אדם\u0004 אף \u0003מחיים \"רימה\", דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ותקות אנוש רמה ובן אדם תולעה\"\u0004 (איוב כה, ו).","","","","","\u0003אבל גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 האפרוח הבוקע מ\u0003ביצה\u0004 יש מקום לומר: \u0003אימת\u0004 \u0005[אימתי]\u0006 האפרוח \u0003גדלה\u0004 \u0005[גדל,\u0006 בוקע מהביצה\u0005]?\u0006 \u0003לכי מסרחא\u0004 \u0005[כאשר\u0006 הביצה \u0005מסריחה,\u0006 נרקבת\u0005],\u0006 \u0003וכי אסרחא\u0004 \u0005[וכאשר\u0006 היא \u0005מסריחה]\u0006 — הריהי כ\u0003עפרא בעלמא\u0004 \u0005[סתם עפר]\u0006 \u0003הוא,\u0004 ומתבטל ממנה שם התרנגולת שהטילה אותה, ואף אם היא עצמה טריפה, האפרוח הבוקע ממנה הריהו מותר להקרבה, ובכך \u0003אפילו ר' אליעזר מודה! ועוד\u0004 ראיה כנגד רב הונא, שהרי \u0003תניא בהדיא\u0004 \u0005[שנויה\u0006 ברייתא \u0005במפורש]:\u0006 \u0003מודה ר' אליעזר לחכמים באפרוח ביצת טרפה, שמותר\u0004 להקרבה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לאביי: \u0003אי תניא\u0004 \u0005[אם שנויה]\u0006 — \u0003תניא\u0004 \u0005[שנויה].\u0006 עוד שנינו במשנה: \u0003ר' חנינא בן אנטיגנוס אומר\u0004 שהבהמה ה\u0003כשרה\u0004 שינקה חלב מן הטריפה פסולה להקרבה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אילימא דמפטמא מינה\u0004 \u0005[אם תאמר\u0006 משום \u0005שהתפטמה,\u0006 גדלה ושמנה \u0003ממנה,\u0004 מהבהמה הטריפה\u0005],\u0006 \u0003אלא מעתה\u0004 תאמר בבהמה שבעליה \u0003האכילה כרשיני\u0004 (מין ירק) של \u0003עבודה זרה הכי נמי דאסירא\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאסורה],\u0006 והרי למדנו שהאכלת כרשיני עבודה זרה אוסרת רק בהמה שהוקצתה באכילה זו לעבודה זרה, ואילו סתם בהמה — אינה נאסרת בכך.","\u0003אלא\u0004 כך \u0003תני\u0004 \u0005[שנה\u0006 במשנתנו\u0005]\u0006 \u0003ר' חנינא טריטאה קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן: כגון שהניקה\u0004 את הבהמה הכשרה \u0003חלב רותח\u0004 (טרי) מהבהמה הטריפה \u0003משחרית לשחרית\u0004 (בוקר בוקר, כלומר, כל ימיה). ו\u0003הואיל ויכולה לעמוד עליה\u0004 (להתקיים מכחה) של יניקה זו \u0003מעת לעת\u0004 (יממה שלמה) עד ליניקה הבאה, נמצא איפוא שכל חיותה של הבהמה הכשרה בא מהבהמה הטריפה, ולכן היא אסורה להקרבה.","","עוד שנינו במשנה כי \u0003כל הקדשים שנעשו טרפה אין פודין\u0004 אותם, משום שאז ניתן הבשר למאכל הכלבים, ויש בדבר משום ביזוי הקודש. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים]?\u0006 — \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הכתוב \"רק בכל אות נפשך תזבח ואכלת בשר כברכת ה' אלהיך אשר נתן לך בכל שעריך הטמא והטהור יאכלנו כצבי וכאיל\" (דברים יב, טו): פסוק זה מדבר בפסולי המוקדשים שנפדו. וכך הוא נדרש: \u0003\"תזבח\"\u0004 — לשחיטתם ולאכילתם הותרו, \u0003ולא\u0004 ל\u0003גיזה\u0004 את צמרם. \u0003\"ואכלת\"\u0004 — לאכילה שלך הותר בשרם, \u0003ולא ל\u0004אכילת \u0003כלביך.\u0004 \"ואכלת \u0003בשר\"\u0004 — \u0003ולא\u0004 את ה\u0003חלב\u0004 שלהם, שאף חליבתם אסורה. \u0003מכאן\u0004 (\"ואכלת\") למדים אנו בדעת חכם זה \u0003שאין פודים את הקדשים\u0004 על מנת \u0003להאכילן לכלבים.\u0004","אכן \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 באופן שונה: \u0003\"תזבח ואכלת\"\u0004 — \u0003אין לך בהן היתר אלא משעת זביחה ואילך,\u0004 כלומר, בדברים שהנאתם באה לאחר שחיטה, והוא בשרם בלבד, ולא גיזתם או חלבם, שהרי אלו הנאות הבאות בהיותם בחיים. ונסיק איפוא כי חכם זה \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 ש\u0003פודין את הקדשים\u0004 על מנת \u0003להאכילן לכלבים.\u0004","","\u0003יש\u0004 הלכות הנוהגות רק \u0003בקדשי מזבח\u0004 (קרבנות) \u0003שאין\u0004 נוהגות \u0003בקדשי בדק הבית\u0004 (המיועדים לבניינו וצרכיו השוטפים של בית המקדש), \u0003ויש\u0004 הלכות הנוהגות רק \u0003ב\u0004בהמות שהן \u0003קדשי בדק הבית שאין\u0004 נוהגות \u0003בקדשי מזבח.\u0004","ומפרטים: \u0003שקדשי מזבח עושין תמורה\u0004 (שאם המירו עליהם בהמת חולין, חלים דיני התמורה), \u0003ו\u0004אילו \u0003קדשי בדק הבית אין עושין תמורה.\u0004 ועוד: \u0003קדשי מזבח חייבין עליו\u0004 עונש כרת \u0003משום פיגול\u0004 (אם בשעת אחת מעבודות הקרבן חשב לאכול את בשרו או להקטיר את האמורים חוץ לזמנו הראוי), וכן חייב כרת האוכל את ה\u0003נותר\u0004 (הנשאר מהם לאחר זמן אכילתם הראוי) \u0003ו\u0004כן האוכל את הקרבן כשהוא \u0003טמא\u0004 — חייב כרת."],["ואם התעברו בהמות קדשי המזבח, ונפל בהן מום, וילדו לאחר שנפדו — \u0003ולדן\u0004 אסור, \u0003ו\u0004כן \u0003חלבן אסור לאחר פדיונן. והשוחטן בחוץ\u0004 (מחוץ למקדש) — \u0003חייב\u0004 על כך כרת (אם עשה כן במזיד). ו\u0003אין\u0004 גזברי המקדש \u0003נותנין מהן\u0004 (מכספים שיוחדו לקדשי מזבח) כתשלום \u0003לאומנין\u0004 העובדים במקדש \u0003בשכרן. מה שאין כן\u0004 בכל אלה \u0003בקדשי בדק הבית.\u0004","ומצד שני \u0003יש\u0004 הלכות הנוהגות \u0003בקדשי בדק הבית,\u0004 ואין נוהגות בקדשי מזבח, ואלו הן: \u0003שסתם הקדשות\u0004 (המקדיש בסתם, בלא שפרט למה ההקדש נועד) הריהם \u0003לבדק הבית,\u0004 ולא לקדשי מזבח. \u0003הקדש בדק הבית חל על הכל,\u0004 ואף על דברים כגון עצים ואבנים, מה שאין כן בקדשי מזבח, שאין חלים אלא על דבר הראוי להקרבה. \u0003ו\u0004עוד, שבקדשי בדק הבית \u0003מועלין\u0004 (נוהג דין מעילה: שאסור להנות מהם, והנהנה מהם — חייב בקרבן אשם מעילות, ובתשלום בתוספת חומש) אף \u0003בגידוליהן\u0004 (במה שנוצר מהם, כגון חלב בהמת הקדש וביצי עופות הקדש), מה שאין כן בקדשי מזבח, שאף שאסור להנות מגידוליהם, אין הנהנה מהם חייב משום מעילה. \u0003ו\u0004עוד מדינים הנוהגים בקדשי בדק הבית ולא בקדשי מזבח, ש\u0003אין בהן\u0004 (בקדשי בדק הבית) כל צד \u0003הנאה לבעלים,\u0004 אבל בקדשי מזבח יש, כגון בשלמים שבשרם נאכל על ידי הבעלים.","על האמור במשנה שקדשי מזבח עושים תמורה שואלים: \u0003ו\u0004כי \u0003כללא\u0004 \u0005[כלל]\u0006 \u0003הוא\u0004 זה, ש\u0003כל קדשי מזבח עושין תמורה, והרי\u0004 קרבנות הבאים מן ה\u0003עופות\u0004 (תורים ובני יונה) ש\u0003קדשי מזבח הן, ו\u0004אין עושים תמורה, שכן \u0003תנן\u0004 \u0005[שנינו]:\u0006 \u0003המנחות והעופות אין עושין תמורה!\u0004 ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 את הכלל הזה — הרי זה דווקא \u0003ב\u0004קרבן הבא מן ה\u0003בהמה.\u0004","ושואלים עוד: \u0003והרי ולד\u0004 הקדשים, ש\u0003קדשי מזבח הוא,\u0004 ובא מן הבהמה, \u0003ו\u0004בכל זאת \u0003תנן\u0004 \u0005[שנינו]\u0006 ש\u0003אין הולד עושה תמורה!\u0004 ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר\u0004 כי \u0003הולד עושה תמורה.\u0004","ושואלים עוד: \u0003והרי תמורה עצמה,\u0004 ש\u0003קדשי מזבח\u0004 היא, \u0003ותנן\u0004 \u0005[ושנינו]\u0006 בה ש\u0003אין תמורה עושה תמורה!\u0004 ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 במשנתנו כלל זה, שכל קדשי מזבח עושים תמורה — הרי זה דווקא \u0003אעיקר זיבחא\u0004 \u0005[בעיקר הזבח],\u0006 בקרבן המקורי, ולא בקרבן הבא מכוחו, כגון התמורה.","ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עתה שבאת לכך,\u0006 להגדרה זו של הכלל\u0005],\u0006 הרי זו תשובה גם לשאלה שנשאלה מוולד הקדשים, ואין צורך להעמיד את משנתנו דווקא כשיטת ר' יהודה, כי \u0003אפילו\u0004 אם \u0003תימא רבנן\u0004 \u0005[תאמר\u0006 שהיא כשיטת \u0005חכמים]\u0006 הסבורים שאין הולד עושה תמורה, ואולם \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 — הרי זה דווקא \u0003אעיקר זיבחא\u0004 \u0005[בעיקר הזבח],\u0006 ולא בקרבן הבא מכוחו, כגון הולד.","\u0003ו\u0004עוד שנינו במשנה כי ממעות שיוחדו לקדשי מזבח \u0003אין נותנין מהן לאומנין\u0004 בשכרם. ומדייקים מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003קדשי בדק הבית\u0004 — \u0003נותנין. אמר ר' אבהו:\u0004 המקור לכך הוא מה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בציווי על עשיית המשכן \u0003\"ועשו לי\u0004 מקדש ושכנתי בתוכם\" (שמות כה, ח), ומשמעות המלה \"לי\" היא — משלי, וכוונת הכתוב היא איפוא שייעשה המקדש \u0003משלי,\u0004 ואף תשלום שכר האומנים העוסקים במלאכת המשכן צריך לבוא \"משלי\" — מהמוקדש לי.","שנינו במשנה עוד כי \u0003יש בקדשי בדק הבית\u0004 דינים שאין בקדשי מזבח, שסתם הקדשות הריהם לבדק הבית, ולא למזבח. ועוד, שהקדש בדק הבית חל על הכל, מה שאין כן בקדשי מזבח. ודנים בדבר: \u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנה כי \u0003סתם הקדשות לבדק הבית, וחל\u0004 הקדש בדק הבית \u0003על הכל.\u0004 ומבררים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 של משנתנו? \u0003אמר ר' חייא בר אבא, אמר ר' יוחנן:\u0004 משנתנו הריהי ש\u0003לא כ\u0004שיטת \u0003ר' יהושע.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת שקלים: \u0003המקדיש נכסיו\u0004 למקדש, בלא שפרט לאיזה הקדש הוא מקדישם, \u0003והיה בהן\u0004 (בכלל נכסיו המוקדשים) \u0003בהמה\u0004 (בהמות) ה\u0003ראויה\u0004 להקרבה \u0003לגבי\u0004 \u0005[אצל]\u0006 ה\u0003מזבח,\u0004 מהן \u0003זכרים ו\u0004מהן \u0003נקבות, ר' אליעזר אומר:\u0004 ה\u0003זכרים\u0004 הראויים לעולה — \u0003ימכרו לצרכי עולות,\u0004 לאנשים החייבים בעולה. \u0003ונקבות\u0004 — \u0003ימכרו לצרכי\u0004 קרבנות \u0003שלמים. ודמיהן\u0004 (והכסף המתקבל מהמכירה) \u0003יפלו\u0004 (יועברו) \u0003עם שאר נכסים\u0004 (שאינם ראויים להקרבה) \u0003ל\u0004צורך \u0003בדק הבית.\u0004","\u0003ר' יהושע אומר:\u0004 ה\u0003זכרים\u0004 — אין מוכרים אותם, אלא \u0003הן עצמן יקרבו עולות\u0004 \u0003ו\u0004ה\u0003נקבות\u0004 — \u0003ימכרו לצרכי\u0004 (לנצרכי) \u0003שלמים\u0004 (הבאים מן הנקבות), והן עצמן תוקרבנה כשלמים, \u0003ויביא\u0004 (ויקנה) \u0003בדמיהן\u0004 (בכסף שהתקבל ממכירתן) \u0003עולות. ושאר\u0004 ה\u0003נכסים\u0004 שאין ראויים להקרבה — יועברו \u0003לבדק הבית.\u0004 הרי שלדעת ר' יהושע בסתם הקדשות לא הכל לבדק הבית.","ומעירים: \u0003ו\u0004הסברו זה של ר' חייא בר אבא בשם ר' יוחנן במחלוקת ר' אליעזר ור' יהושע, \u0003פליגא\u0004 \u0005[חולק]\u0006 על הסברו של \u0003רב אדא בר אהבה\u0004 במחלוקת זו. שכן \u0003אמר רב אדא בר אהבה, אמר רב: בעדר שכולו זכרים\u0004 — לא נחלקו ר' אליעזר ור' יהושע, ו\u0003אפילו ר' אליעזר מודה\u0004 שהבהמות עצמן קרבות כעולה, וסיבת הדבר: \u0003דלא שביק איניש\u0004 \u0005[אין אדם עוזב,\u0006 מניח מלהקדיש\u0005]\u0006 דבר הראוי להיות \u0003קדשי מזבח ומקדיש\u0004 אותו \u0003לבדק הבית.\u0004 ואף שהקדיש סתם, בלא שפירט דבריו — ודאי הקדישם למזבח.","ו\u0003לא נחלקו\u0004 ר' אליעזר ור' יהושע \u0003אלא ב\u0004מקדיש נכסים שבהם \u0003עדר\u0004 בהמות \u0003שיש בו מחצה זכרים ומחצה נקבות,\u0004 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003אין\u0004 אדם \u0003חולק\u0004 (מחלק) \u0003את נדרו, ו\u0004במקרה זה כיון שאת ה\u0003נקבות\u0004 שבעדר — \u0003לאו\u0004 \u0005[לא]\u0006 הקדישן ל\u0003עולות,\u0004 שהרי רק העולה באה מן הזכרים, ה\u0003זכרים\u0004 שבעדר \u0003נמי\u0004 \u0005[גם כן]\u0006 — \u0003לאו\u0004 \u0005[לא]\u0006 הקדישם ל\u0003עולות.\u0004","\u0003ו\u0004אילו \u0003ר' יהושע סבר\u0004 \u0005[סבור]:\u0006 אדם \u0003חולק את נדרו,\u0004 ולכן את הזכרים עצמם הקדיש לעולות, והנקבות ימכרו לנצרכים להביא שלמים, ובדמיהן יביא עולות. נמצא שלהסברו של רב אדא בר אהבה, אף ר' אליעזר סבור שאין אדם המקדיש דבר הראוי להקרבה מניח אותו מלהקריבו ומקדישו לבדק הבית. ואין משנתנו כשיטת ר' אליעזר.","ומציעים: \u0003לישנא אחרינא אמרי לה\u0004 \u0005[לשון אחרת אומרים אותה,\u0006 את ההסבר במחלוקת ר' אליעזר ור' יהושע\u0005],\u0006 שכך \u0003אמר רב אדא בר אהבה, אמר רב: ב\u0004מקרה \u0003שלא הקדיש\u0004 אדם הקדש סתם \u0003אלא בהמה\u0004 (בהמות) הראויות להקרבה בלבד, ולא שאר נכסים איתן — \u0003אפילו ר' אליעזר מודה\u0004 שהריהן קרבות (הזכרים — לעולות, והנקבות — ימכרו לנצרכי שלמים, ובדמיהן יביא עולות). וטעם הדבר: \u0003דלא שביק איניש\u0004 \u0005[שאין אדם מניח\u0006 מלהקדיש\u0005]\u0006 דבר הראוי להיות \u0003קדשי מזבח ומקדיש\u0004 במקום זה \u0003לבדק הבית.\u0004","\u0003לא נחלקו\u0004 ר' אליעזר ור' יהושע \u0003אלא כשיש שאר נכסים עמהן, ו\u0004בזאת נחלקו: ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003אין אדם חולק את נדרו,\u0004 ו\u0003מ\u0004כיון שאת \u0003שאר\u0004 ה\u0003נכסים\u0004 הקדיש ש\u0003לא לקדשי מזבח,\u0004 שהרי אינם ראויים לכך, את ה\u0003בהמה\u0004 (הבהמות הראויות למזבח) \u0003נמי\u0004 \u0005[גם כן]\u0006 — הקדיש ש\u0003לא לקדשי מזבח. ו\u0004אילו \u0003ר' יהושע סבר\u0004 \u0005[סבור]\u0006 כי ה\u0003אדם חולק את נדרו,\u0004 ומשום כך, את הבהמות הראויות ודאי הקדיש לקרבן, ולכן הן קרבות, ושאר הנכסים קדושים לבדק הבית. ומכל מקום אף ללשון זו, שיטת ר' יהושע היא שאין אדם מניח את הראוי לקדשי מזבח מלהקדישו להקרבה, ונמצא שאין משנתנו כשיטת ר' יהושע.","\u0003ו\u0004עומדים על ההבדל בין שתי הלשונות. במשנה נאמר ש\u0003דמיהן יפלו עם שאר נכסים לבדק הבית,\u0004 ושואלים: \u0003בשלמא ללישנא בתרא\u0004 \u0005[נניח,\u0006 זה מובן, \u0005ללשון האחרונה,\u0006 השניה\u0005]\u0006 בהסברו של רב אדא בר אהבה, האומרת בהסבר שיטתו של ר' אליעזר, שאין אדם חולק את נדרו, וכיון שישנם נכסים אחרים שודאי הקדישם לבדק הבית, אף אלו הקדישם לבדק הבית. ולכן \u0003היינו דקתני\u0004 \u0005[זהו ששנינו]\u0006 \"יפלו \u0003עם שאר נכסים לבדק הבית\",\u0004 שהרי כל עיקר נפילתם לבדק הבית היא משום שאר הנכסים.","\u0003אלא ללישנא קמא\u0004 \u0005[ללשון הראשונה]\u0006 בהסברו של רב אדא בר אהבה, כי טעם שיטתו של ר' אליעזר הוא משום שאין אדם חולק בנדרו את בהמותיו, אלו לעולה ואלו לשלמים. ואף אם לא היו שאר נכסים איתן, גם כן דינן הוא כן, אם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 במשנה \u0003\"יפלו לבדק הבית\",\u0004 ואין צורך לציין \"עם שאר נכסים\". ומציינים: אכן כך ראוי לשנות במשנה זו, ו\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 בדברי ר' אליעזר: \u0003\"ודמיהן יפלו לבדק הבית\".\u0004","שנינו במשנה כי \u0003הקדש בדק הבית חל על הכל.\u0004 ולשון זו \"על הכל\", מורה שיש לכלול במוקדשים לבדק הבית אף דברים שאין מסתבר שיחול עליהם הקדש זה. ושואלים: \u0003לאיתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 בא לשון זה? \u0003אמר רבינא: לאיתויי שפויי וניבא\u0004 \u0005[להביא,\u0006 לרבות \u0005נסורת ונשורת],\u0006 שאף בנסורת העצים ועלים הנושרים מהעץ שהוקדש לבדק הבית חלה קדושת בדק הבית.","\u0003ו\u0004עוד שנינו במשנה כי \u0003מועלין בגידוליהן\u0004 (ביוצא מהם) של קדשי בדק הבית, ואין מועלים בגידוליהם של קדשי מזבח. ומבררים: \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 באה המשנה שאין מועלים בגידולי קדשי מזבח? \u0003אמר רב פפא: לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 שאין מועלים בקדושים \u0003בקדושת מזבח\u0004 וכגון ב\u0003חלב\u0004 הנחלב מן \u0003המוקדשין ו\u0004ב\u0003ביצי\u0004 ה\u0003תורין.\u0004","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 משנה\u0005]:\u0006 \u0003חלב המוקדשין וביצי תורין\u0004 — \u0003לא נהנין\u0004 מהם, \u0003ו\u0004אולם אף אם נהנו \u0003לא מועלין\u0004 בהם. \u0003במה דברים אמורים?\u0004 — \u0003בקדשי מזבח, אבל בקדשי בדק הבית,\u0004 כגון זה ש\u0003הקדיש תרנגולת\u0004 לבדק הבית — \u0003מועלין בביצתה,\u0004 או זה שהקדיש לבדק הבית \u0003חמורה\u0004 (אתון) — \u0003מועלין בחלבה.\u0004","\u0003ואפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003מועלין בגידולי מזבח, הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003גידולין דחזו\u0004 \u0005[שראויים]\u0006 \u0003למזבח, אבל גידולין\u0004 ש\u0003לא חזו\u0004 \u0005[ראויים]\u0006 \u0003למזבח\u0004 וכגון חלב וביצה — \u0003אין מועלין בהן.\u0004"],["לאחר שמנינו במשנה הקודמת את ההלכות הנוהגות בקדשי מזבח שאינן נוהגות בקדשי בדק הבית, ואת ההלכות הנוהגות בקדשי בדק הבית שאינן נוהגות בקדשי מזבח, מונים עתה את ההלכות הנוהגות באלו ובאלו: \u0003אחד\u0004 (בין) \u0003קדשי מזבח ואחד\u0004 (ובין) \u0003קדשי בדק הבית\u0004 — \u0003אין משנין אותן מקדושה לקדושה.\u0004 \u0003ו\u0004אולם \u0003מקדישין אותן,\u0004 את קדשי המזבח, \u0003הקדש עילוי\u0004 (שומא). ששמים ומעריכים את הבהמה, וערך זה ניתן לבדק הבית. \u0003ו\u0004כן \u0003מחרימין אותן,\u0004 שמקדישים אותם לצורך נתינה לכהנים שהחרמים שלהם. \u0003ו\u0004עוד הלכה המשותפת לקדשי מזבח ולקדשי בדק הבית — ש\u0003אם מתו\u0004 קדשי המזבח או קדשי בדק הבית — אלו ואלו דינם ש\u0003יקברו,\u0004 ואין הם נפדים (אפילו נפל בהם מום לפני שמתו), שכן אין פודים את הקדשים לאחר שמתו. \u0003ר' שמעון אומר:\u0004 כך הוא הדין בקדשי מזבח, אבל \u0003קדשי בדק הבית, אם מתו\u0004 — \u0003יפדו.\u0004","שנינו במשנתנו בדין השינוי בקדשים, ובענין זה \u0003אמר רב הונא: קדשי מזבח שהתפיסן\u0004 (שהחיל עליהם קדושה) \u0003ל\u0004עשות אותם \u0003חרמי\u0004 (מתנות) \u0003כהנים\u0004 — \u0003לא עשה כלום,\u0004 ומסבירים את דבריו: \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מקור הדבר\u0005]?\u0006 — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדינם של החרמים \"אך כל חרם אשר יחרים לה' מכל אשר לו מאדם ובהמה ומשדה אחוזתו לא ימכר ולא יגאל \u0003כל חרם קדש קדשים הוא לה'\"\u0004(ויקרא כז, כח), וכך הוא מפרש כתוב זה: \u0003כל חרם\u0004 שמעיקרו \u0003קדש קדשים הוי\u0004 \u0005[הינו],\u0006 שהיה מקדשי המזבח והחיל עליו בעליו קדושת חרמי כהנים — הקרבן \u0003ההוא לה' ליהוי\u0004 \u0005[יהיה]\u0006 בלבד, ואין לכהנים זכות בו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב הונא אלה ממה ששנינו בברייתא: \u0003קדשי בדק הבית שהתפיסן, בין\u0004 שהתפיסם \u0003לקדשי מזבח\u0004 החמורים מהם בקדושתם, \u0003בין\u0004 שהתפיסם \u0003לחרמי כהנים\u0004 — \u0003לא עשה\u0004 \u0003כלום.\u0004 שהרי אותם עצמם אינו יכול להפקיע מקדושת בדק הבית, ואילו טובת הנאה (לזכות בתשלום עבור העדפתו של כהן זה על פני אחר) לא שייכת בהם.","והוא הדין ב\u0003חרמי כהנים שהתפיסן, בין\u0004 שהתפיסם \u0003לקדשי מזבח, בין\u0004 שהתפיסם \u0003לקדשי בדק הבית\u0004 — \u0003לא עשה\u0004 בכך \u0003כלום.\u0004 שהרי אין לו חלק בחרמי הכהנים, ואף אין לו טובת הנאה בהם, שהרי ניתנים הם לכהנים המשמשים באותו זמן במשמרת הכהונה שבמקדש, ואינו יכול לתתם לכהן המשמש במשמרת אחרת.","ונדייק: מתוך שמנה התנא דווקא בשני אופנים אלה, קדשי בדק הבית וחרמי כהנים, נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 מכאן ש\u0003קדשי מזבח שהתפיס לחרמי כהנים\u0004 — \u0003מה שעשה עשוי,\u0004 והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003רב הונא!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רב הונא\u0004 שאין לדייק כך, שכן אפשר לומר שמנה התנא שני אופנים ושייר אופן נוסף, ו\u0003כי שיירה\u0004 \u0005[כאשר שייר]\u0006 — \u0003אהדא\u0004 \u0005[את\u0006 האופן \u0005הזה]\u0006 של המתפיס קדשי מזבח הוא ש\u0003שיירה\u0004 \u0005[שייר אותו].\u0006 ש\u0003קדשי מזבח שהתפיסן לבדק הבית\u0004 — \u0003מה שעשה עשוי,\u0004 וישלם לבדק הבית כהקדש עילוי, \u0003אבל\u0004 קדשי מזבח שהתפיסם \u0003לחרמי כהנים\u0004 — \u0003לא עשה כלום.\u0004","ושואלים: \u0003וליתנייה\u0004 \u0005[ושישנה אותו],\u0006 את דין המתפיס קדשי מזבח לחרמי כהנים, שלא עשה בכך כלום, \u0003גבי הנך\u0004 \u0005[אצל אלו],\u0006 קדשי בדק הבית וחרמי כהנים, ששנינו שהמתפיס אותם לא עשה ולא כלום. ומשיבים: ה\u0003תנא,\u0004 אופן \u0003דאית ביה תרתי\u0004 \u0005[שיש בו שני\u0006 פנים\u0005],\u0006 שאין הם מותפסים לא לקדשי מזבח ולא לחרמי כהנים — \u0003קתני\u0004 \u0005[הוא שונה],\u0006 ואולם אופן \u0003דלית ביה תרתי\u0004 \u0005[שאין בו שנים]\u0006 אלא אחד, כגון קדשי מזבח שאמנם אין מתפיסים אותם לקדשי בדק הבית, אבל מותפסים הם לחרמי כהנים — \u0003לא קתני\u0004 \u0005[אין הוא שונה].\u0006","ושואלים עוד: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 בדינם של קדשי מזבח וקדשי בדק הבית ש\u0003מקדיש אותן הקדש עילוי\u0004 ומחרימין אותן, \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ב\u0003הקדש עילוי\u0004 — \u0003לבדק הבית, ומחרימין\u0004 — הכוונה \u0003לחרמי כהן!\u0004 הרי איפוא שמתפיסים (קדשי מזבח) לחרמי כהנים, ושלא כדברי רב הונא!","ומשיבים: \u0003לא\u0004 זו כוונת המשנה, אלא \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 הן הקדש עילוי והן החרמה השנויים בה — הריהם במתפיס קדשי מזבח ל\u0003קדשי בדק הבית, ו\u0004ללמדנו כי \u0003לא שנא מפיק להו\u0004 \u0005[אין\u0006 זה \u0005משנה\u0006 אם \u0005הוציא אותם,\u0006 אמרם\u0005]\u0006 \u0003בלשון \"הקדש\"\u0004 (כגון שאמר \"הרי אלו הקדש לבדק הבית\") — הרי זה \u0003לבדק הבית, ולא שנא מפיק להו\u0004 \u0005[ואין\u0006 זה \u0005משנה\u0006 אם \u0005הוציא אותם,\u0006 אמרם\u0005]\u0006 \u0003בלשון \"חרמי\"\u0004 (כגון שאמר \"הרי אלו חרם לבדק הבית\") — הרי זה \u0003לבדק הבית.\u0004","ושואלים על כך: \u0003והא לא תני הכי\u0004 \u0005[והרי לא שנה כך]\u0006 בברייתא המוסבת על משנתנו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 \u0003בברייתא:\u0004 מקדישים אותם (קדשי מזבח) \u0003הקדש עילוי\u0004 — ל\u0003קדשי בדק הבית.\u0004 ו\u0003מחרימין אותם\u0004 (קדשי מזבח) — ל\u0003חרמי כהנים.\u0004 שלא כדברי רב הונא! \u0003ועוד, הא תניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 מפורשת: \u0003קדשי מזבח שהקדישו לחרמי כהנים\u0004 — \u0003מה שעשה עשוי,\u0004 והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לשיטת \u0003רב הונא!\u0004 ומסכמים: אכן זוהי \u0003תיובתא\u0004 \u0005[קושיה חמורה],\u0006 שנותרה ללא מענה, ונדחו דבריו.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב הונא קרא קאמר\u0004 \u0005[כתוב הוא אומר]\u0006 כמקור לדבריו, וכיצד יוסבר מקרא זה, עתה שנדחו דבריו? \u0003אמר עולא:\u0004 אין דרשת הכתוב כדרך שדרשו רב הונא, אלא כך \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"אך כל חרם אשר יחרים לה' מכל אשר לו מאדם ובהמה ומשדה אחוזתו לא ימכר ולא יגאל כל חרם קדש קדשים הוא לה'\", ולמה נאמר \u0003\"כל חרם\u0004 קדש קדשים הוא לה'\" — ללמדנו שחרם הכהנים חל אף בקדשי מזבח (\"קדש קדשים הוא לה'\"), שלא כדברי רב הונא. ושואלים על דברי עולא: והלוא מתוך שאמר עולא כי המתפיס קדשי מזבח לחרמי כהנים לא עשה כלום, משמע שהמתפיס קדשי מזבח לבדק הבית הריהו מודה שחייב בהקדש עילוי, ונותן לבדק הבית את שווי הקרבנות.","\u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר עולא הכי\u0004 \u0005[כך],\u0006 שהמתפיס קדשי מזבח לבדק הבית, הריהו חייב ב\"הקדש עילוי\", \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר עולא: המתפיס עולה לבדק הבית\u0004 — \u0003אין בה\u0004 דבר המונע מהקרבתה של עולה זו, \u0003אלא עיכוב\u0004 (המתנה לבוא)"],["ה\u0003גזברין בלבד.\u0004 משום שבעליו של הקרבן צריכים לעמוד על גבי קרבנם בשעה שהוא קרב, ובעליה של העולה שהותפסה לבדק הבית הריהם גזברי המקדש. ואולם אין הקרבן מעוכב משום שצריך לשום אותו, והרי שאף המתפיס קדשי מזבח לבדק הבית אינו חייב בהקדש עילוי, ושלא כדברי רב הונא!","ומשיבים: \u0003לעולם\u0004 דין זה שהמתפיס קדשי מזבח לחרמי המקדש צריך לתת דמי הקרבן לבדק הבית אינו מן התורה אלא רק מ\u0003רבנן\u0004 \u0005[\u0006דברי \u0005חכמים],\u0006 ומן התורה אין אלא עיכוב גזברים, ואף עולא סבור כן, \u0003ו\u0004באשר ל\u0003קרא\u0004 \u0005[הכתוב]\u0006 ממנו למד עולא דין זה (\"כל חרם קדש קדשים הוא לה'\", ויקרא כז, כח) — כתוב זה הוא אסמכתא בלבד, ולמעשה כתוב זה בא \u0003ל\u0004למדנו שיש דין \u0003מעילה\u0004 בחרמי הכהנים הוא \u0003דאתא\u0004 \u0005[שבא].\u0006","ותוהים על כך: אם כדי \u0003ל\u0004למדנו דין \u0003מעילה\u0004 בחרמי כהנים, \u0003למה ליה קרא\u0004 \u0005[לו כתוב]\u0006 מיוחד, והלא לשון \u0003קדשי קדשים\u0004 (\"קדש קדשים הוא לה'\") \u0003כתיב ביה\u0004 \u0005[נאמר בו,\u0006 בדין חרמי הכהנים\u0005],\u0006 ובכל הקדשים נוהג דין המעילה!","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שדין המעילה בחרמי כהנים נלמד ממה שנאמר בהם \"קדש קדשים\", מעתה \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר ר' ינאי: אין\u0004 הלכה זו של ה\u0003מעילה מפורשת מן התורה אלא\u0004 במועל \u0003ב\u0004קרבן \u0003עולה בלבד, ש\u0004כן \u0003נאמר\u0004 בענין אשם מעילות \u0003\"נפש כי תמעל מעל וחטאה בשגגה מקדשי ה'\u0004 והביא את אשמו... ואת חמישיתו יוסף עליו\" (ויקרא ה, טו—טז), ודין זה נאמר רק במועל בקרבנות העולה שהן \u0003המיוחדין\u0004 אך \u0003לה'.\u0004 \u0003אבל\u0004 דיני מעילה בקרבנות ה\u0003חטאת ו\u0004קרבנות ה\u0003אשם\u0004 שיש בהם אכילת כהנים ובעלים — \u0003לא נפקא\u0004 \u0005[אינם יוצאים,\u0006 נלמדים\u0005]\u0006 \u0003אלא מ\u0004דרשתו של","\u0003רבי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 נאמר בסוף פרשת השלמים \"והקטירם הכהן המזבחה... \u0003כל חלב לה'\"\u0004(ויקרא ג, טז) — והרי לשון ריבוי זו (\"כל) באה \u0003לרבות\u0004 אף את \u0003אימורי קדשים קלים ל\u0004דין ה\u0003מעילה,\u0004 וכל שכן קדשי קדשים כחטאת ואשם.","ויש לשאול באותו אופן: \u0003למה לי קרא\u0004 \u0005[כתוב]?\u0006 והרי לשון \u0003\"קדשי קדשים\" כתיב בהו\u0004 \u0005[נאמר בהם,\u0006 בקרבנות החטאת והאשם\u0005]!\u0006 \u0003אלא אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003\"קדשי קדשים\" כתיב בהו\u0004 \u0005[נאמר בהם],\u0006 עדיין \u0003בעי קרא לרביינהו\u0004 \u0005[נצרך כתוב לרבותם]\u0006 \u0003למעילה,\u0004 ואם כן \u0003חרמים נמי\u0004 \u0005[גם כן]\u0006 — \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003\"קדשי קדשים\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 — \u0003בעי קרא לרבויינהו\u0004 \u0005[נצרך כתוב לרבותם]\u0006 \u0003למעילה.\u0004","למעלה הובאו דברי עולא שהמתפיס עולה לבדק הבית אין בה אלא עיכוב גזברים בלבד. ועתה דנים בהלכה זו \u0003גופא\u0004 \u0005[כשלעצמה]:\u0006 \u0003המקדיש עולה לבדק הבית\u0004 — \u0003אין בה אלא עיכוב גיזברין בלבד. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003המקדיש עולה לבדק הבית\u0004 — \u0003אסור לשוחטה עד שתפדה,\u0004 ושלא כדברי עולא!","ומשיבים: אין הלכה זו אלא \u0003מדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים],\u0006 ומן התורה אין בה חובת הקדש עילוי, אלא עיכוב גזברים בלבד. ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, שכן \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנינו\u0006 ב\u0005סוף]\u0006 \u0003אם עבר ושחטה\u0004 בלא שנפדתה — \u0003מה שעשה עשוי,\u0004 ואין הוא חייב לפדותה. ואם היה זה דין תורה, איך אפשר עוד לומר כי מה שעשה עשוי! אלא ודאי הוא מדברי חכמים.","ושואלים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אומרים אנו, כי אין זה אלא \u0003מדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים],\u0006 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005הסוף]:\u0006 \u0003ו\u0004כל הנהנים בעולה זו, הריהם \u0003מועלין שתי מעילות\u0004 (אחת משום ההנאה מקדשי מזבח, ואחת משום ההנאה בקדשי בדק הבית), \u0003ואי\u0004 \u0005[ואם]\u0006 כדבריך שחל עליהם הקדש עילוי רק \u0003מדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים]\u0006 בלבד — יש לשאול על כך: \u0003אמאי\u0004 \u0005[מדוע]\u0006 עבר הנהנה ב\u0003שתי מעילות,\u0004 והרי אין מעילה בדבר שקדושתו מדברי חכמים בלבד? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונתו\u0005]:\u0006 \u0003וראויה\u0004 היא עולה זו (אילו היתה קדושת בדק הבית שבה מדין תורה) \u0003למעול בה שתי מעילות.\u0004","\u0003ו\u0004עוד שנינו במשנתנו, שנחלקו חכמים ור' שמעון בדין קדשי מזבח וקדשי בדק הבית, שחכמים אומרים ש\u0003אם מתו,\u0004 ולא נפדו — אי אפשר עוד לפדותם, ודינם ש\u0003יקברו.\u0004 ואילו ר' שמעון אמר שכך הדין בקדשי מזבח, אבל בקדשי בדק הבית — הרי הם נפדים.","ובהסבר מחלוקת זו \u0003אמר ר' יוחנן:\u0004 הטעם \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הוא, שכן \u0003אחד\u0004 (בין) \u0003קדשי מזבח ואחד\u0004 (ובין) \u0003קדשי בדק הבית\u0004 — \u0003היו בכלל\u0004 הנאמר בתורה בפדיון הקדשים \"ואם כל בהמה טמאה אשר לא יקריבו ממנה קרבן לה' והעמיד את הבהמה לפני הכהן. והעריך הכהן אותה בין טוב ובין רע כערכך הכהן כן יהיה\" (ויקרא כז, יא—יב). כלומר, צריך שתהא \u0003העמדה\u0004 של הבהמה לפני הכהן \u0003והערכה\u0004 של הכהן אותה. ומכאן למדנו שמי שאינה בכלל העמדה, וכגון שמתה, אף אינה בכלל הערכה, ולכן אינה נפדית אלא נקברת.","\u0003ו\u0004אילו \u0003ריש לקיש אמר:\u0004 הטעם \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הוא, שכן \u0003קדשי בדק הבית\u0004 אכן \u0003היו בכלל העמדה והערכה,\u0004 שכן אותו כתוב נאמר בהם, ומכאן, שאם מתו — אין הם נפדים אלא נקברים. ואילו \u0003קדשי מזבח\u0004 — \u0003לא היו בכלל העמדה והערכה,\u0004 שלא נאמר פסוק זה בקדשי מזבח, ולכן אם מתו — הרי אלו נפדים.","\u0003ו\u0004מסבירים: \u0003זה וזה,\u0004 הן ר' יוחנן והן ריש לקיש, \u0003מודה\u0004 כי \u0003ל\u0004שיטת \u0003ר' שמעון,\u0004 ש\u0003קדשי בדק הבית לא היו בכלל העמדה והערכה,\u0004 ולכן אף אם מתו, הריהם נפדים. \u0003וקדשי מזבח\u0004 — \u0003היו בכלל העמדה והערכה,\u0004 ולכן אם מתו — אין הם נפדים. \u0003ו\u0004כמו כן ל\u0003דברי הכל,\u0004 בין לר' יוחנן ובין לריש לקיש, כאשר הוקדש \u0003בעל מום מעיקרו\u0004 — הכל מודים ש\u0003לא היה בכלל העמדה והערכה,\u0004 ולכן אם מת — יפדה, אף שהוא בכלל קדשי מזבח.","ומקשים על הסבר זה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' שמעון אומר: קדשי בדק הבית שמתו\u0004 — \u0003יפדו.\u0004 ומעתה יש לדון בדבר: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת הסברו של \u0003ר' יוחנן,\u0004 ש\u0003אמר\u0004 כי \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003אחד זה ואחד זה,\u0004 קדשי בדק הבית וקדשי מזבח, \u0003היו בכלל העמדה והערכה,\u0004 ואם מתו אינם נפדים — \u0003היינו דאיצטריך\u0004 \u0005[זהו שנצרך]\u0006 \u0003ר' שמעון לפרושי\u0004 \u0005[לפרש]\u0006 בדיוק את דעתו, ולומר ש\u0003קדשי בדק הבית שמתו\u0004 הם ש\u0003יפדו,\u0004 שהרי אילו לא היה מפרש את דבריו, ואומר בסתם \"יפדו\" — היה מקום לומר שר' שמעון חולק בכל על חכמים, ולדעתו אף בקדשי מזבח כך הוא הדין שיפדו.","\u0003אלא ל\u0004שיטת הסברו של \u0003ריש לקיש\u0004 שאמר כי לא אמרו חכמים את דבריהם, שיקברו, אלא בקדשי בדק הבית, שהרי בקדשי מזבח סבורים הם שייפדו, \u0003למה ליה לפרושי\u0004 \u0005[לו,\u0006 לר' שמעון במשנתנו, \u0005לפרש]\u0006 את דבריו \"קדשי בדק הבית — אם מתו יפדו\", \u0003לימא\u0004 \u0005[שיאמר]\u0006 בפשטות \u0003\"אם מתו\u0004 — \u0003יפדו\",\u0004 ואנו נדע כי כוונתו לקדשי בדק הבית, שהרי בקדשי מזבח אף חכמים סבורים שיפדו!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך ריש לקיש\u0004 בתשובה לכך, כי \u0003ר' שמעון לא הוה ידע מאי\u0004 \u0005[היה יודע מה\u0006 בדיוק\u0005]\u0006 הוא זה ש\u0003אמר\u0004 ה\u0003תנא קמא\u0004 \u0005[הראשון,\u0006 חכמים\u0005],\u0006 אם מה שאמרו שיקברו מתייחס לקדשי מזבח או לקדשי בדק הבית, \u0003ו\u0004לכן \u0003הכי קאמר ליה\u0004 \u0005[כך הוא אמר לו]\u0006 ר' שמעון לתנא קמא: \u0003אי\u0004 \u0005[אם]\u0006 אמרת את דינך זה \u0003בקדשי מזבח,\u0004 שהם בכלל העמדה והערכה, ולכן אם מתו הריהם נקברים — \u0003מודינא\u0004 \u0005[מודה אני]\u0006 \u0003לך\u0004 בכך. ואולם אם אמרת את דינך זה \u0003בקדשי בדק הבית\u0004 — אין אני סבור שיקברו, אלא \u0003אם מתו\u0004 — \u0003יפדו.\u0004","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן:\u0004 נאמר \"ו \u0003אם\u0004 כל \u0003בהמה\u0004 טמאה \u0003אשר\u0004 לא \u0003יקריבו ממנה...\u0004 והעמיד את הבהמה... והעריך הכהן אותה\", ואמרו חכמים כי \u0003בבעלי מומין שיפדו הכתוב מדבר,\u0004 ולמדנו הכתוב שפדיונה של בעלת מום נעשה בהעמדה ובהערכה.","ודנים בדבר: \u0003אתה אומר\u0004 — \u0003בבעלי מומין\u0004 הכתוב מדבר, \u0003או אינו אלא בבהמה טמאה\u0004 ממש. ולימדנו הכתוב שבהמה טמאה שהוקדשה (לבדק הבית) הריהי נפדית בדרך העמדה והערכה? \u0003כשהוא\u0004 (הכתוב) שב ו\u0003אומר\u0004 כמה פסוקים לאחר מכן \"ו \u0003אם בבהמה\u0004 ה\u0003טמאה ופדה בערכך\"\u0004 (ויקרא כ״ז:כ״ז) — \u0003הרי\u0004 דין פדיון ה\u0003בהמה טמאה אמור,\u0004"],["\u0003הא\u0004 \u0005[הרי]\u0006 מעתה, שדין העמדה והערכה נאמר בבהמה טמאה עצמה, ב\u0003מה אני מקיים\u0004 את דין העמדה והערכה האמור בפסוק \u0003\"ואם כל בהמה\u0004 טמאה \u0003אשר לא יקריבו ממנה קרבן לה'\u0004 והעמיד את הבהמה לפני הכהן. והעריך הכהן אותה בין טוב ובין רע\" (ויקרא כז, יא—יב) — \u0003בבעלי מומין\u0004 שאסורים בהקרבה כטמאים, \u0003שיפדו.\u0004","ומעתה יש מקום לשאול: \u0003יכול יפדו\u0004 כל בעלי מומים, ואף \u0003על מום עובר?\u0004 — לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \"בהמה טמאה \u0003אשר לא יקריבו ממנה\"\u0004 — דווקא בבעלת מום זו \u0003שאינה קריבה כל עיקר,\u0004 כלומר, לעולם (שיש בה מום קבוע), \u0003יצתה\u0004 (יצאה) \u0003זו\u0004 שהיא בעלת מום עובר, \u0003ש\u0004אמנם \u0003אינה קריבה היום, אלא למחר. ו\u0004נסכם:","\u0003אמר רחמנא\u0004 \u0005[הכתוב],\u0006 \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003לה העמדה והערכה,\u0004 כפי שנאמר בפסוק \"והעמיד את הבהמה לפני הכהן והעריך הכהן\" וגו' (ויקרא כז,יב), ואם כן בקדשי מזבח הכתוב מדבר, שהרי בקדשי בדק הבית — אין הבחנה בין מום קבוע למום עובר, שהרי אף זו שאינה בעלת מום, גם כן נפדית. וברייתא זו שהיא מן הסיפרא (וסתם סיפרא — כשיטת ר' יהודה, החולק על ר' שמעון), כשיטת חכמים היא, ומשמע שסבורים חכמים שקדשי מזבח בכלל העמדה והערכה. וממשנתנו אנו למדים בשיטת חכמים שקדשי בדק הבית היו בכלל העמדה והערכה. הרי שלשיטת חכמים בין קדשי מזבח ובין קדשי בדק הבית בכלל העמדה והערכה היו, וכהסבר ר' יוחנן לדבריהם, ושלא כהסברו של ריש לקיש!","ומבררים עתה את שיטת ריש לקיש. \u0003אמר רב גידל, אמר רב: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ריש לקיש\u0004 ש\u0003אמר\u0004 כי \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003קדשי בדק הבית היו בכלל העמדה והערכה,\u0004 ואילו \u0003קדשי מזבח לא היו בכלל העמדה והערכה?\u0004 — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"והעמיד את הבהמה לפני הכהן. \u0003והעריך הכהן אתה בין טוב ובין רע\",\u0004 ויש לברר:","\u0003איזהו\u0004 (מהו) ה\u0003דבר שאינו חלוק\u0004 בדינו \u0003בין טוב לרע,\u0004 כלומר, בין תם לבין בעל מום? — \u0003הוי אומר: זה קדשי בדק הבית,\u0004 שבאים תמימים ובעלי מומים, \u0003ואמר קרא\u0004 \u0005[הכתוב]\u0006 \"והעריך הכהן \u0003אתה\"\u0004 — והרי לשון \"אותה\" בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קדשי מזבח,\u0004 שאינם בכלל הערכה והעמדה.","ושואלים: \u0003ו\u0004לשיטת \u0003ר' יוחנן,\u0004 הסבור שלדעת חכמים יש דין העמדה והערכה אף בקדשי מזבח, כתוב זה \u0003\"אתה\" למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 מכלל דין העמדה והערכה קדשי מזבח שהוא \u0003בעל מום מעיקרו.\u0004","ושואלים: \u0003ול\u0004שיטת ה\u0003תנא דבי\u0004 \u0005[חכם בית\u0006 המדרש\u0005]\u0006 של \u0003לוי,\u0004 ש\u0003אמר\u0004 ש\u0003אפילו\u0004 זה שהוא \u0003בעל מום מעיקרו\u0004 — גם כן היה \u0003בכלל\u0004 דין \u0003העמדה והערכה. דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003לוי: הכל היו בכלל העמדה והערכה, ואפילו בעל מום מעיקרו. וכן תני\u0004 \u0005[שנה]\u0006 \u0003לוי במתניתיה\u0004 \u0005[במשנתו]:\u0006 \u0003ואפילו חיה, ואפילו עופות\u0004 וכגון אווזים, שאינם קרבים, וכולם בכלל העמדה והערכה — \u0003והכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"אתה\",\u0004 והרי זה בא למעט, ומעתה לא הכל היו בכלל העמדה והערכה! ומסכמים: אכן \u0003קשיא\u0004 \u0005[קשה].\u0006","ומבררים את שיטת ר' שמעון שבמשנתנו, \u0003אמר רב יהודה,\u0004 \u0003אמר רב: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לשיטת \u0003ר' שמעון\u0004 ש\u0003אמר, קדשי מזבח היו בכלל העמדה והערכה\u0004 (ולכן, אם מתו — יקברו), ואילו \u0003קדשי בדק הבית לא היו\u0004 בכלל העמדה והערכה? — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"והעמיד את הבהמה לפני הכהן. \u0003והעריך הכהן אתה בין טוב ובין רע\",\u0004 ויש לדון: בפירושו של פסוק זה: \u0003איזהו\u0004 (מהו) ה\u0003דבר שחלוק\u0004 בדינו \u0003בין טוב לרע,\u0004 כלומר, בין תם לבין בעל מום — \u0003הוי אומר: זה קדשי מזבח,\u0004 \u0003ו\u0004הוסיף ו\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 הזה \"והעריך הכהן \u0003אתה\"\u0004 — והרי זה בא \u0003למעוטי\u0004 \u0005[למעט],\u0006 ומה הוא ממעט — קדשי \u0003בדק הבית,\u0004 שאין דין הערכה והעמדה בהם.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שעניינו של כתוב זה הוא בדבר שיש בו הבדל בין טוב לרע, \"והעריך הכהן אותה \u0003בין טוב לרע\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לומר, שכן הלשון \"בין טוב ובין רע\" יש בה להורות על השוואה, בעוד שהלשון \"בין טוב לרע\" מורה על הבדל. ומסכמים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר על ר' שמעון.","ושבים לדון בדעותיהם של ר' יוחנן וריש לקיש. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה שלמדנו בברייתא: קדשים ש\u0003מתו,\u0004 אם היו \u0003תמימין\u0004 — אין הם נפדים, אלא \u0003יקברו. ו\u0004אם היו \u0003בעלי מומין\u0004 — \u0003יפדו.\u0004 ומסייגים את הדברים: \u0003במה דברים\u0004 אלה \u0003אמורים?\u0004 — דווקא \u0003בקדשי מזבח, אבל בקדשי בדק הבית\u0004 — \u0003בין תמימין בין בעלי מומים,\u0004 הרי אלו \u0003יקברו.\u0004 אלה דברי חכמים.","\u0003ר' שמעון אומר: אחד קדשי מזבח ואחד קדשי בדק הבית\u0004 שמתו, אם היו \u0003תמימים\u0004 — \u0003יקברו,\u0004 ואם היו \u0003בעלי מומין\u0004 — \u0003יפדו.\u0004 והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' יוחנן\u0004 האומר שלשיטת חכמים בין קדשי מזבח ובין קדשי בדק הבית היו בכלל העמדה והערכה (ולכן אם מתו — יקברו) \u0003מרישא\u0004 \u0005[מתחילת\u0006 הברייתא\u0005].\u0006","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך ר' יוחנן: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003ב\u0004זה שהיה \u0003בעל מום מעיקרו,\u0004 ובזה חכמים סבורים שלא היה בכלל העמדה והערכה, ולכן אם מתו — יפדו, אבל במקרה שנפל בו מום לאחר הקדשתו ומת, סבורים חכמים שיקבר.","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, שכאן מדובר בבעלי מום מעיקרם, \u0003דאי תימא\u0004 \u0005[ש\u0006כן \u0005אם תאמר]\u0006 שמדובר במקרה \u0003שקדם הקדישן את מומן\u0004 — האם באופן זה \u0003ליפלוג\u0004 \u0005[יחלוק]\u0006 \u0003ר' שמעון עלה\u0004 \u0005[עליה]\u0006 ויאמר שיפדו, והרי ר' שמעון סבור שקדשי מזבח היו בכלל העמדה והערכה! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 — שמדובר בברייתא זו \u0003בבעל מום מעיקרו.\u0004 ובכך נחלקו חכמים ור' שמעון, שחכמים סבורים שדינם של קדשי בדק הבית שמתו שיקברו, ור' שמעון סבור שיפדו.","ושואלים לצד האחר: \u0003אלא\u0004 מעתה שהוכחנו מתוך דברי ר' שמעון שהברייתא עוסקת בבעל מום מעיקרו, ועל כך אמרו חכמים שקדשי מזבח בעלי מומים יפדו, אבל בבעלי מומים שקדם הקדשם למומם סבורים חכמים שיקברו \u0003לימא\u0004 \u0005[תאמר]\u0006 כי \u0003תיהוי תיובתיה\u0004 \u0005[תהיה\u0006 ברייתא זו \u0005קושיה חמורה]\u0006 על הסברו של \u0003ריש לקיש\u0004 שאמר שלשיטת חכמים קדשי מזבח לא היו בכלל העמדה והערכה (ולכן אם מתו — יפדו), ממה ששנינו בברייתא שאם היו תמימים יקברו?!","ומשיבים: \u0003ריש לקיש מוקים לה\u0004 \u0005[מעמיד אותה,\u0006 את הברייתא\u0005]\u0006 \u0003בשקדם הקדישן את מומן,\u0004 ודברי חכמים האמורים בה הריהם כשיטתו, שקדשי מזבח לא היו בכלל העמדה והערכה, ואם מתו — יפדו. ואשר לשאלה, \u0003אי הכי, ניפלוג\u0004 \u0005[אם כך,\u0006 היה מקום \u0005שיחלוק]\u0006 \u0003ר' שמעון עלה\u0004 \u0005[עליה]\u0006 ויאמר שקדשי מזבח יקברו — יש להשיב:","\u0003ריש לקיש מיפך אפיך\u0004 \u0005[הופך]\u0006 את גירסת הברייתא, \u0003והכי מותיב\u0004 \u0005[וכך\u0006 הוא \u0005מקשה]\u0006 על ר' יוחנן \u0003ממכילתא\u0004 (מדרש הלכה) \u0003אחריתי\u0004 \u0005[אחרת],\u0006 ששנינו בה: קדשים ש\u0003מתו, בין\u0004 שהיו \u0003תמימין בין\u0004 שהיו \u0003בעלי מומין\u0004 — הרי אלו \u0003יקברו.\u0004","אלו דברי חכמים, ואילו \u0003ר' שמעון אומר:\u0004 קדשי בדק הבית שמתו, \u0003תמימים\u0004 — \u0003יקברו, ובעלי מומין\u0004 — \u0003יפדו.\u0004 הרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על הסברו של ר' יוחנן \u0003מסיפא\u0004 \u0005[מסוף]\u0006 דבריהם בברייתא!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך ר' יוחנן: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003בבעל מום מעיקרו.\u0004 ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, משום \u0003דאי תימא\u0004 \u0005[שאם תאמר]\u0006 שמדובר \u0003בשקדם הקדישן את מומן,\u0004 וחכמים סבורים שקדשי בדק הבית יקברו וקדשי מזבח יפדו — \u0003ניפלוג\u0004 \u0005[שיחלוק]\u0006 \u0003ר' שמעון עלה\u0004 \u0005[עליה],\u0006 בשני האופנים הללו.","ושואלים: אם כן \u0003אלא לימא תיהוי תיובתיה\u0004 \u0005[תאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003ריש לקיש\u0004 מדוע לא חלק ר' שמעון בקדשי מזבח! ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך ריש לקיש: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003בשקדם הקדישן את מומן, ו\u0004אשר לשאלה \u0003ניפלוג\u0004 \u0005[שיחלוק]\u0006 \u0003ר' שמעון עלה\u0004 \u0005[עליה]\u0006 — \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך ריש לקיש: הכי נמי דפליג\u0004 \u0005[כך גם כן,\u0006 אמנם כן, \u0005שחולק]\u0006 \u0003ר' שמעון\u0004 אף בקדשי מזבח. ואולם כיון שהברייתא עסקה בקדשי בדק הבית, התייחס ר' שמעון רק לקדשי בדק הבית.","ודנים עוד במחלוקת ריש לקיש ור' יוחנן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: ל\u0004הסברו של \u0003ריש לקיש,\u0004 ש\u0003אמר\u0004 כי \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003קדשי מזבח לא היו בכלל העמדה והערכה, וקתני\u0004 \u0005[ושנינו]\u0006 \u0003קדשי מזבח\u0004"],["\u0003בעלי מומין\u0004 — \u0003יפדו, ומוקמינן לה\u0004 \u0005[והעמדנו אותה]\u0006 לשיטת הסברו של ריש לקיש \u0003ב\u0004בעלי מומים \u0003שקדם הקדישן את מומן,\u0004 ואף שיש בהם קדושת הגוף, שהרי כשהוקדשו היו תמימים, מכל מקום הריהם נפדים, ואם כן לכאורה \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003פודין את הקדשים להאכילן לכלבים!\u0004","ודוחים: אין זו ראיה, שכן מה ששנינו בקדשים אלה \"אם מתו\" אין הכוונה שמתו סתם, אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — שמתו בדרך שחיטה, המתרת אותם לאכילת אדם. ואף שאסור לשוחטם, מדובר \u0003ב\u0004מקרה \u0003שעבר\u0004 על האסור, \u0003ושחטן\u0004 לפני שנפדו.","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל הקדשים שנפל בהן מום, ושחטן, ר' מאיר אומר: יקברו,\u0004 שכן סבור הוא כר' שמעון האומר שקדשי מזבח היו בכלל העמדה והערכה (ולכן, אם מתו — לא יפדו, אלא יקברו). \u0003ו\u0004אילו \u0003חכמים אומרים:\u0004 לא היו אלה בכלל העמדה והערכה, ומשום כך, אף שעמד ושחטם — \u0003יפדו.\u0004","ועוד בבירור דברי הברייתא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: ל\u0004שיטת \u0003ר' שמעון,\u0004 ש\u0003אמר\u0004 כי \u0003קדשי בדק הבית לא הוו\u0004 \u0005[לא היו]\u0006 \u0003בכלל העמדה והערכה,\u0004 ולכן אם מתו — יפדו, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003תמימים\u0004 שמתו \u0003יקברו,\u0004 ולא יפדו, והרי הם לא היו בכלל העמדה והערכה? השיב ר' זירא לר' ירמיה: \u0003משום דחזו\u0004 \u0005[שראויים]\u0006 היו \u0003להקרבה\u0004 על גבי המזבח.","ומסבירים באיזה אופן היו אלה ראויים להקרבה, והרי אלו קדשי בדק הבית שאינם קרבים — \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003המתפיס\u0004 בעלי חיים \u0003תמימים ל\u0004קדשי \u0003בדק הבית, כשהן נפדין\u0004 על ידי ההקדש — אינן נפדין אלא למזבח (שנמכרים לצורך מי שחייב בהקרבה, ויקרבו על המזבח כקרבן). וטעם הדבר שאין הם נפדים לחולין, אלא למזבח — \u0003שכל\u0004 דבר הקדש \u0003הראוי למזבח,\u0004 אף שלא הוקדש למזבח, אלא לבדק הבית — \u0003אינו יוצא מידי מזבח לעולם.\u0004","ודנים עוד בשיטות ר' יוחנן וריש לקיש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי אמר זאת \u0003רבא\u0004 לאביי: \u0003ל\u0004דברי \u0003ר' יוחנן, דמוקים לה\u0004 \u0005[שמעמיד אותה,\u0006 את הברייתא הזאת\u0005]\u0006 \u0003בבעל מום מעיקרו, ו\u0004לדעתו, \u0003כולי עלמא סבירא להו\u0004 \u0005[הכל,\u0006 ר' שמעון וחכמים, \u0005הריהם סבורים]\u0006 ש\u0003בעל מום מעיקרו לא הוי\u0004 \u0005[היה]\u0006 \u0003בכלל העמדה והערכה, ו\u0004אולם על כך יש להקשות: האם אכן \u0003לא\u0004 היה בעל מום מעיקרו בכלל העמדה והערכה,","\u0003והתנן\u0004 \u0005[והרי שנינו]\u0006 במשנה במסכת בכורות: \u0003כל הקדשים שקדם מום קבוע להקדשן,\u0004 שהקדישם למזבח כשכבר היה בהם מום, ומתחילה לא נתקדשו כקרבן, אלא כדי למוכרם ולהביא בדמיהם קרבן כשר, \u0003ונפדו\u0004 מיד ההקדש — הריהם \u0003חייבין בבכורה\u0004 אם ילדו, כדין בהמות חולין, \u0003ו\u0004אם נשחטו הרי יש בהם חיוב \u0003במתנות\u0004 כהונה, כלומר, בנתינת זרוע לחיים וקיבה שנותנים לכהן מכל בהמת חולין שנשחטה, \u0003ו\u0004כשנפדים הריהם \u0003יוצאין לחולין ליגזז וליעבד,\u0004 שמותר לגזוז את צמרם ולעבוד בהם.","וכן \u0003ולדן וחלבן מותר לאחר פדיונן. ו\u0004אף קודם שנפדו, הואיל ואינם ראויים להקרבה — \u0003השוחטן בחוץ\u0004 (מחוץ לעזרה שבמקדש) — \u0003פטור,\u0004 ואינו בכלל שוחט קדשים בחוץ. וכן \u0003אין\u0004 הם \u0003עושין תמורה,\u0004 שאם אמר על בהמת חולין שתהא תמורתה — אין היא קדושה. \u0003ואם מתו\u0004 ברשות ההקדש — \u0003יפדו,\u0004 ואינם טעונים קבורה.","\u0003ו\u0004בהסבר הדברים \u0003אמר רב יהודה, אמר רב: זו\u0004 ששנינו במשנה בבכורות במקדיש בעלי מום למזבח שאם מתו דינם לפדיה, הרי אלו כ\u0003דברי ר' שמעון,\u0004 ש\u0003אמר\u0004 כי דווקא \u0003קדשי מזבח\u0004 — \u0003היו בכלל העמדה והערכה,\u0004 אבל \u0003קדשי בדק הבית\u0004 — \u0003לא היו\u0004 בכלל העמדה והערכה. \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ר' שמעון אומר: קדשי בדק הבית, אם מתו\u0004 — \u0003יפדו.\u0004 ואולם קדשי מזבח יקברו, כיון שלא היו בכלל העמדה והערכה.","\u0003ו\u0004מכל מקום, למרות שדעתו שקדשי מזבח היו בכלל העמדה והערכה, \u0003מודה ר' שמעון בבעל מום מעיקרו,\u0004 שהקדישו למזבח כשהוא בעל מום, ומת — \u0003ש\u0004הוא \u0003נפדה. מאי טעמא\u0004 \u0005[מה הטעם],\u0006 מהו המקור לכך בכתוב? — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"והעמיד את הבהמה והעריך הכהן \u0003אתה\"\u0004 (ויקרא כז, יא—יב), ולמדים: \u0003\"אתה\"\u0004 — דווקא זו שהוקדשה ורק לאחר מכן נפל בה מום, \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003בעל מום מעיקרו,\u0004 שאין הוא בכלל העמדה והערכה. \u0003אבל חכמים אומרים:\u0004 כל קדשי מזבח, ו\u0003אפילו\u0004 זה שהיה \u0003בעל מום מעיקרו\u0004 (בשעה שהוקדש) \u0003היה בכלל העמדה והערכה,\u0004 ולכן אם מתו — יקברו. והרי זה שלא כהסברו של ר' יוחנן בדברי חכמים שבמשנתנו שבעל מום מעיקרו אינו בכלל העמדה והערכה. ולשיטתו, המשנה בבכורות הריהי כשיטת חכמים (ואין אנו נצרכים להעמידה דווקא כר' שמעון, כדברי רב יהודה אמר רב)!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב פפא (או לרבא, לשיטת יש אומרים): אין להקשות מדברי רב יהודה בשם רב אלו, שכן לא היתה כוונתו לחכמים שבמשנתנו החולקים על ר' שמעון במשנתנו, אלא \u0003מאן\u0004 \u0005[מיהו]\u0006 התנא המכונה בפיו \u0003\"חכמים\"?\u0004 — \u0003תנא דבי\u0004 \u0005[חכם בית\u0006 המדרש\u0005]\u0006 של \u0003לוי.\u0004 ששנה כך בברייתות שבידו. ושאל רב פפא את אביי על הסברו זה: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאף חכמים שבמשנתנו סבורים שבעלי מום מעיקרם הריהם נפדים, מדוע אמר רב יהודה בשם רב בהסבר המשנה בבכורות כי \u0003\"זו דברי ר' שמעון\" ותו\u0004 \u0005[ויותר,\u0006 וחכמים נוספים\u0005]\u0006 \u0003לא\u0004 ציין, ומשמע איפוא מדבריו שאין זה אלא כר' שמעון בלבד. והרי דין זה הוא אף כשיטת חכמים שבמשנתנו, ולכן \u0003\"זו דברי ר' שמעון ומחלוקתו\u0004 (והחולקים עליו, במשנתנו)\"\u0003מיבעי ליה\u0004 \u0005[צריך היה לו,\u0006 לרב\u0005]\u0006 לומר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003האי דלא קתני הכי\u0004 \u0005[זה ש\u0006רב יהודה בשם רב \u0005לא שנה כך]\u0006 — \u0003משום\u0004 ש\u0003רב סבר לה\u0004 \u0005[הריהו סבור]\u0006 \u0003כריש לקיש,\u0004 ש\u0003אמר\u0004 כי \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 אלו, רק \u0003קדשי בדק הבית\u0004 — \u0003היו בכלל העמדה והערכה,\u0004 אבל \u0003קדשי מזבח\u0004 — \u0003לא היו\u0004 בכלל העמדה והערכה, ולכן אינם נפדים. ומעתה אי אפשר להעמיד את המשנה בבכורות כולה כשיטת חכמים.","שכן אף שאת ה\u0003רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005]\u0006 יכולים להעמיד כחכמים החולקים על ר' שמעון, שכן \u0003קתני\u0004 \u0005[שנינו]\u0006 בה: \u0003ואם מתו\u0004 — \u0003יפדו.\u0004 ונאמר כרב יהודה בשם רב (הסבור כריש לקיש) שאף חכמים סבורים שיפדו, שכן דין קדשים אלה הריהו כדין קדשי מזבח (כיון שהוקדשו על מנת להימכר לצורך קרבנות), \u0003ו\u0004אולם את ה\u0003סיפא\u0004 \u0005[סוף\u0006 אותה משנה\u0005]\u0006 אי אפשר להעמיד כחכמים שכן \u0003קתני\u0004 \u0005[שנינו]\u0006 בה: \u0003אם מתו\u0004 — \u0003יקברו,\u0004 ומדובר בה בשקדם הקדשם את מומם, ולשיטת חכמים דינם של אלו הוא לפדיה (להסברו של ריש לקיש שקדשי מזבח לא היו בכלל העמדה והערכה). ולכן הוצרך רב יהודה בשם רב לומר שהמשנה בבכורות הריהי דווקא כשיטת ר' שמעון ולא כשיטת חכמים שבמשנתנו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר, וכי אמנם \u0003רב כר' יוחנן סבירא ליה\u0004 \u0005[הריהו סבור],\u0006 שחכמים החולקים על ר' שמעון סבורים גם הם שקדשי מזבח היו בכלל העמדה והערכה (ולכן אם מתו — יקברו), וניתן איפוא להעמיד את המשנה כשיטתם. \u0003ודקא קשיא\u0004 \u0005[וזה שהיה קשה]\u0006 \u0003לך \"זו דברי ר' שמעון ומחלוקתו\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לומר, אכן \u0003אימא הכי נמי\u0004 \u0005[אמור,\u0006 שנה \u0005כך גם כן].\u0006","\u0003ואלו הן ה\u0004דברים האסורים בהנאה ו\u0003נקברין:\u0004 בהמת \u0003קדשים שהפילה\u0004 את עובריה — \u0003יקברו\u0004 הנפלים. וכן אם \u0003הפילה שליא\u0004 (מערכת קרומים, דרכה מקבל העובר את מזונו בהיותו שרוי במעי אמו) — הרי זו \u0003תקבר,\u0004 שודאי היה בה ולד, ונימוח בתוכה. \u0003ו\u0004כן הדין ב\u0003שור הנסקל\u0004 שנידון לסקילה על שהרג אדם, שהוא נקבר; \u0003ו\u0004ב\u0003עגלה ערופה\u0004 שהופרשה לכפרה על העיר הקרובה אל מקום הימצאו של אדם שנרצח ולא נודע מי רצחו, שהיא אסורה בהנאה (לפי שנאמר בה לשון כפרה, \"כפר לעמך ישראל\". דברים כא, ח); \u0003ו\u0004ב\u0003צפרי\u0004 ה\u0003מצורע\u0004 הבאות לטהרתו; \u0003ו\u0004ב\u0003שיער נזיר\u0004 שנטמא, ומגלח ראשו קודם שמתחיל בנזירות חדשה;","\u0003ו\u0004ב\u0003פטר חמור,\u0004 בכור החמור המיוחד מכל שאר החיות הטמאות שיש בו קדושה וצריך לפדותו בשה, ואם אין פודים אותו יש לעורפו. ונלמד מגזירה שווה מעגלה ערופה שאף הוא אסור בהנאה; \u0003ו\u0004בתערובת \u0003בשר בחלב\u0004 שהתבשלו יחד; \u0003ו\u0004בבהמות \u0003חולין שנשחטו בעזרה.\u0004 שכל אלה אסורים בהנאה, והריהם חייבים בקבורה. \u0003ר' שמעון אומר: חולין שנשחטו בעזרה\u0004 — \u0003ישרפו,\u0004 וכדין הקדשים שנפסלו בעזרה, שנשרפים הם. \u0003וכן\u0004 בכלל זה גם \u0003חיה שנשחטה בעזרה,\u0004 שאף שאין היא כבהמה שממנה מביאים לקרבנות, גזרו עליה שתישרף.","\u0003ואלו הן הנשרפין: חמץ בפסח\u0004 — \u0003ישרף. ותרומה טמאה\u0004 תישרף אף היא. \u0003והערלה\u0004 (פירות העץ בשלש השנים הראשונות, האסורים באכילה), \u0003וכלאי הכרם\u0004 (תבואה או ירק שנזרעו בכרם והריהם אסורים בהנאה), \u0003את\u0004 הדברים \u0003שדרכן לשרוף\u0004 (כגון מאכלים) — \u0003ישרוף, ואת שדרכן להקבר\u0004 ולא להישרף (כגון משקים) — \u0003יקבר. ומדליקין בפת ובשמן של תרומה\u0004 שנטמאה, אף שנהנה מהם הכהן אגב שריפתם. \u0003כל הקדשים שנשחטו\u0004 על מנת לאכול מבשרם או להקריב את החלקים הקרבים על המזבח \u0003חוץ לזמנן\u0004 (לאחר זמן אכילתם או הקרבתם הראוי), ובכך התפגלו הקרבנות. \u0003ו\u0004כן אם נשחטו על מנת לאוכלם או להקריבם \u0003חוץ למקומן\u0004 (שלא במקומם הראוי), ובכך נפסלו הקרבנות — \u0003הרי אלו ישרפו.\u0004"],["קרבן \u0003אשם תלוי\u0004 שחיובו הוא על ספק חטא, ונודע לבעליו לפני שנזרק דם הקרבן שהוא לא חטא — \u0003ישרף\u0004 הקרבן, שהוא כקרבן פסול. \u0003ר' יהודה אומר: יקבר.\u0004 קרבן \u0003חטאת העוף הבאה על הספק,\u0004 כגון ספק לידה (שהפילה האשה, וספק אם היה זה ולד) — \u0003תשרף,\u0004 כשאר קרבנות פסולים (שכן מן הספק אין היא נאכלת, והרי היא עוף שנמלק, שאסור באכילה משום נבילה). \u0003ר' יהודה אומר: יטילנה לאמה\u0004 (תעלת מים שעברה בבית המקדש, לצורך ניקוז הנוזלים אל מחוצה לו), שאף העוף הרך, נמוח הוא בקילוח המים, ויוצא הוא בכך אל מחוץ למקדש.","וכלל הוא: \u0003כל הנקברין\u0004 — \u0003לא ישרפו, וכל הנשרפין\u0004 — \u0003לא יקברו. ר' יהודה אומר: אם רצה להחמיר על עצמו לשרוף את הנקברין\u0004 — \u0003רשאי, אמרו לו\u0004 חכמים לר' יהודה: \u0003אינו מותר לשנות,\u0004 שכן מתוך חומרה זו ששורפם הריהו בא לידי הקלה, שכן אפר הנשרפים מותר בהנאה, מה שאין כן באפר הנקברים.","שנינו במשנתנו בין איסורי הנאה שדינם קבורה, ש\u0003שער הנזיר יקבר.\u0004 ובענין זה \u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה סתירה\u0005]\u0006 החכם \u0003טבי לרב נחמן: תנן\u0004 \u0005[שנינו]\u0006 במשנתנו זו כי \u0003שער הנזיר יקבר, ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו במשנה במסכת ערלה: \u0003האורג\u0004 שיעור המכונה \u0003\"מלא הסיט\"\u0004 (המרחק שבין האצבע והאמה שבכף היד) \u0003מצמר בכור,\u0004 האסור בהנאה כשאר קדשים, \u0003בבגד\u0004 — \u0003ידלק\u0004 (ישרף) \u0003הבגד.\u0004 וכן האורג \u0003משער הנזיר\u0004 או משערו של \u0003פטר חמור בשק\u0004 — \u0003ידלק השק.\u0004 הרי שדינו של שער הנזיר בשריפה ולא בקבורה!","","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לטבי: אין זו סתירה, אלא \u0003כאן,\u0004 במשנתנו, ששנינו שדין שער נזיר בקבורה — מדובר \u0003בנזיר טמא\u0004 (שנטמא), המגלח שער ראשו ומתחיל בנזירות חדשה. ואילו \u0003כאן\u0004 במשנה במסכת ערלה, ששנינו שדין שער נזיר בשריפה — מדובר \u0003ב\u0004שערו של \u0003נזיר טהור,\u0004 המשלים את ימי נזירותו, ומגלח את שער ראשו, ודינו של זה בשריפה, ככתוב בו: \"וזאת תורת הנזיר ביום מלאת ימי נזרו... וגלח הנזיר פתח אהל מועד את ראש נזרו ולקח את שער ראש נזרו ונתן על האש אשר תחת זבח השלמים\" (במדבר ו, יג—יח). \u0003אמר ליה\u0004 \u0005[לו]\u0006 טבי לרב נחמן: \u0003שנית\u0004 (תרצת) את הסתירה מ\u0003נזיר\u0004 על \u0003נזיר,\u0004 ואולם הסתירה מ\u0003פטר חמור\u0004 על \u0003פטר חמור\u0004 עדיין \u0003קשיא\u0004 \u0005[קשה],\u0006 שהרי במשנתנו שנינו שדינו (ובכלל זה שערו) לקבורה, ובמשנה בערלה שנינו שדין שערו לשריפה! \u0003אישתיק\u0004 \u0005[שתק]\u0006 רב נחמן \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 לטבי על שאלתו זו \u0003ו\u0004אף \u0003לא מידי\u0004 \u0005[דבר]\u0006 שיש בו תשובה, אלא \u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003מידי שמיע לך בהא\u0004 \u0005[שמעת בזה דבר\u0006 תירוץ לשאלה זו מפי אחרים\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 טבי לרב נחמן: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת\u0004 בתירוץ סתירה זו: \u0003כאן\u0004 במשנה בערלה — מדובר בשערו של פטר חמור שנארג \u0003בשק,\u0004 ודינו של זה אכן לשריפה, ואילו \u0003כאן\u0004 במשנתנו — מדובר \u0003בשער\u0004 פטר חמור כשלעצמו, שדינו בקבורה ולא בשריפה.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ששני תירוצים אלה, של רב נחמן ושל רב ששת, נאמרו גם על ידי חכמים אחרים, שכך \u0003אמר ר' יוסי בר' חנינא:\u0004 אין זו סתירה בין המשניות, שכן \u0003כאן\u0004 במשנה בערלה — מדובר בשער נזיר ופטר חמור שנארג \u0003בשק,\u0004 ואילו \u0003כאן\u0004 במשנתנו — מדובר \u0003בשער\u0004 נזיר ופטר חמור כשלעצמו. ואילו \u0003ר' אלעזר אמר: כאן\u0004 במשנה בערלה — מדובר \u0003בנזיר טהור, כאן\u0004 במשנתנו — מדובר \u0003בנזיר טמא.\u0004","","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרב ששת: לדעתך שיש להבחין בין השער כשלעצמו לבין השער שנארג בשק, שדינו לשריפה, אם כן \u0003ליבטל\u0004 \u0005[שיתבטל]\u0006 שער הנזיר ופטר החמור שנארגו ב\u0003שק ברובא\u0004 \u0005[ברוב]\u0006 החומר האחר (של היתר) שממנו נארג השק, ולא ישרף השק! \u0003אמר רב פפא:\u0004 מדובר כאן \u0003ב\u0004מקרה שעשה מהשער האסור שנארג בשק כעין צורת \u0003ציפורתא\u0004 \u0005[ציפור]\u0006 ליפות את השק בכך, והרי זה כדבר חשוב שאינו מתבטל. ותוהים על תשובה זו: \u0003ציפורתא\u0004 \u0005[ציפור]\u0006 — מדוע יאסר השק בכך, ויצא לשריפה? \u0003לישלופינהו\u0004 \u0005[שישלוף אותם,\u0006 את הצורות הרקומות בשק\u0005]\u0006 מתוך השק, ויותר השק! \u0003אמר ר' ירמיה\u0004 תירוץ אחר לסתירה שבין משנתנו למשנה בערלה: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו,\u0006 שבמסכת ערלה, כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר\u0004 במשנתנו ש\u0003אם רצה להחמיר על עצמו לשרוף את הנקברים\u0004 — \u0003רשאי.\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קא קשיא לן לשלופינהו\u0004 \u0005[היה קשה לנו שישלפם],\u0006 \u0003ואת מוקמת לה\u0004 \u0005[ואתה מעמיד אותה]\u0006 \u0003כר' יהודה,\u0004 והרי אף לשיטת ר' יהודה זו, אם אפשר לתקן את השק על ידי שליפת הרקמה האסורה בתוכו, אין מקום להחמיר בו לשורפו!","השיב לו: \u0003הכי קאמינא\u0004 \u0005[כך הוא שאמרתי,\u0006 זו היתה כוונתי\u0005]:\u0006 \u0003אם אפשר לשלופינהו\u0004 \u0005[לשלוף אותם]\u0006 — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אוקמה\u0004 \u0005[העמד אותה]\u0006 \u0003כר' יהודה,\u0004 ש\u0003אמר אם רצה להחמיר על עצמו לשרוף את הנקברין\u0004 — \u0003רשאי.\u0004","שנינו במשנה: \u0003\"ואלו הן הנשרפין:\u0004 חמץ בפסח — ישרף\". ומעירים: \u0003אמר מר\u0004 \u0005[החכם,\u0006 תנא משנתנו\u0005]:\u0006 \u0003חמץ בפסח\u0004 — \u0003ישרף.\u0004 הרי איפוא ש\u0003סתם\u0004 (שנה בסתם) \u0003לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא\u0004 של משנתנו \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר\u0004 ש\u0003אין ביעור חמץ אלא שרפה,\u0004 ושלא כדעת חכמים החולקים עליו וסוברים שביעור חמץ נעשה בכל אופני הביעור.","שנינו במשנה ש\u0003תרומה טמאה\u0004 תישרף. \u0003ו\u0004באשר לדינם של \u0003הערלה\u0004 וכלאי הכרם שדרכם לשרוף — ישרוף, ואת שדרכם להיקבר — יקבור. ומסבירים, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד,\u0004 מה הם אלו שדרכם בשריפה ומה הם אלו שאין דרכם בשריפה? — \u0003אוכלין\u0004 — הריהם דבר שדרכו \u0003בשרפה, משקין\u0004 (דברי משקה) — הריהם דבר שאין דרכו בשריפה, ודינו איפוא \u0003בקבורה.\u0004 \u0003ו\u0004עוד שנינו במשנה כי \u0003חטאת העוף\u0004 הבאה על הספק תישרף, ור' יהודה אומר שיטילנה לאמה (תעלת המים העוברת בעזרה). ובשיטתו של ר' יהודה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה: חטאת העוף הבאה על הספק\u0004 — \u0003יטילנה לאמה, ו\u0004כיצד? — \u0003מנתחה אבר אבר\u0004 לעצמו, \u0003ו\u0004לאחר מכן \u0003זורקן\u0004 לאברים \u0003לאמה, ו\u0004הריהי מתגלגלת והולכת עם הנוזלים שבתעלה זו \u0003לנחל קדרון\u0004 אל מחוץ לירושלים. ועוד שנינו במשנה כי \u0003כל\u0004 אלה שדינם שהם מכלל","","\u0003הנקברין\u0004 — \u0003לא ישרפו,\u0004 וכל שדינם בשריפה — לא יקברו. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שהנקברים אינם נשרפים? ומשיבים: \u0003משום\u0004 שה\u0003נקברין אפרן אסור, ונשרפין אפרן מותר,\u0004 ומעתה יש לחשוש שאם ישרפו הנקברים, יבואו ליהנות מאפרם, ומשום כך נאסרה שריפתם של אלו. ושואלים: \u0003ו\u0004האם ה\u0003נקברין אפרן אסור? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003דם הנדה ובשר המת\u0004 המטמאים בין כשהם לחים ובין כשהם יבשים, ואולם במקרה \u0003ש\u0004יבשו ו\u0003נפרכו\u0004 (התפוררו כדי אפר) — הרי הם \u0003טהורין. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא שהרי אלו \u0003טהורין\u0004 מכל וכל, \u0003ו\u0004אף \u0003מותרין\u0004 בהנאה, והרי שאפרם מותר! ודוחים: \u0003לא\u0004 זו הכוונה, אלא הריהם \u0003טהורין\u0004 מלטמא, \u0003ו\u0004אולם \u0003אסורין\u0004 בהנאה.","","שב ו\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב פנחס\u0004 ממה ששנינו בברייתא אחרת: \u0003עולת העוף שנתמצה\u0004 (שנסחט וניתן) \u0003דמה\u0004 על קיר המזבח, כמצוות הקרבן — \u0003מוראתה\u0004 (הזפק) \u0003ו\u0004כן ה\u0003נוצה שלה\u0004 שאינם עולים על המזבח \u0003יצאו\u0004 בכך \u0003מידי\u0004 דין \u0003מעילה. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ש\u0003יצאו מידי מעילה\u0004 מכל וכל, שאין הם עוד בכלל הקדש, \u0003ו\u0004אף \u0003מותרין\u0004 בהנאה, אף שהם מכלל הנקברים (שכן הם מושלכים אל מזרח המזבח ונבלעים שם במקומם) והרי איפוא שאפרם של הנקברים הריהו מותר! ודוחים: \u0003לא,\u0004 אין זו הכוונה. אלא דינם שאכן \u0003יצאו מידי\u0004 דין \u0003מעילה, ו\u0004אולם \u0003אסורין\u0004 בהנאה. ושואלים עוד: \u0003ו\u0004האם דינם של ה\u0003נשרפין\u0004 של \u0003הקדש\u0004 ש\u0003אפרן מותר? והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל הנשרפין אפרם מותר, חוץ מאפר אשירה\u0004 (אילן שניטע או שנעבד לעבודה זרה). \u0003ואפר\u0004 של \u0003הקדש\u0004 — \u0003לעולם אסור! ו\u0004מסבירים תחילה מדוע מפרידה הברייתא בין דין אפר האשירה ואפר ההקדש, כנראה מלשונה של הברייתא. וטעם הדבר ש\u0003מיערב\u0004 \u0005[לערב]\u0006 את שתי ההלכות הללו ולשנותן כאחת \u0003הוא לא קעריב להו ותני להו\u0004 \u0005[לא עירב אותן ושנה אותן]\u0006 ביחד — \u0003משום\u0004 ש\u0003אשירה\u0004 יש אופן להתירה, שכן \u0003יש לה בטילה\u0004 (דרך ביטול) \u0003ב\u0004אמצעות \u0003גוי,\u0004 ואילו \u0003הקדש\u0004 — אין דרך להתירו, שכן \u0003אין לו בטילה עולמית.\u0004 \u0003קתני מיהא\u0004 \u0005[שנינו על כל פנים]\u0006 ש\u0003אפר הקדש לעולם אסור.\u0004","","","\u0003אמר רמי בר חמא:\u0004 השריפה אכן מתירה את אפר ההקדש, ואולם אין זה אלא כאשר באמצעות שריפה זו התקיים דין מעילה בהקדש זה ויצא בשל כך לחולין. ואילו זה ששנינו בברייתא זו שאפר ההקדש אסור, המדובר \u0003כגון\u0004 ש\u0003נפלה דליקה בעצי הקדש מאליה.\u0004 ומעתה, \u0003כיון דלא ידיע מאן\u0004 \u0005[שאין ידוע מי]\u0006 ששרף את עצי ההקדש, ונמצא \u0005דלא הוי איניש דלמעול\u0006 \u0005[שלא היה אדם\u0006 מסויים \u0005שביצע מעילה]\u0006 שתוציא את \u0003אפרן לחולין.\u0004","\u0003רב שמעיה אמר\u0004 הסבר אחר: \u0003כי תניא הא מתניתא\u0004 \u0005[כאשר נשנתה ברייתא זו]\u0006 שאפר הקדש אסור — הרי \u0003בתרומת הדשן\u0004 (שמרים הכהן בכל יום בשחרית מן הדשן שעל המזבח ומניחו על הרצפה ליד המזבח) היא \u0003תניא\u0004 \u0005[נשנתה],\u0006 שאפר זה אכן \u0003לעולם אסור\u0004 בהנאה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בדין תרומת הדשן \"...והרים את הדשן אשר תאכל האש את העולה על המזבח ושמו אצל המזבח\" (ויקרא ו, ג). ומן הנאמר בכתוב זה למדנו: \u0003\"ושמו\"\u0004 — שישימו \u0003בנחת,\u0004 עוד למדנו: \u0003\"ושמו\"\u0004 — \u0003כולו,\u0004 ועוד למדנו: \u0003\"ושמו\"\u0004 — \u0003שלא יפזר,\u0004 והרי שאף לאחר שריפתו יש בו קדושה ואסור בהנאה.",""]]};
